// Correcciones Simulia — tanda 3 — parte 8 de 8: fotos, protocolos, escalas y dudas (10 oct 2026)
// Pegar en mongosh (Compass) conectado a SimuLIA. Guarda copia de cada original antes de tocarlo.
const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97700b") }, {"long_answer": "Al alta hospitalaria se debe proporcionar a los pacientes información detallada sobre los medicamentos que deben tomar, indicando qué fármacos son nuevos, cuáles se han modificado o suspendido respecto a su tratamiento previo, su indicación, dosis, pauta, duración y posibles efectos adversos, idealmente por escrito y comprobando que lo han entendido. Limitar la información exclusivamente a la dosis y el intervalo es insuficiente para una transición segura. La disponibilidad de los medicamentos en el mercado o su precio no son la información clínica relevante que se recomienda trasladar al paciente para prevenir errores de medicación tras el alta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97700d") }, {"long_answer": "Si un paciente tiene que suspender su medicación por un efecto secundario, debe informar al personal sanitario de la situación para que se valore la reacción, se decida si es necesario modificar la dosis o cambiar de fármaco y, en su caso, se notifique la sospecha de reacción adversa. Seguir tomándola a pesar del efecto adverso, esperar a que cause daño o tomar decisiones sin consultar a los profesionales puede comprometer la seguridad del paciente y la eficacia del tratamiento. La comunicación con el equipo sanitario es una de las recomendaciones básicas para la participación segura del paciente en su medicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977015") }, {"long_answer": "El consenso internacional del Grupo de Trabajo Internacional sobre el Pie Diabético (IWGDF) recomienda para la prevención de úlceras un conjunto de medidas: educación del paciente, la familia y los profesionales, exploración periódica de los pies para identificar el pie de riesgo, uso de calzado apropiado, tratamiento de los factores de riesgo de ulceración y organización de los cuidados mediante equipos multidisciplinares. La realización de campañas o la reducción de la tasa de amputaciones son objetivos o indicadores de una estrategia de salud, no las recomendaciones clínicas del consenso. El documento sí menciona estas recomendaciones, por lo que la última opción es falsa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977017") }, {"long_answer": "El método básico recomendado para estratificar el riesgo del pie en personas con diabetes es el cribado de neuropatía con el monofilamento de Semmes-Weinstein de 10 g, prueba sencilla, barata y validada para detectar la pérdida de sensibilidad protectora, que se complementa con la inspección del pie y la exploración vascular mediante palpación de pulsos. La sensibilidad vibratoria con diapasón es una prueba complementaria, y la exploración vascular no instrumentada por sí sola no valora la neuropatía. Los dispositivos para cuantificar la pérdida de sensibilidad, como el biotensiómetro, no se consideran el método básico de cribado en la práctica habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977019") }, {"long_answer": "Los programas de educación terapéutica para personas con riesgo de pie diabético deben incluir de forma específica los cuidados básicos de higiene de los pies, el secado cuidadoso entre los dedos, la hidratación de la piel, el cuidado y corte adecuado de las uñas, la autoinspección diaria y la elección de calzado y calcetines adecuados. Aunque los conocimientos de nutrición o el manejo de la insulina forman parte de la educación diabetológica general, no son el contenido específico de la prevención del pie diabético. Las pruebas de diagnóstico de la diabetes no son un contenido de educación para el autocuidado del pie."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97701d") }, {"answer": 3, "option_4": "Mantener curas locales en domicilio y revisar la evolución en un mes", "long_answer": "Ante una úlcera de pie diabético con una infección que amenaza la extremidad o la vida del paciente y que requiere desbridamiento o cirugía, el documento indica la derivación urgente a un nivel asistencial 2-3 de referencia, donde un equipo multidisciplinar con cirugía puede realizar el desbridamiento quirúrgico, el drenaje o la revascularización necesarios. Iniciar antibiótico empírico o aplicar medidas de descarga son actuaciones necesarias, pero insuficientes por sí solas en este escenario y no deben retrasar la derivación. Mantener curas en domicilio con revisión diferida pondría en riesgo la extremidad y la vida del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977020") }, {"option_3": "Poliuria", "option_4": "Bradicardia sinusal aislada", "long_answer": "La hemólisis aguda durante la sesión de hemodiálisis, causada por problemas como un baño de diálisis hipotónico o sobrecalentado, contaminantes químicos o acodamientos de las líneas, puede manifestarse con hipertensión, dolor torácico o lumbar, disnea, náuseas, malestar general y sangre de aspecto oscuro o traslúcido en el circuito extracorpóreo. La hipertensión es por tanto una manifestación descrita. La fiebre alta no es característica de la hemólisis, sino que orienta a bacteriemia o reacción pirógena. La poliuria no aparece en estos pacientes, habitualmente oligoanúricos, y la bradicardia sinusal aislada no es un signo de hemólisis."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977021") }, {"long_answer": "El objetivo de detectar precozmente la sintomatología asociada a la hemólisis aguda en hemodiálisis es actuar con rapidez ante la aparición de un episodio: detener la bomba de sangre, pinzar las líneas sin retornar la sangre del circuito, avisar al nefrólogo, extraer analítica y tratar la posible hiperpotasemia y la anemia. Realizar una transfusión o pruebas de laboratorio son actuaciones que pueden formar parte del manejo posterior, pero no constituyen el objetivo principal de la detección precoz. La administración de insulina solo estaría indicada como tratamiento de una hiperpotasemia confirmada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97702f") }, {"long_answer": "Las enfermedades no transmisibles, como las enfermedades cardiovasculares, el cáncer, la diabetes y las enfermedades respiratorias crónicas, representan en la Región Europea de la OMS aproximadamente el 86% de los fallecimientos y el 77% de la carga de enfermedad, por lo que constituyen el principal problema de salud pública de la región. La cifra del 90% de los ictus no describe el impacto global de las ENT, y un 50% de la mortalidad infraestima su peso real. Afirmar que no tienen un impacto significativo es claramente falso, dada su contribución a la morbimortalidad y a la discapacidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977030") }, {"long_answer": "Según la Estrategia en Ictus del Sistema Nacional de Salud, entre el 80% y el 90% de los ictus serían evitables mediante el control adecuado de los factores de riesgo modificables, como la hipertensión arterial, el tabaquismo, la diabetes, la dislipemia, la fibrilación auricular, el sedentarismo, la obesidad o el consumo excesivo de alcohol. Las cifras del 50% o 60% infraestiman el potencial de la prevención, mientras que el 100% es irreal, ya que existen factores no modificables como la edad, el sexo o la predisposición genética que no pueden controlarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977034") }, {"answer": 3, "option_2": "Dislipemia", "long_answer": "La hipertensión arterial es el factor de riesgo modificable más importante tanto para el ictus isquémico como para el hemorrágico, con una relación directa y continua entre las cifras de presión arterial y el riesgo de ictus, y su control es la medida preventiva con mayor impacto. La diabetes mellitus y la dislipemia son factores de riesgo relevantes sobre todo para el ictus isquémico de origen aterotrombótico, pero no tienen el mismo peso en el hemorrágico. El consumo de alcohol en exceso aumenta el riesgo, especialmente de hemorragia, aunque su contribución global es menor que la de la hipertensión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97703c") }, {"option_4": "Ecografía Doppler transcraneal", "long_answer": "En pacientes con ictus isquémico de inicio desconocido, como el ictus del despertar, se recomienda la resonancia magnética de difusión-perfusión, que permite identificar el tejido ya infartado y el tejido en riesgo o penumbra isquémica, y valorar el desajuste difusión-FLAIR para estimar el tiempo de evolución y seleccionar candidatos a reperfusión. La TC craneal simple descarta hemorragia pero no valora la penumbra, y la angio-TC identifica la oclusión de grandes vasos, no el tejido salvable. La ecografía Doppler transcraneal estudia la circulación intracraneal, pero no delimita la penumbra isquémica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97703d") }, {"long_answer": "Uno de los factores de éxito más importantes de la trombectomía mecánica es conseguir la recanalización completa en un primer pase del dispositivo, el llamado efecto primer pase, que se asocia a mejores resultados funcionales, menor tiempo de procedimiento y menos complicaciones que cuando se requieren varios pases. La presión arterial baja no es un factor de éxito y puede comprometer la perfusión colateral. El tratamiento anticoagulante no condiciona el éxito del procedimiento y la cirugía cerebral no forma parte de la técnica, que es endovascular y se realiza por vía percutánea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977042") }, {"long_answer": "Entre las complicaciones de la trombectomía mecánica relacionadas con el acceso vascular, el hematoma en el punto de punción, que puede extenderse al retroperitoneo y causar shock hemorrágico, se considera una de las más graves, por lo que los cuidados de enfermería incluyen vigilar el punto de punción, los pulsos distales y los signos de sangrado. El vasoespasmo suele ser transitorio y responde a vasodilatadores. La disección arterial es menos frecuente y la fístula en el punto de punción es una complicación tardía y menos grave. Por ello el hematoma es la opción que mejor responde a la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97704a") }, {"long_answer": "La Estrategia en Ictus señala que menos del 10% de los pacientes con ictus llegan al hospital en los primeros 60 minutos desde el inicio de los síntomas, lo que limita el acceso a tratamientos de reperfusión cuya eficacia depende del tiempo. Por ello se insiste en la educación de la población para reconocer los síntomas de alarma y llamar al 112, y en la activación del Código Ictus extrahospitalario. Las cifras del 20%, más del 50% o casi el 100% sobrestiman la proporción de pacientes que llegan precozmente, que sigue siendo muy baja."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97704b") }, {"long_answer": "La unidad de ictus es una estructura geográficamente delimitada dentro del hospital, atendida por un equipo multidisciplinar coordinado y especializado, con protocolos de actuación y monitorización continua, que integra la asistencia al paciente con ictus en fase aguda. Ha demostrado reducir la mortalidad, la dependencia y la intensidad de las secuelas frente a la atención en una planta convencional. La atención primaria, el servicio de urgencias o el servicio de neurología participan en el proceso, pero por sí solos no constituyen el modelo asistencial integrado que ha demostrado estos beneficios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97704f") }, {"option_2": "Endocarditis infecciosa", "long_answer": "La neumonía es una de las complicaciones infecciosas más frecuentes en los pacientes con ictus y una de las principales causas de mortalidad en la fase aguda, favorecida por la disfagia, el bajo nivel de conciencia y la inmovilidad, que facilitan la broncoaspiración. Por ello se recomienda realizar un cribado de disfagia antes de iniciar la alimentación oral y mantener el cabecero elevado. La endocarditis infecciosa no es una complicación habitual del ictus, aunque puede ser su causa. La bronquitis y las infecciones de la piel son mucho menos relevantes en este contexto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977054") }, {"long_answer": "Los centros de ictus de referencia, además de las funciones de las unidades de ictus básicas, deben proporcionar procedimientos diagnósticos y terapéuticos más avanzados que no están disponibles en todos los centros, como la neurorradiología intervencionista para trombectomía mecánica, la neurocirugía o la cirugía vascular, y atender de forma continuada las 24 horas. Reducir la mortalidad intrahospitalaria, incrementar la independencia funcional al alta o disminuir complicaciones como úlceras por presión o tromboembolismos son objetivos de calidad aplicables a toda la atención al ictus, no la característica diferencial de los centros de referencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97705f") }, {"long_answer": "En la prevención secundaria del ictus o accidente isquémico transitorio en pacientes con fibrilación auricular no valvular, el tratamiento recomendado es la anticoagulación oral, que reduce de forma muy superior a la antiagregación el riesgo de nuevos eventos embólicos. El documento recoge los antagonistas de la vitamina K, y en la actualidad también los anticoagulantes orales de acción directa son una alternativa preferente en muchos pacientes. La antiagregación con AAS no se considera adecuada en esta indicación. El control lipídico y el seguimiento en consultas de neurología son medidas complementarias, pero no el tratamiento específico de la fibrilación auricular."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977065") }, {"long_answer": "La Estrategia de atención al parto normal señala que la posición que adoptan las mujeres durante el periodo expulsivo está fuertemente influida por normas culturales, más que por la evidencia científica, lo que explica la extensión del decúbito dorsal en el entorno hospitalario occidental frente a las posiciones verticales en otras culturas. Las recomendaciones médicas, las costumbres familiares o la presión social pueden influir, pero el documento destaca el peso de las normas culturales. Por ello se recomienda informar a la mujer y permitirle elegir libremente la postura que le resulte más cómoda durante el expulsivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977068") }, {"long_answer": "La Estrategia de atención al parto normal recoge que la revisión sistemática Cochrane sobre la posición materna en el periodo expulsivo y las recomendaciones de la OMS presentan limitaciones metodológicas, ya que los ensayos incluidos tienen calidad variable, ciertas heterogeneidades y sesgos, por lo que sus conclusiones deben interpretarse con cautela. Por ello no puede hablarse de resultados definitivos ni de una conclusión categórica. Aunque se describen beneficios y riesgos de las distintas posiciones, la característica que el documento destaca de esta evidencia son sus limitaciones metodológicas, que justifican recomendar la libre elección de postura por parte de la mujer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97706d") }, {"long_answer": "Según la Estrategia de atención al parto normal, la posición que adoptan las parturientas durante el periodo expulsivo está influida de forma predominante por normas culturales, de modo que en el ámbito hospitalario occidental se ha generalizado el decúbito dorsal o la posición semirrecostada, mientras que en otras culturas predominan las posturas verticales. Las recomendaciones médicas, las preferencias personales o las experiencias previas pueden influir, pero no son el factor predominante que destaca el documento. Por ello se recomienda informar y respetar la libertad de la mujer para adoptar la posición que prefiera durante el expulsivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97706e") }, {"long_answer": "La Estrategia de atención al parto normal señala que el principal argumento a favor del decúbito dorsal o la posición semirrecostada durante el expulsivo es que facilita al profesional el acceso al abdomen materno y al periné, permitiendo la auscultación fetal y la realización de maniobras, más que aportar beneficios a la mujer o al feto. De hecho, el decúbito supino puede comprimir los grandes vasos y dificultar la perfusión placentaria. No se ha demostrado que esta posición reduzca la duración del parto, disminuya el dolor ni mejore la circulación sanguínea, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977071") }, {"long_answer": "La revisión Cochrane recogida en la Estrategia de atención al parto normal muestra que las posiciones verticales o laterales durante el expulsivo se asocian a una reducción de partos asistidos y de episiotomías, pero también a un aumento de los desgarros perineales de segundo grado y de la pérdida sanguínea estimada superior a 500 ml. Por tanto, el aumento de desgarros perineales es la desventaja descrita. El aumento de partos asistidos es incorrecto, ya que estos disminuyen, y la menor práctica de episiotomías es una ventaja, no una desventaja. La reducción del sangrado tampoco es cierta, ya que este aumenta ligeramente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977077") }, {"long_answer": "La Estrategia de atención al parto normal considera la tasa de cesáreas un indicador de calidad de la atención materna y perinatal y recomienda investigar las causas del incremento de las tasas de cesárea y de su variabilidad entre centros y comunidades, ya que gran parte de esa variabilidad no se explica por diferencias clínicas entre las mujeres atendidas. No se recomienda mantener una tasa del 30%, muy superior a la considerada adecuada, ni aumentar las cesáreas, que conllevan mayor morbilidad materna y neonatal. Descartar la tasa de cesáreas como indicador de calidad contradice el planteamiento del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977079") }, {"long_answer": "La Estrategia de atención al parto normal recomienda en el posparto inmediato favorecer el contacto piel con piel y el inicio precoz de la lactancia materna, retrasando la realización de los procedimientos rutinarios no urgentes al recién nacido, como el peso, la exploración completa o la profilaxis, para no interrumpir ese primer contacto y la primera toma. Las demás opciones son contrarias a la estrategia: no promover prácticas eficaces de apoyo a la lactancia, no informar a las madres de sus ventajas o realizar procedimientos innecesarios que interfieran con ella dificultaría el establecimiento de la lactancia materna."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97707c") }, {"long_answer": "El empoderamiento de las mujeres en el proceso de parto implica que participen activamente en la toma de decisiones sobre su atención, con información adecuada, veraz y comprensible sobre las distintas opciones, de modo que puedan expresar sus preferencias, por ejemplo a través del plan de parto, y decidir de forma consensuada con los profesionales. Depender de las decisiones del personal sanitario o delegarlas en las autoridades corresponde a un modelo paternalista, contrario al empoderamiento. Del mismo modo, no recibir información adecuada impide a la mujer ejercer su autonomía en el proceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977081") }, {"long_answer": "Los documentos de atención al parto recomiendan a las mujeres cuestionar y observar con mirada crítica cualquier información sobre el parto procedente de los medios de comunicación, ya que con frecuencia transmiten mensajes sesgados, poco rigurosos o influidos por intereses comerciales. Es preferible contrastarla con los profesionales sanitarios y con fuentes basadas en la evidencia antes de tomar decisiones. Aceptar la información sin cuestionarla, no dudar de su veracidad o no analizarla críticamente expone a la mujer a decisiones poco informadas, por lo que estas opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977084") }, {"long_answer": "La toma de decisiones conjuntas o compartida entre usuarias y profesionales implica que el profesional comparta con la mujer información no sesgada y basada en la evidencia sobre las opciones disponibles, sus beneficios y riesgos, que se tengan en cuenta sus valores y preferencias y que ambos acuerden un plan de acción. Dejar que solo los profesionales decidan, no involucrar a las usuarias o excluirlas de la toma de decisiones corresponde a un modelo paternalista que la estrategia pretende superar, por lo que estas opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977087") }, {"long_answer": "La participación de las mujeres en la toma de decisiones sobre su atención sanitaria tiene como objetivo pasar de un modelo paternalista a un modelo de alianza, consenso y responsabilidad compartida entre la mujer y los profesionales, en el que ambos aportan conocimiento y la decisión final se acuerda respetando la autonomía de la usuaria. Adoptar o mantener el modelo paternalista, no modificar la relación clínica o excluir a las mujeres de las decisiones son planteamientos contrarios a los principios de la estrategia de atención al parto y a la ley de autonomía del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97708d") }, {"long_answer": "La toma de decisiones conjuntas en el proceso de atención sanitaria requiere incluir las preferencias de las usuarias, junto con información basada en la evidencia proporcionada por los profesionales, de forma que el plan de cuidados acordado se ajuste a los valores y expectativas de cada mujer. Proporcionar información sin evidencias documentadas resta rigor al proceso, mientras que no considerar las preferencias de las usuarias o impedir la comunicación entre usuarias y profesionales hace imposible una decisión compartida. Por ello la única opción coherente con este modelo de atención es la inclusión de las preferencias de las usuarias."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97708e") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977090") }, {"long_answer": "Se recomienda cuestionar y observar con mirada crítica cualquier información sobre salud, y en particular sobre el embarazo y el parto, procedente de los medios de comunicación, ya que puede estar sesgada, simplificada o condicionada por intereses comerciales, y contrastarla con profesionales y fuentes basadas en la evidencia. Confiar en su veracidad sin más, no cuestionarla o aceptar toda la información sin dudar puede llevar a expectativas poco realistas o a decisiones poco informadas, por lo que estas opciones no se ajustan a la recomendación del documento."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977091") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977093") }, {"question": "¿En qué evidencia se basa la recomendación de no realizar rasurado perineal sistemático a las mujeres de parto?", "option_1": "Únicamente en la opinión de expertos", "option_2": "En estudios observacionales sin grupo control", "option_3": "En ensayos clínicos aleatorizados y en las recomendaciones de la OMS", "option_4": "En series de casos de un único hospital", "long_answer": "La Estrategia de atención al parto normal recomienda no realizar de forma sistemática el rasurado perineal, basándose en ensayos clínicos aleatorizados, recogidos en una revisión sistemática Cochrane, que no muestran beneficios en la reducción de infecciones ni en la dehiscencia de suturas, y en las recomendaciones de la OMS, que lo consideran una práctica innecesaria. Además, el rasurado produce molestias, irritación y microlesiones cutáneas. La recomendación no se basa únicamente en la opinión de expertos ni en estudios observacionales sin grupo control o series de casos, que tendrían un nivel de evidencia mucho menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97709a") }, {"option_1": "Mayor riesgo de parto vaginal instrumental", "long_answer": "Según la evidencia recogida en la Estrategia de atención al parto normal, la analgesia epidural es el método más eficaz para aliviar el dolor del parto, pero se asocia a un mayor riesgo de parto vaginal instrumental, a una prolongación de la segunda etapa del parto, a mayor necesidad de oxitocina y a fiebre materna intraparto. No se ha demostrado un aumento de la tasa de cesáreas ni de la depresión posparto, y no reduce la duración del trabajo de parto, sino que puede prolongarlo. Por ello la mujer debe recibir esta información para decidir sobre su uso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a0") }, {"long_answer": "La Estrategia en Salud Cardiovascular del SNS considera la salud cardiovascular un reto social y sanitario de primer orden no solo por su elevada morbimortalidad, sino por su impacto en la economía y en el mercado laboral, debido al gasto sanitario que generan las enfermedades cardiovasculares y a las pérdidas de productividad por incapacidad temporal, discapacidad y muertes prematuras en edad laboral. No afecta únicamente a la población de edad avanzada. La alta prevalencia de cardiopatías y de factores de riesgo es una causa del problema, pero el documento subraya su dimensión social y económica para justificar ese carácter de reto prioritario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a2") }, {"long_answer": "Según la Estrategia en Salud Cardiovascular, en 2019 la incidencia anual de enfermedades cardiovasculares en España fue de aproximadamente un caso por cada 100 personas, lo que refleja la enorme carga que suponen estas patologías para la población y el sistema sanitario y justifica la priorización de las medidas de prevención y promoción de hábitos de vida saludables. Las cifras de un caso por cada 50 personas sobrestiman la incidencia descrita, mientras que uno por cada 200 o por cada 300 personas la infraestiman. Este dato sitúa a las enfermedades cardiovasculares entre los principales problemas de salud del país."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770a6") }, {"long_answer": "La Estrategia en Salud Cardiovascular señala que los factores de desigualdad de género contribuyen al estancamiento en la reducción del impacto de las enfermedades cardiovasculares en las mujeres durante la última década. Entre ellos destacan la infrarrepresentación femenina en los ensayos clínicos, el menor reconocimiento de sus síntomas, a menudo atípicos, el retraso diagnóstico, el menor uso de tratamientos basados en la evidencia y la sobrecarga derivada del rol de cuidadoras. El acceso a la atención, la concienciación o los programas de prevención influyen, pero el documento atribuye este estancamiento a las desigualdades de género."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ab") }, {"long_answer": "La Estrategia en Salud Cardiovascular identifica el empoderamiento de las mujeres como un mecanismo fundamental para alcanzar la equidad de género en salud cardiovascular, ya que les permite conocer sus factores de riesgo y síntomas, reconocer los signos de alarma, demandar una atención adecuada y participar activamente en las decisiones sobre su salud. La intervención de los gobiernos, la inversión en tecnología o la educación sobre hábitos saludables son medidas útiles, pero no se señalan como el mecanismo fundamental para corregir las desigualdades de género en este ámbito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770ac") }, {"long_answer": "Entre los aspectos relacionados con el papel social que influyen en la salud cardiovascular de las mujeres, la Estrategia en Salud Cardiovascular destaca la conciliación familiar y laboral, ya que la doble jornada y el rol de cuidadoras generan sobrecarga física y mental, estrés crónico y menos tiempo para el autocuidado, la actividad física o la asistencia a revisiones. El acceso a la educación, la participación en actividades deportivas o la profesión elegida pueden influir en la salud, pero no se señalan como el aspecto ligado al rol social de género que se recoge en la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770b7") }, {"question": "Según la Estrategia en Salud Cardiovascular, ¿qué dato de prevalencia de la insuficiencia cardiaca (IC) se describe en España?", "long_answer": "La Estrategia en Salud Cardiovascular recoge que la prevalencia de la insuficiencia cardiaca en España alcanza el 16,1% entre las personas mayores de 75 años, lo que pone de manifiesto su estrecha relación con el envejecimiento y su gran impacto en hospitalizaciones, consumo de recursos y calidad de vida. La cifra del 1,2% en hombres no corresponde al dato descrito. Las 30.000 paradas cardiacas extrahospitalarias y las alrededor de 20.000 paradas cardiacas intrahospitalarias son datos de parada cardiaca, no de insuficiencia cardiaca, por lo que no responden a la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770bc") }, {"long_answer": "Dentro de la línea de gestión del conocimiento, investigación e innovación, la Estrategia en Salud Cardiovascular identifica como punto crítico la necesidad de promover proyectos de I+D+i que respondan a las necesidades de salud cardiovascular existentes, fomentando la colaboración entre grupos y facilitando la transferencia de los resultados a la práctica asistencial. Mejorar el diagnóstico precoz de la insuficiencia cardiaca o de las valvulopatías prevalentes corresponde a la línea de atención a las enfermedades cardiovasculares, y dotar a los ciudadanos de competencias de autocuidado pertenece al ámbito de promoción y capacitación ciudadana, no al de investigación e innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c4") }, {"long_answer": "Según el mapa estratégico de la Estrategia en Salud Cardiovascular, el objetivo estratégico de mayor autonomía y capacitación de los agentes implicados se despliega en tres líneas de actuación, orientadas a capacitar tanto a la ciudadanía y a los pacientes, para el autocuidado y la gestión de su enfermedad, como a los profesionales, para mejorar la calidad de la atención. Las cifras de dos, cuatro o cinco líneas no corresponden a la estructura recogida en el documento para este objetivo, por lo que la opción correcta es la de tres líneas de actuación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c5") }, {"long_answer": "Según el mapa estratégico de la Estrategia en Salud Cardiovascular, el objetivo estratégico de mejora de los procesos sociales y profesionales sobre estilos de vida saludables y de la atención a la persona con enfermedad cardiovascular es el que reúne más contenido operativo, con 19 ámbitos de actuación en materia de proceso u organización. Estos ámbitos abarcan desde la promoción de hábitos saludables y la prevención hasta la atención en las distintas patologías y la rehabilitación. Las cifras de 15, 17 o 21 ámbitos no se corresponden con el número recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771f9") }, {"option_3": "Motocicletas con cilindrada máxima de 125 cm³", "long_answer": "El permiso A1, que puede obtenerse a partir de los 16 años, autoriza a conducir motocicletas con una cilindrada máxima de 125 cm³, una potencia máxima de 11 kW y una relación potencia/peso no superior a 0,1 kW/kg, así como triciclos de motor de hasta 15 kW. Las motocicletas de hasta 35 kW, unos 47 CV, corresponden al permiso A2, que requiere 18 años. Los ciclomotores y cuadriciclos ligeros se conducen con la licencia o permiso AM, a partir de los 15 años, por lo que no son el tipo de vehículo característico del permiso A1."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771fe") }, {"long_answer": "Las recomendaciones de seguridad vial para la infancia señalan que, al caminar con niños y niñas de 6 a 12 años, se deben fomentar comportamientos saludables y seguros como ir caminando, cruzar siempre por los pasos señalizados y esperar a que el semáforo esté en verde para los peatones, mirando a ambos lados antes de cruzar. Los adultos deben actuar como modelo, ya que los menores aprenden por imitación. Correr, cruzar por cualquier lugar, no respetar el semáforo, caminar por la carretera o ignorar las señales de tráfico son conductas de riesgo que favorecen los atropellos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977203") }, {"long_answer": "Las recomendaciones de seguridad vial indican que al conducir con niños y niñas en el coche se debe evitar fumar, ya que expone a los menores al humo del tabaco en un espacio cerrado y además distrae al conductor, así como la conducción agresiva, que aumenta el riesgo de accidente y transmite un mal modelo de conducta. Conducir con calma, usar siempre el cinturón y los sistemas de retención adecuados y respetar las normas de tráfico son comportamientos recomendados, no conductas que deban evitarse, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977206") }, {"option_3": "En brazos de un adulto en el asiento trasero", "long_answer": "La recomendación de seguridad vial para niños y niñas es que viajen a contramarcha el mayor tiempo posible, al menos hasta los 15 meses y preferiblemente hasta los 4 años, ya que en esta posición la cabeza, el cuello y la columna quedan mucho más protegidos ante una colisión frontal, la más frecuente y grave. Viajar en brazos de un adulto es muy peligroso aunque sea en el asiento trasero, ya que es imposible retener al menor en un impacto. Viajar sin sistema de retención infantil está prohibido, y el asiento delantero solo se admite en casos excepcionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977207") }, {"long_answer": "Siempre que se instale una sillita a contramarcha en el asiento del copiloto es obligatorio desactivar el airbag frontal del acompañante, ya que en caso de colisión el airbag se despliega a gran velocidad e impactaría directamente contra el respaldo de la silla, pudiendo causar lesiones graves o mortales al niño o la niña. Esta obligación no depende del tamaño o la edad del menor, por lo que la opción que la limita a los niños muy pequeños es incorrecta, al igual que afirmar que nunca es necesario o que no importa si el airbag está activado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977210") }, {"long_answer": "La utilización de nirsevimab, un anticuerpo monoclonal de vida media prolongada frente a la proteína F del VRS, ha reducido de forma notable la morbimortalidad por este virus en menores de 1 año, con una disminución importante de las hospitalizaciones, los ingresos en UCI y las consultas por bronquiolitis en las temporadas en que se ha aplicado de forma sistemática en España. Los datos de efectividad muestran un impacto claro y positivo, por lo que las opciones que indican ausencia de impacto, empeoramiento de la situación o ningún cambio observado son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977211") }, {"long_answer": "La primera vacuna frente al VRS autorizada para su uso en embarazadas, la vacuna RSVpreF (Abrysvo), recibió la autorización de comercialización de la Comisión Europea el 23 de agosto de 2023, para la protección pasiva de los lactantes desde el nacimiento hasta los 6 meses de edad mediante la vacunación materna entre las semanas 24 y 36 de gestación, así como para adultos de 60 años o más. Las fechas de enero de 2023, marzo de 2024 y noviembre de 2024 no corresponden a esta autorización, por lo que son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977216") }, {"option_1": "La edad avanzada", "option_2": "La ubicación geográfica", "option_3": "La deprivación socioeconómica", "option_4": "La exposición al sol", "long_answer": "El documento sobre la enfermedad por VRS recoge la deprivación socioeconómica como un posible factor de riesgo de mayor morbilidad, ya que se asocia a condiciones de hacinamiento, peor acceso a la atención sanitaria, exposición al humo del tabaco y mayor frecuencia de comorbilidades. En población infantil, la mayor carga se concentra en los lactantes pequeños, por lo que la edad avanzada no es el factor de riesgo planteado en este contexto. La ubicación geográfica influye en la estacionalidad pero no se describe como factor de riesgo individual, y la exposición al sol no guarda relación con la infección por VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97721f") }, {"long_answer": "Según el documento de recomendaciones frente al VRS, la vacuna RSVpreF administrada a embarazadas mostró en el ensayo pivotal una eficacia del 55,3% frente a la infección del tracto respiratorio inferior con atención médica por VRS en los lactantes a los 180 días de vida. La eficacia fue mayor frente a la enfermedad grave y en los primeros 90 días, y disminuye con el tiempo a medida que descienden los anticuerpos transferidos por vía placentaria. Las cifras de 54,8%, 64,1% y 77,8% no corresponden a este resultado concreto a los 180 días."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977224") }, {"long_answer": "Los estudios realizados en España tras la introducción sistemática de nirsevimab estimaron una efectividad de aproximadamente el 78% en la reducción de las hospitalizaciones por VRS en los menores con indicación de inmunización al nacimiento o en su primera temporada, según recoge el documento de recomendaciones. Esta elevada efectividad en condiciones reales confirma los resultados de los ensayos clínicos y respalda la estrategia de inmunización universal de los lactantes. Las cifras del 55%, 70% y 87% no se corresponden con la estimación recogida en el documento para este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977238") }, {"long_answer": "Según el documento de recomendaciones frente al VRS, la efectividad observada de nirsevimab en la prevención de la enfermedad grave y la hospitalización por VRS en la población infantil fue del 76,4%, lo que confirma en condiciones reales su elevado beneficio para reducir la carga asistencial en las temporadas epidémicas. Las cifras del 64,2%, 72,3% y 80,1% no corresponden a la estimación concreta recogida en el documento para este indicador, por lo que son incorrectas, aunque todas ellas reflejan el rango de alta efectividad descrito en los distintos estudios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977239") }, {"question": "¿En qué temporada España recomendó y empleó por primera vez nirsevimab de forma sistemática en recién nacidos y lactantes para reducir la morbimortalidad debida al VRS?", "option_3": "2021-2022", "answer": 2, "long_answer": "España fue uno de los primeros países en recomendar y emplear de forma sistemática el anticuerpo monoclonal nirsevimab en recién nacidos y lactantes durante la temporada 2023-2024, con una campaña iniciada en octubre de 2023 dirigida a los nacidos durante la temporada y a los menores de 6 meses al inicio de la misma, además de los grupos de riesgo. La estrategia se mantuvo en temporadas posteriores. En 2021-2022 y 2022-2023 el fármaco aún no estaba disponible para un uso poblacional, y 2025-2026 no fue la temporada de introducción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97723c") }, {"long_answer": "En los ensayos clínicos de la vacuna RSVpreF (Abrysvo) en embarazadas, el evento adverso notificado con más frecuencia fue el dolor en el lugar de administración, una reacción local generalmente leve o moderada y de corta duración. Otros efectos como la cefalea o las mialgias fueron también frecuentes, pero menos que el dolor local. La fiebre fue poco habitual, con frecuencias similares a las del grupo placebo, y la diarrea no se describe como un efecto adverso relevante. El perfil de seguridad de la vacuna se considera aceptable, aunque se vigila el posible riesgo de parto prematuro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977240") }, {"option_2": "Inmunización pasiva con anticuerpo monoclonal (nirsevimab) en lactantes", "long_answer": "La estrategia de prevención de la enfermedad grave por VRS en la población infantil en España se ha basado en la inmunización pasiva de los lactantes con el anticuerpo monoclonal nirsevimab, dirigida a los nacidos durante la temporada, a los menores de 6 meses al inicio de esta y a los niños con factores de riesgo hasta los 24 meses. La vacunación de embarazadas como estrategia única no fue la recomendación adoptada, y la vacunación de niños de 2 a 5 años o exclusivamente de prematuros no se contempla, ya que no existen vacunas autorizadas para la población pediátrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977241") }, {"long_answer": "El documento señala que, ante cualquier cambio en la estrategia de prevención de la enfermedad por VRS en la población infantil, como la incorporación de la vacunación materna o la modificación de los grupos diana, es primordial desarrollar estrategias de educación e información dirigidas a profesionales sanitarios y familias, para mantener la confianza, la aceptación y las coberturas alcanzadas. Ampliar el número de dosis, cerrar centros educativos o incrementar las camas hospitalarias no son medidas que el documento considere prioritarias ante un cambio de estrategia, y en algunos casos no tienen relación con la prevención del VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977245") }, {"question": "¿Aproximadamente cuántas hospitalizaciones anuales relacionadas con el VRS se estiman en personas de 60 o más años en los países de altos ingresos?", "option_1": "2.000", "option_2": "50.000", "option_3": "787.000", "option_4": "50.000.000", "long_answer": "Según las estimaciones recogidas en el documento de recomendaciones de vacunación frente al VRS en población adulta, en los países de altos ingresos se producen cada año alrededor de 787.000 hospitalizaciones relacionadas con el VRS en personas de 60 o más años, lo que pone de manifiesto la importante carga de enfermedad que este virus genera en los adultos mayores, a menudo infradiagnosticada. Las cifras de 2.000 o 50.000 hospitalizaciones infraestiman claramente el problema, y la de 50 millones es desproporcionada respecto a la población de estos países."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977248") }, {"long_answer": "La proteína F o de fusión del VRS es el principal determinante antigénico que induce la producción de anticuerpos neutralizantes, ya que media la fusión de la envoltura vírica con la membrana celular y está muy conservada entre los subtipos A y B. Su conformación prefusión es la diana de las vacunas actuales y del anticuerpo monoclonal nirsevimab. Las proteínas N, M y L son internas o estructurales y no inducen anticuerpos neutralizantes relevantes: la N forma la nucleocápside, la M es la proteína de matriz y la L es la polimerasa viral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97724d") }, {"answer": 3, "option_4": "Producir anticuerpos neutralizantes frente a la proteína F", "long_answer": "Las células T CD8+ específicas del VRS son linfocitos citotóxicos cuya función principal es eliminar directamente las células infectadas por el virus mediante la liberación de perforinas y granzimas, contribuyendo así a la resolución de la infección. La producción de anticuerpos neutralizantes frente a la proteína F corresponde a los linfocitos B y células plasmáticas, no a las células T CD8+. La producción de interferones de tipo I y la respuesta inmunitaria innata dependen fundamentalmente de células epiteliales, macrófagos, células dendríticas y células NK, que intervienen antes de la respuesta adaptativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97724e") }, {"option_1": "Neutralizar el virus, impidiendo la infección y contribuyendo a su eliminación", "long_answer": "Los anticuerpos neutralizantes específicos frente al VRS, dirigidos principalmente contra la proteína F, se unen al virus e impiden su fusión con las células del epitelio respiratorio, bloqueando la infección y contribuyendo a la eliminación vírica. Su presencia, ya sea por infección previa, por transferencia materna o por anticuerpos monoclonales como nirsevimab, se asocia a protección frente a la enfermedad grave. No promueven la replicación viral, no tienen como función inducir inflamación y no activan la respuesta inmune innata, que actúa de forma inespecífica antes de la respuesta adaptativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977255") }, {"long_answer": "El documento de recomendaciones de vacunación frente al VRS en adultos estima alrededor de 14.892 hospitalizaciones anuales por infección por VRS en adultos mayores de 20 años en España, con la mayor parte concentrada en las personas de edad avanzada y con comorbilidades. Esta cifra refleja una carga de enfermedad considerable y probablemente infraestimada, ya que el VRS no se busca de forma sistemática en los adultos hospitalizados con infección respiratoria. Las cifras de 10, 15 o 20 hospitalizaciones son irrealmente bajas para un país con la población de España."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977257") }, {"long_answer": "Según el documento de recomendaciones de vacunación frente al VRS en población adulta, la mayor carga de enfermedad a nivel poblacional entre los adultos se observa en el grupo de 75 a 79 años, en el que confluyen una elevada incidencia de hospitalización por VRS y un tamaño poblacional todavía amplio. En edades más avanzadas el riesgo individual sigue aumentando, pero el número de personas es menor, mientras que en los grupos de 65 a 74 años el riesgo individual es inferior. Por ello las opciones de 65-69, 70-74 y 80-84 años no corresponden al dato descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977259") }, {"long_answer": "Según el documento de recomendaciones de vacunación frente al VRS en población adulta, el riesgo individual de hospitalización por VRS en las personas de 70 a 79 años se estima en 5,2 por 100.000 habitantes, una cifra superior a la de los adultos más jóvenes e inferior a la de los mayores de 80 años, en quienes el riesgo es máximo. Este gradiente con la edad, unido a la inmunosenescencia y a la mayor presencia de comorbilidades, fundamenta la priorización de los grupos de mayor edad en las recomendaciones de vacunación. Las cifras de 3,5, 7,5 y 11 por 100.000 no corresponden al dato descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97725d") }, {"long_answer": "El documento de recomendaciones frente al VRS en adultos señala que la incidencia anual de infección por VRS en adultos de 60 o más años institucionalizados se sitúa en torno al 6%, superior a la descrita en los mayores que viven en la comunidad, debido a la convivencia en espacios compartidos, la fragilidad y la elevada prevalencia de enfermedades crónicas. Este dato apoya que las personas que residen en centros de mayores sean un grupo prioritario para la vacunación. Las cifras del 2%, 4% y 8% no se corresponden con la incidencia recogida en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977263") }, {"long_answer": "En el ensayo pivotal de la vacuna RSVPreF3 (Arexvy) en adultos de 60 o más años, recogido en el documento de recomendaciones, la eficacia frente a la enfermedad del tracto respiratorio inferior grave por VRS durante la segunda temporada fue del 78,8%, inferior a la observada en la primera temporada pero todavía elevada, lo que indica una protección mantenida durante al menos dos temporadas tras una única dosis. La cifra del 94,1% corresponde a la protección frente a enfermedad grave en la primera temporada, y las del 55,9% y 67,2% no corresponden al dato descrito para la segunda temporada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977264") }, {"long_answer": "Según los datos recogidos en el documento de recomendaciones, la eficacia de la vacuna RSVPreF3 (Arexvy) frente a la enfermedad del tracto respiratorio inferior por VRS en el grupo de 70 a 79 años fue del 74,9%, inferior a la observada en el grupo de 60 a 69 años pero aún elevada, lo que respalda su utilidad en las personas de más edad, que son las que concentran mayor riesgo de complicaciones. Las cifras del 81%, 93,8% y 65,4% no se corresponden con la eficacia descrita específicamente para este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977269") }, {"long_answer": "En el ensayo clínico de la vacuna de ARNm mRNA-1345 (mRESVIA) en personas de 60 o más años, recogido en el documento de recomendaciones, la eficacia frente a la enfermedad del tracto respiratorio inferior por VRS con dos o más síntomas fue del 56,7% en el seguimiento ampliado, con una disminución respecto a la estimación inicial a corto plazo, lo que refleja una pérdida de protección con el tiempo más marcada que con otras vacunas. Las cifras del 50,3%, 49,9% y 37,5% no corresponden al dato descrito para este indicador concreto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97726b") }, {"long_answer": "El documento de recomendaciones de vacunación frente al VRS recoge que, en los datos de farmacovigilancia poscomercialización, la tasa de notificación de casos de síndrome de Guillain-Barré con la vacuna Abrysvo fue de aproximadamente 5 por millón de dosis administradas, una señal de seguridad que llevó a incluir este posible riesgo en la información de la vacuna, aunque el balance beneficio-riesgo en adultos mayores se mantiene favorable. Las cifras de 1,5, 0,43 y 0,54 por millón no se corresponden con la tasa notificada para Abrysvo en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977270") }, {"long_answer": "A partir de la temporada 2021-2022 España estableció la vigilancia de la infección por VRS dentro del Sistema de Vigilancia de Infección Respiratoria Aguda (SiVIRA), que integra la vigilancia centinela de infecciones respiratorias agudas en atención primaria y de infecciones respiratorias agudas graves en hospitales, con estudio virológico de gripe, SARS-CoV-2 y VRS. Este sistema permite estimar la incidencia y la gravedad de la infección y evaluar el impacto de las estrategias de inmunización. Las demás denominaciones, referidas a infección respiratoria crónica, epidemias respiratorias o infecciones virales en general, no corresponden a ningún sistema de vigilancia oficial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977273") }, {"long_answer": "La vacuna RSVpreF (Abrysvo), bivalente frente a la proteína F prefusión de los subtipos A y B, es la única de las citadas autorizada para su uso en embarazadas, entre las semanas 24 y 36 de gestación, con el fin de proteger al lactante mediante la transferencia transplacentaria de anticuerpos durante sus primeros meses de vida. También está autorizada en adultos de 60 o más años. Las vacunas RSVPreF3 (Arexvy) y mRNA-1345 (mRESVIA) están autorizadas únicamente en población adulta, principalmente de 60 o más años, y no en el embarazo, por lo que la última opción también es falsa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977277") }, {"long_answer": "El documento sobre vacunación frente al VRS en población adulta señala que su introducción supondría un aumento de la carga asistencial, especialmente en atención primaria y en residencias, que coincidiría con las campañas de vacunación frente a gripe y COVID-19, por lo que deben planificarse los recursos humanos, la logística, la coadministración y el registro de las dosis. El coste de las vacunas o su eficiencia son aspectos de evaluación económica, no asistenciales o logísticos, y la disponibilidad de vacunas para toda la población no es el planteamiento, ya que la recomendación se dirige a grupos de mayor riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977278") }, {"long_answer": "Asegurar un acceso equitativo a la vacunación frente al VRS en la población adulta es esencial para mejorar la aceptación y la cobertura de la vacuna, evitando que las barreras económicas, geográficas o sociales impidan su llegada a los grupos más vulnerables, que suelen ser los de mayor riesgo de enfermedad grave. Las ventajas económicas no son el motivo de la equidad. El VRS es un virus, por lo que la vacunación no actúa sobre la resistencia a los antibióticos. Aunque la reducción de casos es un objetivo de la vacunación, no es la razón específica por la que se requiere un acceso equitativo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97727c") }, {"long_answer": "La Organización Mundial de la Salud define la seguridad del paciente como la ausencia de daño innecesario, real o potencial, asociado a la asistencia sanitaria, es decir, la reducción del riesgo de daño evitable a un mínimo aceptable. Esta definición es la base de las estrategias de seguridad del paciente del Sistema Nacional de Salud. La reducción de costes y la mejora de la eficiencia pueden ser consecuencias de una atención más segura, pero no definen el concepto, y la prevención de enfermedades infecciosas pertenece al ámbito de la salud pública, aunque las infecciones asociadas a la asistencia sean un aspecto de la seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977281") }, {"long_answer": "El tercer reto mundial por la seguridad del paciente de la OMS, Medicación sin daño, lanzado en 2017, se propuso reducir en un 50% los daños graves y evitables asociados a los medicamentos en un plazo de cinco años, actuando sobre los pacientes, los profesionales, los medicamentos y los sistemas y prácticas de medicación, con especial atención a las situaciones de alto riesgo, la polimedicación y las transiciones asistenciales. Los plazos de tres, siete o diez años no se corresponden con el objetivo fijado por la OMS para este reto mundial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977284") }, {"long_answer": "En los pacientes pediátricos confluyen varios factores que favorecen los incidentes con medicamentos: la necesidad de realizar cálculos individualizados para ajustar la dosis al peso o la superficie corporal, la falta de disponibilidad de presentaciones y formas farmacéuticas pediátricas, que obliga a manipular presentaciones de adultos, y las diferencias farmacocinéticas y farmacodinámicas propias de cada etapa del desarrollo, que modifican la respuesta al fármaco. Como todos estos factores se recogen en los documentos de seguridad del paciente pediátrico, la opción que los engloba es la correcta, y cada una de las opciones por separado resulta incompleta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977288") }, {"long_answer": "Los pacientes pediátricos presentan diferencias en la farmacocinética, es decir, en la absorción, distribución, metabolismo y eliminación de los fármacos, y en la farmacodinámica, por la inmadurez de órganos y sistemas y los cambios propios del crecimiento, lo que modifica la respuesta a los medicamentos respecto a los adultos. Por ello no son pequeños adultos, y sus dosis deben calcularse de forma individualizada. No es cierto que tengan menor sensibilidad a los efectos secundarios ni mayor tolerancia a los eventos adversos; de hecho, son más vulnerables a ellos, y afirmar que no existen diferencias significativas es incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97728c") }, {"long_answer": "Se establece una lista específica de medicamentos de alto riesgo para pacientes pediátricos con el fin de priorizar las actividades de mejora e implantar prácticas seguras dirigidas a aquellos fármacos que, en esta población, tienen mayor probabilidad de causar daños graves si se produce un error, teniendo en cuenta sus particularidades farmacológicas y de dosificación. El objetivo no es reducir el uso de medicamentos ni mejorar la eficiencia del sistema, y los niños no están excluidos de las listas generales, sino que estas se complementan con una relación adaptada a sus características."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97728d") }, {"long_answer": "La lista de medicamentos de alto riesgo de un centro sanitario debe revisarse y actualizarse periódicamente por varios motivos: para incluir nuevos medicamentos de alto riesgo que se incorporen a la guía farmacoterapéutica, para excluir aquellos que ya no supongan un riesgo elevado gracias a las prácticas implantadas o a cambios en su uso, y para adaptarla a las características del centro y a los incidentes notificados en él. Como todas estas razones son correctas, la opción que las engloba es la respuesta adecuada, mientras que cada una por separado resulta incompleta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977290") }, {"long_answer": "Las recomendaciones del Ministerio de Sanidad sobre medicamentos de alto riesgo establecen que cada centro sanitario debe elaborar su propia lista, tomando como referencia las listas nacionales e internacionales, pero adaptándola a los medicamentos incluidos en su guía farmacoterapéutica, a los tipos de pacientes que atiende y a los incidentes registrados en el propio centro. Utilizar la lista de otro centro sin modificaciones no reflejaría estas particularidades, y limitarse a consultar y adaptar la de otro centro no sustituye a un proceso propio. No disponer de lista impediría priorizar las prácticas seguras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977292") }, {"long_answer": "Según las recomendaciones sobre medicamentos de alto riesgo, las listas de cada centro sanitario deben revisarse y actualizarse al menos cada dos años, o antes si se incorporan nuevos medicamentos o se detectan incidentes relevantes, para que se mantengan adaptadas a la realidad asistencial del centro. Una revisión anual no es el plazo mínimo establecido, y un intervalo de tres años sería excesivo ante la rápida incorporación de nuevos fármacos. Vincular la revisión a los cambios en el personal sanitario no tiene fundamento, ya que el riesgo depende del medicamento y su circuito de utilización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977293") }, {"long_answer": "Los centros sanitarios deben implantar múltiples prácticas seguras en todas las fases del circuito de utilización de los medicamentos de alto riesgo, desde la selección, adquisición y almacenamiento hasta la prescripción, validación, preparación, dispensación, administración y seguimiento, ya que los errores pueden producirse en cualquiera de ellas y una sola barrera es insuficiente. Limitarse a la fase de administración deja sin proteger el resto del proceso. Las prácticas seguras deben actualizarse y reforzarse de forma continua, por lo que la tercera opción es falsa, y la cuarta también al existir una opción correcta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977294") }, {"long_answer": "La jerarquía de efectividad es una clasificación de las prácticas de prevención de errores de medicación según su capacidad para reducirlos. En el nivel más alto se sitúan las funciones forzadas y las restricciones, seguidas de la automatización y la estandarización, mientras que las medidas que dependen de la memoria o la atención humana, como la formación o las normas y políticas, son las menos eficaces. No es un modelo para clasificar medicamentos de alto riesgo, ni una lista de prácticas basadas en la memoria humana, ni una clasificación según su impacto en la eficiencia del sistema sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97729c") }, {"option_2": "Permitir que cada profesional prepare las mezclas según su propio criterio de dilución", "option_3": "Preparar las diluciones en la unidad a partir de presentaciones de adultos sin verificación", "long_answer": "Para reducir los errores en la preparación de medicamentos de alto riesgo en pediatría se recomienda promover la elaboración centralizada de las mezclas parenterales en los servicios de farmacia hospitalaria, utilizando concentraciones estandarizadas, ya que se realizan en condiciones controladas, con validación y técnica aséptica, y se evitan cálculos y diluciones en las unidades. Dejar las diluciones al criterio de cada profesional o prepararlas a partir de presentaciones de adultos sin verificación aumenta el riesgo de error. Las bombas de infusión inteligentes son una práctica segura de la fase de administración, no de la preparación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97729e") }, {"long_answer": "Las prácticas seguras con aminoglucósidos recomiendan disponer de protocolos actualizados para el inicio, la duración y el seguimiento del tratamiento que incluyan los ajustes de dosis en pacientes con bajo peso, obesidad o insuficiencia renal, junto con la monitorización de niveles plasmáticos y de la función renal, dado su estrecho margen terapéutico y su riesgo de nefrotoxicidad y ototoxicidad. Las interacciones, la posología general o el tiempo de administración son informaciones útiles, pero el aspecto que se destaca como contenido esencial de estos protocolos es la individualización de la dosis según el peso y la función renal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a0") }, {"long_answer": "Entre los errores más frecuentes con insulinas destaca la confusión entre los distintos tipos, concentraciones y preparados, por ejemplo entre insulinas rápidas y basales, entre presentaciones de 100 y 300 UI/ml o entre nombres comerciales similares, lo que puede provocar hipoglucemias o hiperglucemias graves. Por ello se recomienda la prescripción por nombre comercial, evitar abreviaturas como U y estandarizar los preparados disponibles. La falta de ajuste en ayunas, la programación incorrecta de bombas o los errores en el tratamiento de la hiperpotasemia también se describen, pero no son el error más frecuente que se recoge en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a3") }, {"long_answer": "Entre las prácticas de prevención de errores con nutrición parenteral se recomienda administrarla mediante bombas de infusión inteligentes con bibliotecas de fármacos y límites de seguridad, que ayudan a evitar errores en la velocidad o el volumen de infusión. Las demás opciones son contrarias a las recomendaciones de seguridad: sí debe evaluarse el etiquetado y envasado de los productos utilizados en su preparación, establecerse un límite de osmolaridad para la infusión por vía periférica, para prevenir flebitis, y promoverse el uso de sistemas automatizados de elaboración de mezclas, que reducen los errores de preparación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a4") }, {"long_answer": "Entre las recomendaciones para el uso seguro de opioides en pediatría dirigidas a los profesionales sanitarios figura realizar un doble chequeo independiente cuando se preparen mezclas intravenosas de opioides, para verificar el fármaco, la concentración, la dosis calculada según el peso y la dilución, ya que los errores en estos cálculos pueden causar depresión respiratoria grave. Prescribir múltiples opioides en distintas formulaciones y vías aumenta el riesgo de confusión. Además, sí se debe informar sobre el riesgo de depresión respiratoria y sí se recomienda administrar las mezclas intravenosas con bombas de infusión inteligentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a5") }, {"long_answer": "El error más frecuente y grave con el metotrexato oral en indicaciones no oncológicas, como la artritis reumatoide o la psoriasis, es su administración diaria en lugar de semanal, que puede producir toxicidad grave e incluso mortal por mielosupresión, mucositis y daño hepático y renal. Por ello se recomienda prescribirlo indicando el día de la semana, utilizar envases con alertas y educar al paciente. La falta de prescripción de ácido fólico es un problema de calidad, pero no el error más frecuente descrito. Las opciones sobre opioides y bombas de infusión no guardan relación con el metotrexato oral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772aa") }, {"long_answer": "Dar a un niño una dosis más pequeña de un medicamento destinado a adultos es peligroso porque el medicamento podría actuar de forma muy diferente en el organismo infantil, debido a las diferencias farmacocinéticas y farmacodinámicas propias del desarrollo, y algunos fármacos o excipientes pueden resultar tóxicos o no estar autorizados en niños. Por ello solo deben utilizarse medicamentos y dosis indicados por un profesional sanitario. No se trata de que el fármaco no vaya a hacer efecto o de que se genere resistencia, y los posibles efectos secundarios no son necesariamente leves, sino que pueden ser graves."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ab") }, {"long_answer": "Guardar los medicamentos en su envase original con la etiqueta intacta es importante sobre todo para evitar confusiones en su administración, ya que permite identificar en todo momento el nombre del fármaco, su dosis, el lote y la fecha de caducidad, y conservar el prospecto con las instrucciones de uso. Trasvasar medicamentos a otros recipientes o manipular las etiquetas es una causa frecuente de errores, especialmente en domicilios con varios tratamientos. Evitar la contaminación, mantener la conservación o facilitar la administración son beneficios secundarios, pero no son el motivo principal que destaca la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ac") }, {"long_answer": "Ante el olvido de una dosis, la recomendación general es administrarla en cuanto se recuerde solo si ha pasado poco tiempo desde la hora prevista; si está próxima la siguiente toma, se debe omitir la dosis olvidada y continuar con la pauta habitual, consultando con el profesional sanitario o el prospecto en caso de duda. Nunca debe administrarse una dosis doble para compensar, por el riesgo de toxicidad. No administrar ninguna dosis cuando ha pasado poco tiempo es incorrecto, y administrar la dosis olvidada en cualquier momento puede solaparla con la siguiente toma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b0") }, {"long_answer": "En los estándares y recomendaciones del Ministerio de Sanidad, el bloque quirúrgico (BQ) se define como una organización de profesionales sanitarios que ofrece asistencia multidisciplinar a procesos asistenciales mediante cirugía, en un espacio donde se agrupan quirófanos con los apoyos e instalaciones necesarios, y que cumple unos requisitos funcionales, estructurales y organizativos que garantizan condiciones adecuadas de calidad, seguridad y eficiencia. La unidad de cuidados intensivos, la unidad de recuperación postanestésica y la hospitalización convencional son unidades relacionadas con la atención quirúrgica, pero no corresponden a la definición de bloque quirúrgico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770c7") }, {"long_answer": "El mapa estratégico de la Estrategia en Salud Cardiovascular (ESCAV) recoge 33 ámbitos de actuación y áreas de resultados considerados prioritarios, que permiten centrar los esfuerzos en los aspectos con mayor impacto sobre la salud cardiovascular de la población y sobre la calidad de la atención. El mapa organiza de forma visual la relación entre los objetivos estratégicos, las líneas de actuación y los resultados esperados. Las cifras de 30, 36 y 39 no se corresponden con el número de elementos prioritarios recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770cb") }, {"long_answer": "El mapa estratégico de la Estrategia en Salud Cardiovascular (ESCAV) contempla en total 50 áreas de resultados y ámbitos de actuación, de los cuales una parte se consideran prioritarios. Este mapa permite visualizar de forma integrada cómo se relacionan los objetivos estratégicos con las acciones en materia de proceso u organización y con los resultados en salud esperados, facilitando su seguimiento y evaluación. Las cifras de 48, 52 y 54 no se corresponden con el número total de elementos recogido en el documento, por lo que son incorrectas."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770cd") });
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d2") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d4") }, {"long_answer": "Entre los factores determinantes de la salud cardiovascular, la Estrategia en Salud Cardiovascular destaca los relacionados con la alimentación y el estilo de vida, como la dieta, la actividad física, el tabaquismo, el consumo de alcohol, el descanso y el control del peso, ya que son factores modificables sobre los que actúan la promoción de la salud y la prevención. Los factores genéticos, psicológicos, económicos o educativos influyen en el riesgo, pero no son los determinantes centrales señalados para la intervención, y los factores climáticos y geográficos tienen una influencia mucho menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770d6") }, {"long_answer": "La Estrategia en Salud Cardiovascular establece que la seguridad del paciente, la continuidad asistencial y el impulso de los sistemas de información son valores que deben estar presentes de forma transversal en todos sus planteamientos, independientemente de la línea estratégica de que se trate. Promoción, prevención y capacitación ciudadana, así como gestión del conocimiento, investigación e innovación, corresponden a líneas estratégicas concretas del documento, no a valores transversales. La equidad, el género y la edad son enfoques que también se consideran, pero no constituyen la tríada de valores por la que se pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770db") }, {"long_answer": "La Estrategia en Salud Cardiovascular señala que las enfermedades cardiovasculares tienen un importante impacto en la economía española, con un coste estimado en torno al 0,7% del producto interior bruto y más de 145 millones de euros al año solo en incapacidad temporal, a lo que se añaden el gasto sanitario directo y las pérdidas de productividad por discapacidad y mortalidad prematura. Las demás opciones describen efectos positivos, como menor desempleo, mayor productividad, menor gasto sanitario o más inversión, que no se corresponden con el impacto real de estas enfermedades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770dc") }, {"long_answer": "En una sociedad que afronta un proceso de envejecimiento acelerado, la Estrategia en Salud Cardiovascular destaca como aspecto clave el aumento de la prevalencia de factores de riesgo cardiovascular, como la hipertensión, la diabetes o la dislipemia, y de las enfermedades cardiovasculares asociadas a la edad, lo que incrementará la demanda asistencial. El envejecimiento se caracteriza por un aumento de la esperanza de vida y de la población mayor de 65 años, junto con una baja natalidad, por lo que las opciones de incremento de natalidad, reducción de la esperanza de vida o disminución de mayores son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770de") }, {"long_answer": "La Estrategia en Salud Cardiovascular identifica como factor de desigualdad de género la sobrecarga física y mental asociada al papel de cuidadoras que asumen mayoritariamente las mujeres, que genera estrés crónico, menos tiempo para el autocuidado y la actividad física y retrasos en la búsqueda de atención, aumentando su riesgo cardiovascular. La predisposición genética y las enfermedades crónicas previas son factores biológicos o clínicos, no de desigualdad de género. La exposición a ambientes laborales tóxicos puede ser un riesgo, pero no se describe como el factor de desigualdad de género característico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e2") }, {"long_answer": "La Estrategia en Salud Cardiovascular recoge que alrededor del 45% de las mujeres cancela o retrasa sus citas médicas debido al estigma social asociado al sobrepeso, por temor a ser juzgadas o a que todos sus problemas de salud se atribuyan al peso. Este fenómeno dificulta la detección y el control precoz de los factores de riesgo cardiovascular y es un ejemplo de cómo las desigualdades de género y el estigma influyen en la salud. Las cifras del 15%, 30% y 60% no se corresponden con el dato recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e4") }, {"long_answer": "Los cambios hormonales que experimentan las mujeres a lo largo de su vida, como los asociados al embarazo, al uso de anticonceptivos hormonales y especialmente a la menopausia, con la disminución del efecto protector de los estrógenos, aumentan su riesgo de desarrollar enfermedades cardiovasculares, al favorecer cambios en el perfil lipídico, la presión arterial y la distribución de la grasa corporal. Por ello no es correcto afirmar que no tengan impacto o que disminuyan el riesgo, y sus efectos no se limitan a las mujeres mayores de 65 años, sino que se producen en distintas etapas vitales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e5") }, {"long_answer": "La Estrategia en Salud Cardiovascular señala que una de las razones por las que las mujeres reciben menos tratamientos basados en la evidencia científica es que las guías de práctica clínica no hacen distinción de género, ya que se basan en ensayos clínicos con predominio de varones y no recogen las particularidades de la presentación, el diagnóstico y la respuesta al tratamiento en las mujeres. No es cierto que las mujeres presenten menos síntomas, sino que estos son con frecuencia distintos. Las opciones sobre preferencias de los profesionales o menor adherencia de las mujeres no se recogen como causa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770e6") }, {"long_answer": "Las enfermedades cardiovasculares son la principal causa de mortalidad en las mujeres a nivel mundial y también en España, por encima del cáncer, a pesar de la percepción social de que se trata de enfermedades propias de los hombres. Esta infravaloración del riesgo contribuye a retrasos en el diagnóstico y el tratamiento. El cáncer de mama es el tumor más frecuente en las mujeres, pero causa muchas menos muertes que las enfermedades cardiovasculares. Las enfermedades respiratorias y los accidentes de tráfico tienen un peso mucho menor en la mortalidad femenina global."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f3") }, {"long_answer": "El Código Europeo contra el Cáncer recomienda hacer ejercicio a diario y limitar el tiempo que se pasa sentado, ya que la actividad física regular reduce el riesgo de varios tipos de cáncer, como el de colon, mama y endometrio, además de ayudar a mantener un peso saludable. Las demás opciones son contrarias a sus recomendaciones: el Código aconseja evitar los alimentos hipercalóricos y las bebidas azucaradas, no fumar ni consumir ningún tipo de tabaco, y evitar la exposición excesiva al sol, protegiéndose especialmente los niños y no utilizando cabinas de rayos UVA."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770f6") }, {"long_answer": "El Código Europeo contra el Cáncer recomienda protegerse en el trabajo frente a las sustancias cancerígenas cumpliendo las instrucciones de la normativa de protección de la salud y seguridad laboral, como el uso de equipos de protección, la ventilación adecuada o la limitación de la exposición a agentes como el amianto, la sílice o determinados disolventes. Las demás opciones son claramente contrarias a esta recomendación: no tomar medidas de prevención, exponerse a sustancias cancerígenas o ignorar la normativa de salud y seguridad laboral aumentan el riesgo de cáncer de origen profesional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9770fe") }, {"long_answer": "Según el informe sobre la situación del cáncer en España, la incidencia de cáncer de estómago en hombres disminuyó aproximadamente un 21% entre 2012 y 2020, en consonancia con la tendencia descendente observada en los países desarrollados, atribuida a la reducción de la infección por Helicobacter pylori, la mejora en la conservación de los alimentos con la refrigeración y el menor consumo de alimentos salados y ahumados. Por ello las opciones que indican un aumento del 21% o del 6% son incorrectas, al igual que la que afirma que la incidencia se mantuvo estable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977104") }, {"long_answer": "Según los datos comparativos del informe sobre el cáncer en España, el cáncer de mama presentó en las mujeres una tasa ligeramente superior en España que en el conjunto de la Unión Europea de 27 países, a diferencia de otros tumores que muestran tasas similares o inferiores. El cáncer de mama es el tumor más frecuente en las mujeres españolas. El cáncer de pulmón en mujeres españolas tiene todavía tasas inferiores a las europeas, aunque en ascenso por la incorporación más tardía de las mujeres al tabaquismo, y los cánceres de tiroides y estómago no son los que se señalan en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977108") }, {"long_answer": "Según el informe sobre el cáncer en España, la supervivencia observada a cinco años para el total de cánceres, excluidos los de piel no melanoma, en los hombres diagnosticados en el periodo 2008-2013 fue del 48,9%. La supervivencia observada incluye las muertes por cualquier causa, por lo que es inferior a la supervivencia neta, que solo tiene en cuenta el exceso de mortalidad atribuible al cáncer y que en ese periodo superó el 55% en los hombres. Las cifras del 57,4%, 55,3% y 61,7% no corresponden a la supervivencia observada en hombres descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977109") }, {"long_answer": "Según el informe sobre la supervivencia del cáncer en España, la supervivencia neta a cinco años en los hombres del grupo de edad de 55 a 64 años fue del 77,7%, superior a la de los grupos de mayor edad, ya que la supervivencia disminuye a medida que aumenta la edad al diagnóstico por la mayor comorbilidad, el diagnóstico en estadios más avanzados y la menor tolerancia a los tratamientos. Las cifras del 74,3%, 55,6% y 60,7% no corresponden al dato descrito para este grupo de edad en los hombres, por lo que son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977111") }, {"long_answer": "La prevalencia del cáncer, es decir, el número de personas vivas que han sido diagnosticadas de cáncer en un periodo determinado, depende fundamentalmente de la incidencia, o número de casos nuevos, y de la supervivencia de los pacientes. Por ello la mejora en la supervivencia gracias al diagnóstico precoz y a los avances terapéuticos, unida al aumento de la incidencia por el envejecimiento, explica el crecimiento de la prevalencia. La edad, el acceso a los tratamientos o el sexo influyen indirectamente a través de la incidencia y la supervivencia, pero no son los determinantes principales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977112") }, {"question": "Según el informe sobre la situación del cáncer, ¿cuál fue la primera causa de mortalidad en los hombres en España en 2018?", "option_2": "Accidentes de tráfico", "long_answer": "En 2018 el cáncer fue la primera causa de muerte en los hombres en España, con más de 65.000 defunciones, por delante de las enfermedades cardiovasculares, que siguieron siendo la primera causa de muerte en las mujeres y en el conjunto de la población. Este dato refleja el elevado impacto de tumores como el de pulmón, colorrectal y próstata en la mortalidad masculina. Las enfermedades cardiovasculares ocuparon el segundo lugar en los hombres y las enfermedades respiratorias el tercero, mientras que los accidentes de tráfico tienen un peso mucho menor en la mortalidad global."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977113") }, {"long_answer": "Según el informe sobre la situación del cáncer en España, en 2018 se registraron 65.851 defunciones por cáncer en hombres, frente a unas 42.404 en mujeres, sumando un total de 108.255 muertes por tumores, lo que lo sitúa como la primera causa de muerte en los varones. La cifra de 42.404 corresponde a las defunciones en mujeres, la de 108.255 al total de ambos sexos y la de 22.104 se aproxima a las muertes por cáncer de pulmón, por lo que ninguna de ellas responde a la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977116") }, {"long_answer": "Según el informe sobre la situación del cáncer en España, en 2018 el cáncer de mama ocupó el tercer lugar entre las causas de defunción en las mujeres, siendo además el tumor que más muertes causó en la población femenina, seguido del cáncer colorrectal y del cáncer de pulmón, este último en ascenso por la incorporación de las mujeres al tabaquismo. El cáncer colorrectal y el de pulmón ocuparon posiciones posteriores, y el cáncer de páncreas, aunque con elevada letalidad, causó menos defunciones que el de mama. De ahí la importancia de los programas de cribado mediante mamografía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97711d") }, {"long_answer": "Según las estimaciones de incidencia del cáncer en España para 2020 recogidas en el informe, se diagnosticaron aproximadamente 9.188 casos nuevos de linfomas no hodgkinianos, lo que los sitúa entre los tumores hematológicos más frecuentes en ambos sexos, con mayor incidencia en edades avanzadas. Las cifras de 8.188, 10.188 y 11.188 casos no se corresponden con la estimación recogida en el documento para ese año, por lo que son incorrectas. Conocer estos datos ayuda a dimensionar la carga de las neoplasias hematológicas en el sistema sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97711f") }, {"long_answer": "El informe sobre el cáncer en España señala que durante el periodo 2008-2012 hubo una amplia fluctuación en las tasas de incidencia ajustadas a la población mundial entre los distintos registros de cáncer de base poblacional españoles, reflejando diferencias geográficas en la exposición a factores de riesgo, como el tabaco, en los programas de cribado y en las características de cada población. Por ello no es correcto afirmar que no hubo variabilidad, que esta fue ligera o que no fue significativa, ya que el documento destaca precisamente la amplitud de estas diferencias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977122") }, {"long_answer": "Según las estimaciones de incidencia del cáncer en España para 2020 recogidas en el informe, las leucemias ocuparon la decimosegunda posición entre los tumores más frecuentes en los hombres y la decimotercera en las mujeres, por detrás de tumores mucho más frecuentes como el colorrectal, próstata, pulmón y vejiga en hombres o mama, colorrectal y pulmón en mujeres. Las demás combinaciones de posiciones no se corresponden con los datos del documento. No son, por tanto, uno de los cánceres más diagnosticados, aunque sí uno de los más frecuentes en la infancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977127") }, {"question": "Según la Estrategia en Cáncer del SNS, ¿cuántos casos nuevos de cáncer en adolescentes de 15 a 19 años se estimaron en España en 2020?", "long_answer": "La Estrategia en Cáncer del Sistema Nacional de Salud recoge, a partir de las estimaciones de la Red Española de Registros de Cáncer, que en 2020 se diagnosticarían en España alrededor de 382 casos nuevos de cáncer en adolescentes de 15 a 19 años, cifra que se suma a los aproximadamente 1.100 casos estimados en la población infantil de 0 a 14 años. Aunque el cáncer en esta franja de edad es poco frecuente, constituye una causa relevante de mortalidad por enfermedad y justifica una organización asistencial específica para la adolescencia. Las cifras de 282, 482 y 582 casos no se corresponden con la estimación publicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97712d") }, {"long_answer": "El Código Europeo contra el Cáncer es un conjunto de recomendaciones dirigidas a la población general, basadas en la evidencia científica, cuyo objetivo es reducir el riesgo de desarrollar cáncer. Su cuarta edición incluye doce recomendaciones sobre tabaco, exposición al humo ajeno, peso corporal, actividad física, alimentación, alcohol, exposición solar, carcinógenos laborales, radón, lactancia materna, terapia hormonal sustitutiva, vacunación frente a hepatitis B y VPH y participación en los programas de cribado. No es un código deontológico para oncólogos, ni una clasificación de tumores, ni un listado de fármacos antineoplásicos, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977134") }, {"long_answer": "Según la Encuesta Nacional de Salud de España (ENSE) 2017, el 10,3% de la población infantil de 2 a 17 años presentaba obesidad, considerando ambos sexos, mientras que el sobrepeso afectaba a un 18,3%. La suma de ambos, exceso de peso, alcanza el 28,6%, cifra que corresponde a la primera opción y que no debe confundirse con la prevalencia de obesidad aislada. Estos datos sitúan el exceso de peso infantil como un problema prioritario de salud pública, relacionado con factores de riesgo de cáncer y otras enfermedades crónicas. Los valores de 17,4% y 6,8% no corresponden a la prevalencia de obesidad para ambos sexos recogida por la encuesta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977138") }, {"question": "Según la Estrategia en Cáncer del SNS, ¿cuántas muertes por cáncer relacionado con el trabajo se producen aproximadamente cada año en la Unión Europea?", "option_1": "50.000", "option_2": "100.000", "option_3": "150.000", "option_4": "200.000", "long_answer": "Se estima que en la Unión Europea alrededor de 100.000 personas fallecen cada año por cáncer relacionado con la exposición a agentes carcinógenos en el lugar de trabajo, lo que convierte al cáncer en la principal causa de mortalidad laboral en la UE. Esta cifra justifica que el Código Europeo contra el Cáncer incluya la recomendación de protegerse frente a sustancias cancerígenas en el trabajo siguiendo las normas de seguridad, y que la normativa europea sobre carcinógenos y mutágenos se haya ido actualizando con nuevos valores límite de exposición. Las cifras de 50.000, 150.000 y 200.000 no se corresponden con la estimación que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97713a") }, {"long_answer": "El cáncer es la principal causa de mortalidad relacionada con el trabajo en la Unión Europea, responsable de más de la mitad de las muertes de origen laboral, por delante de las enfermedades circulatorias y respiratorias. Se debe a la exposición a carcinógenos como el amianto, la sílice cristalina, los humos de motor diésel o determinados disolventes, cuyos efectos aparecen tras largos periodos de latencia. Los accidentes laborales y los de tráfico in itinere causan muertes, pero en un número claramente inferior, y las enfermedades cardiovasculares de origen laboral tampoco superan al cáncer, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97713f") }, {"long_answer": "La evidencia científica actual asocia la terapia hormonal sustitutiva en la menopausia con un incremento del riesgo de cáncer, especialmente de mama, y en el caso de los estrógenos sin oposición progestágena también de endometrio. Por ello, el Código Europeo contra el Cáncer recomienda limitar su uso y reservarlo para indicaciones concretas, a la menor dosis y durante el menor tiempo posible. No es correcto afirmar que no exista asociación ni que disminuya el riesgo; y aunque el efecto varía entre localizaciones, el mensaje que recoge el documento es el aumento global del riesgo, por lo que la cuarta opción no es la más adecuada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977142") }, {"long_answer": "La Ley 33/2011, General de Salud Pública, define el cribado como las actividades orientadas a la detección precoz de la enfermedad, su diagnóstico y tratamiento temprano, que se ofrecen activamente al conjunto de una población susceptible de padecerla, aunque no tenga síntomas ni haya demandado ayuda médica. Su esencia es actuar sobre personas asintomáticas para mejorar el pronóstico. Las pruebas de confirmación diagnóstica, el tratamiento aislado o la atención a personas que ya presentan síntomas forman parte de la asistencia clínica habitual, no del cribado poblacional, por lo que el resto de opciones no recogen la definición legal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977148") }, {"long_answer": "Los tumores raros se caracterizan por su baja incidencia, de modo que los pacientes están dispersos entre muchos centros. Esta dispersión dificulta reunir casuística suficiente y, entre otros problemas, limita el acceso de estos pacientes a los ensayos clínicos, que suelen concentrarse en centros con experiencia y volumen. Por ello la Estrategia en Cáncer del SNS propone redes y centros de referencia. La dispersión no se asocia a mayor disponibilidad de tratamientos aprobados ni facilita la investigación clínica, sino todo lo contrario, y el acceso a nuevas pruebas diagnósticas no es el problema que se destaca, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97714a") }, {"question": "¿Qué papel se promueve para los pacientes con cáncer en la toma de decisiones terapéuticas?", "option_1": "Participar activamente en una toma de decisiones compartida con los profesionales", "long_answer": "La Estrategia en Cáncer del SNS promueve que la persona con cáncer participe activamente en las decisiones sobre su tratamiento mediante un modelo de toma de decisiones compartida: el profesional aporta información comprensible sobre opciones, beneficios y riesgos, y el paciente aporta sus valores y preferencias. Este enfoque refuerza la autonomía, mejora la adherencia y la satisfacción. No expresar preferencias, aceptar pasivamente las indicaciones o que el profesional no explore las preferencias del paciente representan el modelo paternalista que precisamente se pretende superar, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97714b") }, {"long_answer": "La creciente demanda de segundas opiniones por parte de pacientes con cáncer refleja, fundamentalmente, su necesidad de confirmar el diagnóstico o el tratamiento propuesto ante decisiones complejas y de gran trascendencia, en un contexto de pacientes más informados y participativos. La Estrategia en Cáncer del SNS plantea ordenar este derecho para que se ejerza con garantías. No implica necesariamente falta de confianza en el profesional, ni guarda relación con un aumento de la eficacia del tratamiento indicado o con el acceso a tratamientos más agresivos, por lo que estas opciones no explican el fenómeno descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97714d") }, {"long_answer": "La atención al paciente oncológico en red tiene como elemento clave la atención multidisciplinar: la valoración de cada caso por comités de tumores con profesionales de distintas especialidades, que acuerdan un plan terapéutico integrado y coordinado entre niveles y centros. La Estrategia en Cáncer del SNS lo considera un estándar de calidad. Derivar a centros de referencia extranjeros no es un elemento de la red asistencial del SNS; la tecnología de última generación es un recurso, no el eje organizativo; y concentrar todo el tratamiento en hospitales centrales contradice el modelo en red, que distribuye la atención según complejidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97714e") }, {"question": "Según la Estrategia en Cáncer del SNS, ¿qué tipo de programas deben establecerse en todas las CC.AA. ante la sospecha de cáncer?", "long_answer": "La Estrategia en Cáncer del SNS recomienda que todas las comunidades autónomas dispongan de programas de diagnóstico rápido ante la sospecha fundada de cáncer, con circuitos preferentes entre atención primaria y hospitalaria que reduzcan el tiempo hasta la confirmación diagnóstica y el inicio del tratamiento, disminuyendo además la ansiedad del paciente. Los tratamientos experimentales se encuadran en ensayos clínicos, no en programas generalizados; la rehabilitación forma parte de la atención posterior; y la cirugía preferente no sustituye a un circuito diagnóstico ágil, por lo que las demás opciones no responden a la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977150") }, {"option_2": "Análisis genéticos de ancestría y genealogía", "long_answer": "La actualización de 2014 de la cartera común básica de servicios asistenciales del SNS, mediante la Orden SSI/2065/2014, incorporó de forma expresa los análisis genéticos, entre ellos los análisis genéticos diagnósticos, que permiten confirmar una sospecha clínica de enfermedad de base genética, incluidos los síndromes de cáncer hereditario, junto con el consejo genético asociado. Los análisis de ancestría o genealogía no tienen finalidad asistencial y no forman parte de la cartera; los denominados preventivos o terapéuticos no son categorías definidas en la norma, por lo que la opción correcta es la de análisis diagnósticos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97715b") }, {"option_3": "Registros de cáncer en niños y adolescentes.", "long_answer": "Para evaluar las acciones de reducción del riesgo de cáncer en la población general, la Estrategia en Cáncer del SNS utiliza como fuentes de información las estadísticas oficiales y las encuestas poblacionales, como la Encuesta Nacional de Salud o la Encuesta Europea de Salud, que permiten conocer la prevalencia de tabaquismo, consumo de alcohol, sedentarismo u obesidad. Los registros de cáncer infantil se emplean para vigilar la incidencia en menores, los efectos secundarios en adultos tienen que ver con la supervivencia y los datos administrativos hospitalarios reflejan la actividad asistencial, por lo que no son la fuente para medir factores de riesgo poblacionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97715e") }, {"long_answer": "Entre los objetivos de detección precoz de la Estrategia en Cáncer del SNS figura alcanzar en los programas poblacionales de cribado de cáncer de mama una participación mínima del 70% de las mujeres invitadas, estándar recomendado por las guías europeas de calidad para que el programa tenga impacto sobre la mortalidad. La población diana del programa es la de 50 a 69 años, por lo que el cribado sistemático de mujeres de 70 a 80 años no es el objetivo; una participación del 50% es insuficiente; y promover la actividad física en mujeres ya diagnosticadas es una medida de promoción de la salud, no de detección precoz."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97715f") }, {"long_answer": "En relación con el cáncer colorrectal, el objetivo que recoge la Estrategia en Cáncer del SNS es impulsar la implantación completa de los programas poblacionales de cribado para alcanzar una cobertura total de invitación de la población diana, de 50 a 69 años, dentro del plazo fijado. La extensión del programa es el reto prioritario, ya que su despliegue ha sido desigual entre comunidades autónomas. El cribado sistemático no se dirige a mayores de 70 años; la cifra de participación del 60% no es la que fija el documento; y la sensibilización de la población es una acción de apoyo, no el objetivo planteado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977164") }, {"question": "En la Estrategia en Cáncer del SNS, ¿cuál es una de las acciones relacionadas con el objetivo 27?", "option_1": "Seleccionar la herramienta/s estandarizada más adecuada para la detección precoz de malestar emocional", "long_answer": "En la Estrategia en Cáncer del SNS, una de las acciones vinculadas al objetivo 27 es poner en marcha cursos de formación dirigidos a los profesionales que atienden a personas con cáncer, ya que la capacitación continuada de los equipos es una pieza transversal para mejorar la calidad de la atención. Las demás opciones son acciones reales de la Estrategia pero pertenecen a otros objetivos: la selección de herramientas para detectar el malestar emocional se enmarca en la atención psicológica, y el control de calidad y la mejora del diagnóstico anatomopatológico se relacionan con los objetivos de diagnóstico y de oncología de precisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977169") }, {"question": "En la Estrategia en Cáncer del SNS, ¿cuál es una de las acciones relacionadas con el objetivo 32?", "long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 32 se refiere a la atención de los tumores raros, y una de sus acciones es implantar un sistema de doble lectura de la prueba diagnóstica de anatomía patológica, realizada por un patólogo o patóloga experta de un centro de referencia designado. La baja frecuencia de estos tumores dificulta la experiencia diagnóstica y la doble lectura reduce los errores. El mapa de recursos de radioterapia, el modelo organizativo de la oncología de precisión y el plan individualizado de seguimiento son acciones de la Estrategia ligadas a otros objetivos distintos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97716c") }, {"question": "En la Estrategia en Cáncer del SNS, ¿cuál es una de las acciones relacionadas con el objetivo 35?", "long_answer": "En la Estrategia en Cáncer del SNS, el objetivo 35 se centra en los sistemas de información, y una de sus acciones es definir y desarrollar un sistema de información de cáncer que permita conocer la incidencia, la prevalencia y la supervivencia por comunidad autónoma, imprescindible para planificar recursos y evaluar resultados. La organización asistencial del cáncer infantil y de la adolescencia, la formación de profesionales y los circuitos de seguimiento de pacientes sin enfermedad presente son también acciones de la Estrategia, pero están vinculadas a otros objetivos y no al de información."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97716e") }, {"question": "¿De qué dependen la concentración y el tamaño de los aerosoles generados por una persona?", "long_answer": "Según el documento del Ministerio de Sanidad sobre transmisión de SARS-CoV-2 por aerosoles, la concentración y el tamaño de los aerosoles que emite una persona dependen de la actividad que realiza: la emisión es mínima al respirar tranquilamente y aumenta progresivamente al hablar, hablar alto, cantar, gritar o hacer ejercicio intenso. Por eso se recomienda hablar en voz baja y reducir las actividades de alta emisión en interiores. El nivel de transmisión comunitaria, el volumen de aire inhalado o el tiempo de exposición influyen en el riesgo de contagio del receptor, pero no determinan las características de los aerosoles emitidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97716f") }, {"long_answer": "Jones y Brousseau propusieron tres condiciones para considerar que una infección se transmite por aerosoles, y la primera es que los aerosoles generados por la persona infectada contengan virus viables. Las siguientes condiciones exigen que esos aerosoles alcancen el tejido diana del huésped susceptible y que este tejido sea vulnerable a la infección. La relación entre viabilidad, humedad y temperatura, la cantidad de virus emitida en ese momento o la capacidad infectiva de los aerosoles son factores que modulan el riesgo, pero no constituyen la primera condición del modelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977170") }, {"long_answer": "El riesgo de que se generen aerosoles con virus viable de SARS-CoV-2 depende sobre todo de la carga viral de la persona infectada en sus vías respiratorias, que es máxima en los días previos y los primeros días tras el inicio de síntomas, junto con la actividad que realiza. El volumen de aire inhalado y el nivel de transmisión comunitaria influyen en el riesgo de quien se expone o de la población, no en la generación de aerosoles infectivos. La concentración y el tamaño de los aerosoles son consecuencia de la emisión, no el factor que determina que contengan virus viable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977185") }, {"long_answer": "En la Unión Europea las mascarillas quirúrgicas son productos sanitarios cuya eficacia se regula por la norma UNE-EN 14683:2019, que establece los requisitos de eficacia de filtración bacteriana, respirabilidad, resistencia a salpicaduras y limpieza microbiana, clasificándolas en tipo I, tipo II y tipo IIR. La norma EN 149:2001 regula las mascarillas autofiltrantes o EPI (FFP1, FFP2, FFP3). Las especificaciones UNE 0065 y CWA 17553:2020 se refieren a mascarillas higiénicas reutilizables de uso por la población general, que no son productos sanitarios. Por tanto, solo la primera opción corresponde a mascarillas quirúrgicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977187") }, {"answer": 2, "option_4": "Aumentar la temperatura del local", "long_answer": "El documento del Ministerio de Sanidad sobre transmisión de SARS-CoV-2 por aerosoles señala que la emisión de aerosoles aumenta de forma marcada al hablar alto, gritar o cantar, por lo que hablar en tono bajo o permanecer en silencio es una medida sencilla y eficaz para reducir el riesgo de contagio. La distancia interpersonal y las mascarillas son medidas complementarias, pero no actúan sobre la cantidad de aerosoles emitidos al elevar la voz, y aumentar la temperatura del local no reduce la emisión ni la concentración de partículas. Por ello, la opción correcta es hablar en voz baja o en silencio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97718b") }, {"option_4": "99,995%", "long_answer": "Según la norma UNE-EN 1822, un filtro HEPA de clase H13 tiene una eficacia mínima de filtración del 99,95% para el tamaño de partícula de máxima penetración, mientras que la clase H14 alcanza el 99,995%. Estos filtros se emplean en quirófanos, unidades de aislamiento y purificadores portátiles para reducir la concentración de aerosoles en interiores. El 95% corresponde a filtros de menor clase y el 99,5% a filtros EPA o semi-HEPA, por lo que no definen un HEPA H13; el 99,995% es el valor propio del H14."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977190") }, {"option_1": "En parques al aire libre con poca gente", "option_2": "En una habitación en la que la persona está sola", "long_answer": "El documento sobre transmisión por aerosoles recomienda mantener niveles bajos de ruido, por ejemplo con la música a volumen reducido, en restaurantes, bares y otros locales de hostelería, porque el ruido obliga a hablar más alto y aumenta la emisión de aerosoles en espacios interiores donde además se retira la mascarilla para comer y beber. En un parque al aire libre con poca gente o en una habitación donde la persona está sola el riesgo de transmisión es mínimo, por lo que no es allí donde se dirige la recomendación, y la opción ninguna de las anteriores es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977192") }, {"long_answer": "Reducir el aforo de los espacios interiores permite que las personas puedan mantener la distancia interpersonal y disminuye el número de emisores potenciales de aerosoles en el mismo volumen de aire, lo que reduce la concentración de partículas infecciosas y la probabilidad de contagio. Es una de las medidas que el documento de transmisión por aerosoles combina con la ventilación, la mascarilla y la reducción del tiempo de permanencia. Aumentar la concentración de personas o el riesgo de contagio sería el efecto contrario al buscado, por lo que esas opciones son incorrectas, igual que la opción ninguna de las anteriores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977193") }, {"long_answer": "En espacios interiores mal ventilados los aerosoles se acumulan, y la dosis infectiva que recibe una persona depende de la concentración de virus en el aire y del tiempo que permanece expuesta. Por tanto, cuanto mayor es el tiempo de exposición, mayor es la dosis inhalada y mayor el riesgo de infección. Por esta razón se recomienda limitar la duración de las estancias y las reuniones en interiores, además de mejorar la ventilación. Afirmar que la exposición prolongada disminuye la dosis o no tiene efecto contradice el modelo de transmisión por aerosoles, y la opción ninguna de las anteriores también es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977199") }, {"long_answer": "Según su etiología, la flebitis asociada a catéteres venosos periféricos se clasifica en tres tipos: mecánica, producida por el roce del catéter con la pared venosa, una fijación inadecuada o un calibre excesivo; química, causada por fármacos o soluciones irritantes por su pH u osmolaridad; e infecciosa o bacteriana, debida a la colonización del catéter por microorganismos. Algunos autores describen además la flebitis postinfusión, pero se considera una forma de presentación temporal y no una etiología distinta. Por ello, la respuesta correcta es tres tipos y no dos, cuatro o cinco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97719d") }, {"long_answer": "Se considera infección del punto de inserción de un catéter cuando aparecen signos locales como enrojecimiento, induración, calor y salida de material purulento por el orificio, ya que la supuración es el dato que mejor diferencia la infección de la simple inflamación. Ante estos signos debe retirarse el catéter y valorar el cultivo del exudado. El dolor, el eritema, la sensibilidad y el calor sin pus son propios de la flebitis; una erupción cutánea puede deberse a alergias o al apósito; y la fiebre, la tos y el malestar general son síntomas sistémicos inespecíficos que no localizan la infección en el punto de inserción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97719f") }, {"long_answer": "La OMS insiste en que el uso de guantes no sustituye la higiene de manos. Los guantes deben retirarse al finalizar cada actividad o tarea con el paciente, y siempre que surja una indicación de higiene de manos mientras se llevan puestos, realizando la higiene inmediatamente después de quitarlos, porque pueden tener microperforaciones y las manos se contaminan al retirarlos. Por ello no es correcto limitarlo a los guantes manchados de sangre o al contacto con fluidos, ni afirmar que nunca es necesario quitárselos, ya que lavar o desinfectar los guantes puestos no está recomendado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771a0") }, {"long_answer": "Según la OMS, los guantes de exploración no estériles están indicados cuando se prevé el contacto con sangre, fluidos corporales, secreciones, excreciones, mucosas, piel no intacta u objetos visiblemente contaminados, así como cuando lo exigen las precauciones de contacto. Tomar la presión arterial o la temperatura sobre piel intacta es una exposición directa en la que no están indicados, y su uso innecesario favorece la transmisión cruzada y el olvido de la higiene de manos. No se limitan a situaciones de epidemia o emergencia, y afirmar que nunca deben usarse es claramente incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771a1") }, {"option_2": "Distribución de medicación oral y recogida de bandejas de comida.", "long_answer": "En la pirámide de uso de guantes de la OMS, se denomina exposición directa al paciente a las actividades con contacto físico sin riesgo de exposición a fluidos, como tomar la presión arterial, la temperatura y el pulso, administrar inyecciones subcutáneas e intramusculares, bañar o vestir al paciente, en las que no se indican guantes salvo precauciones de contacto. El manejo de residuos y la limpieza de superficies, usar el teléfono y registrar datos, o distribuir medicación oral y recoger bandejas son exposiciones indirectas, ya que no implican contacto físico con el paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b3") }, {"answer": 3, "long_answer": "Los objetivos generales del Plan de Actuación sobre Ictus en Europa 2018-2030 incluyen disponer de planes nacionales para el ictus que abarquen toda la cadena de atención, desde la prevención primaria hasta la vida después del ictus. El plan también propone reducir el número absoluto de ictus en un 10%, no un 5%, y tratar al 90% o más de los pacientes en una unidad de ictus como primer nivel de atención, no al 80%, por lo que esas opciones alteran las cifras reales. La reducción de la mortalidad al primer mes en hemorragias es una meta de un área concreta y no uno de los objetivos generales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b5") }, {"question": "Según el Plan de Actuación sobre Ictus en Europa 2018-2030, ¿cuál es uno de los aspectos centrales de una unidad integral de ictus?", "long_answer": "Una unidad de ictus integral se caracteriza por contar con un equipo especializado centrado en el ictus, con médicos expertos en esta enfermedad que trabajan con un enfoque multidisciplinar junto a enfermería, fisioterapia, terapia ocupacional, logopedia y trabajo social, lo que permite iniciar la rehabilitación de forma precoz y reduce la mortalidad y la dependencia. Garantizar el acceso del 90% de la población a la rehabilitación precoz, ofrecer acondicionamiento físico a quienes viven en la comunidad o nombrar responsables gubernamentales de la vida tras el ictus son metas poblacionales o de política sanitaria del plan, no características de la unidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b6") }, {"long_answer": "En el ámbito de la evaluación y mejora de la calidad, el Plan de Actuación sobre Ictus en Europa 2018-2030 propone definir un Marco Común Europeo de Referencia para la Calidad de la Atención del Ictus, con indicadores homogéneos que permitan comparar resultados entre países y monitorizar la cadena asistencial. Las otras opciones son también objetivos del plan, pero pertenecen al área de la vida después del ictus: garantizar el apoyo con independencia del lugar de residencia, formalizar la participación de pacientes, cuidadores y asociaciones, y nombrar responsables gubernamentales que atiendan sus necesidades a largo plazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771b7") }, {"question": "¿Cuál de los siguientes es un efecto del consumo de alcohol sobre la conducción?", "option_2": "Aumento de la capacidad de concentración", "option_3": "Tiempo de reacción más rápido", "option_4": "Mejora de la coordinación motora", "long_answer": "El alcohol es un depresor del sistema nervioso central y, incluso con tasas bajas de alcoholemia, produce una disminución de la agudeza mental: empeora la atención, la capacidad de juicio y la valoración del riesgo, a menudo con una falsa sensación de seguridad. Además alarga el tiempo de reacción, altera la coordinación motora y la visión, y aumenta el riesgo de siniestro de forma proporcional a la alcoholemia. Por ello son falsas las opciones que atribuyen al alcohol un aumento de la concentración, un tiempo de reacción más rápido o una mejora de la coordinación, efectos contrarios a los que realmente provoca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771bd") }, {"long_answer": "Los efectos del alcohol sobre la conducción dependen de la alcoholemia alcanzada, y esta depende de factores como la cantidad ingerida, la velocidad con que se consume, la ingesta simultánea de alimentos, el peso, el sexo y la edad. Beber rápidamente produce picos de alcoholemia más altos porque el organismo no tiene tiempo de metabolizar el alcohol, por lo que el deterioro es mayor. La hora del día, la música que se escucha o el tipo de vehículo no modifican la absorción ni el efecto del alcohol, aunque puedan influir en otros aspectos de la conducción, por lo que no son la respuesta correcta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c2") }, {"long_answer": "En situaciones de catástrofe, la necesidad prioritaria en materia de vacunación es mantener las coberturas de las vacunas incluidas en el calendario a lo largo de toda la vida y en los grupos de riesgo, ya que la interrupción de servicios y el hacinamiento favorecen brotes de enfermedades inmunoprevenibles. Las vacunaciones adicionales solo se indican según la evaluación de riesgos. Vacunar a toda la población sin excepción no está justificado; suspender toda vacunación aumentaría el riesgo de brotes; y priorizar exclusivamente a los mayores ignoraría a la población infantil y a otros grupos vulnerables, por lo que esas opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771c5") }, {"long_answer": "La hepatitis A se transmite por vía fecal-oral, a través de agua y alimentos contaminados, por lo que el principal riesgo en situaciones de inundación es un aumento de la incidencia por la contaminación de las fuentes de agua potable y de los alimentos, favorecida por el deterioro del saneamiento. En España, la baja endemicidad hace que gran parte de la población joven no esté inmunizada, lo que aumenta su susceptibilidad en lugar de anular el riesgo. Por tanto, es incorrecto afirmar que el riesgo sea nulo, que no exista o que afecte únicamente a la población adulta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ce") }, {"question": "En el Real Decreto que modifica la regulación de los productos del tabaco, ¿a qué se refiere el principio de proporcionalidad?", "long_answer": "En la normativa española, el principio de proporcionalidad, recogido entre los principios de buena regulación de la Ley 39/2015, implica que la norma contiene la regulación imprescindible para atender las necesidades que pretende cubrir, sin imponer obligaciones más allá de lo necesario. En el Real Decreto sobre productos del tabaco se justifica así que la modificación se limite a lo exigido para adaptarse a los cambios en los patrones de consumo y a la normativa europea. Generar nuevas cargas administrativas, establecer medidas sin justificación o ignorar esos cambios contradicen precisamente este principio y los de eficiencia y necesidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d0") }, {"question": "¿Qué establece el artículo único del Real Decreto 47/2024 sobre productos del tabaco?", "option_4": "La prohibición total de la venta de cigarrillos electrónicos", "long_answer": "El artículo único del Real Decreto 47/2024 modifica el Real Decreto 579/2017, por el que se regulan determinados aspectos relativos a la fabricación, presentación y comercialización de los productos del tabaco y los productos relacionados. A través de esta modificación se traslada la normativa europea que extiende a los productos del tabaco calentado la prohibición de aromas característicos y las advertencias sanitarias. No prohíbe importar productos del tabaco, no crea una nueva categoría de producto y tampoco prohíbe la venta de cigarrillos electrónicos, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d3") }, {"long_answer": "La infección por el virus de la viruela del mono (MPXV) suele comenzar con un periodo prodrómico en el que el síntoma principal es la fiebre, acompañada de cefalea, mialgias, astenia y linfadenopatías, que ayudan a diferenciarla de la varicela. Posteriormente aparece el exantema característico, que evoluciona de mácula a pápula, vesícula, pústula y costra, y que en el brote de 2022 se localizó con frecuencia en la zona anogenital. El dolor de garganta, el dolor abdominal o el dolor de espalda pueden presentarse en algunos casos, pero no constituyen el cuadro inicial principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d6") }, {"long_answer": "Para el diagnóstico de laboratorio de la infección por MPXV, la muestra de elección es la de las lesiones cutáneas o mucosas: frotis del exudado o del techo de las vesículas, o costras, en las que la carga viral es mayor y que se analizan mediante PCR. El frotis faríngeo o la muestra de sangre pueden complementar el estudio en fases precoces o en contactos, pero tienen menor rendimiento. La orina no se recomienda como muestra diagnóstica, y el frotis de mucosa bucal sin lesión no sustituye a la toma directa de la lesión, por lo que la respuesta correcta es la muestra de lesión cutánea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771d9") }, {"long_answer": "El MPXV es un virus envuelto, sensible a los detergentes y desinfectantes habituales, por lo que para el control medioambiental se recomienda una limpieza con agua caliente y detergente, seguida de desinfección con los productos de uso habitual en el centro, como hipoclorito sódico diluido. La ropa de cama y la ropa personal se lavan a temperatura elevada, evitando sacudirlas para no dispersar partículas. No se necesitan desinfectantes químicos agresivos ni lejía concentrada, que pueden dañar superficies y resultar tóxicos, y evitar la limpieza es incorrecto, ya que mantendría las superficies contaminadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771da") }, {"long_answer": "Según el protocolo para la detección precoz y manejo de casos de viruela del mono, los contactos estrechos de un caso probable o confirmado no requieren cuarentena, pero deben vigilar la aparición de síntomas durante 21 días, que es el periodo máximo de incubación, extremar las precauciones y reducir las interacciones sociales, evitando especialmente el contacto con personas inmunodeprimidas, embarazadas y niños, así como las relaciones sexuales. La cuarentena obligatoria no está indicada; no hacer seguimiento sería incorrecto; y el uso de mascarilla durante 14 días no se ajusta ni a la medida ni al periodo recomendados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e1") }, {"long_answer": "Durante el embarazo se recomienda utilizar siempre el cinturón de seguridad, tanto si la mujer conduce como si viaja como pasajera, en cualquier plaza del vehículo, ya que es la medida más eficaz para proteger a la madre y, con ello, al feto en caso de colisión. Debe colocarse correctamente: la banda diagonal entre los pechos y por encima del abdomen, y la banda horizontal por debajo del vientre, sobre los huesos de la cadera. No usarlo, o hacerlo solo cuando se conduce, aumenta el riesgo de lesiones graves, y la condición de viajar en un coche libre de humo no tiene relación con el uso del cinturón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e3") }, {"long_answer": "Durante el embarazo deben evitarse el consumo de tabaco y alcohol y el consumo de drogas, y además se recomienda viajar en un coche libre de humo, puesto que la exposición pasiva al humo del tabaco también perjudica al feto. Estas sustancias se asocian a bajo peso al nacer, prematuridad, malformaciones, síndrome alcohólico fetal y otras alteraciones del desarrollo, y no existe un nivel de consumo de alcohol seguro en la gestación. Como cada una de las tres primeras opciones recoge una recomendación correcta, la respuesta adecuada es la que las engloba a todas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e5") }, {"long_answer": "Los sistemas de retención infantil adecuados a la talla y el peso del niño, correctamente instalados, pueden prevenir hasta el 90% de las lesiones graves o mortales en caso de accidente de circulación, lo que los convierte en la medida de seguridad vial más eficaz para la población infantil. Su eficacia depende de su uso en todos los trayectos, incluso los cortos, y de una instalación correcta, preferiblemente a contramarcha el mayor tiempo posible. Los porcentajes del 50% y del 75% infravaloran el beneficio, y ninguna medida evita el 100% de las lesiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e6") }, {"option_4": "Llevarlos en brazos de un adulto en trayectos cortos", "long_answer": "La recomendación es que los niños viajen a contramarcha, es decir, en sentido contrario a la marcha, el mayor tiempo posible, al menos hasta los 15 meses y preferiblemente hasta los 4 años, porque en esta posición la silla reparte las fuerzas de una colisión frontal por toda la espalda y protege mejor la cabeza y el cuello, cuya musculatura aún no está desarrollada. Viajar mirando hacia adelante a edades tempranas aumenta el riesgo de lesión cervical, no usar sistemas de retención está contraindicado y llevar al niño en brazos, aunque el trayecto sea corto, es muy peligroso y está prohibido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771e8") }, {"long_answer": "Cuando se viaja en autobús con un bebé en su carrito, la recomendación es utilizar las fijaciones o anclajes disponibles en el espacio reservado, accionar el freno del carrito y colocarlo en sentido contrario a la marcha, apoyado contra el respaldo, para que no se desplace con los frenazos o curvas. Dejar al bebé suelto en el carrito, no usar el freno o situarlo en el sentido de la marcha aumentan el riesgo de que el carrito vuelque o se desplace y de que el niño sufra lesiones, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ed") }, {"long_answer": "Según el Protocolo común de actuación sanitaria frente a la violencia en la infancia y la adolescencia, la creación de la Comisión frente a la Violencia en los Niños, Niñas y Adolescentes del Consejo Interterritorial del SNS (CoViNNA) se acordó en mayo de 2022, en cumplimiento de la Ley Orgánica 8/2021 de protección integral a la infancia y la adolescencia frente a la violencia (LOPIVI). Esta comisión se encarga de impulsar actuaciones sanitarias de prevención, detección precoz y atención, entre ellas la elaboración del protocolo común. Las fechas de junio de 2021, abril de 2022 y diciembre de 2023 no corresponden a dicho acuerdo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771ef") }, {"long_answer": "Dentro de la CoViNNA se constituyó el Grupo de Trabajo Protocolo, cuya función es la elaboración del Protocolo Común de Actuación Sanitaria frente a la violencia contra niños, niñas y adolescentes, que establece pautas homogéneas para la prevención, detección, atención y derivación de estos casos en todo el SNS. La elaboración del informe anual, la detección precoz de la violencia y la promoción del buen trato a la infancia son objetivos o tareas de la comisión en su conjunto o de otros grupos, no la finalidad específica para la que se creó este grupo de trabajo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771f1") }, {"long_answer": "El nuevo Protocolo común de actuación sanitaria frente a la violencia contra la infancia y la adolescencia incorpora un apartado de situaciones particulares, entre las que se incluyen la sumisión química y las agresiones con objeto punzante, conocidas como pinchazos, que exigen una actuación sanitaria específica en la toma de muestras, la valoración clínica y la comunicación a las autoridades. La elaboración del informe anual, la difusión, monitorización y evaluación del protocolo y el apoyo en la planificación de medidas son aspectos organizativos del propio protocolo o de la CoViNNA, no situaciones particulares de violencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771f4") }, {"long_answer": "La actividad física regular mejora la salud cardiovascular, porque reduce la presión arterial, mejora el perfil lipídico y la sensibilidad a la insulina, favorece el control del peso y disminuye el riesgo de cardiopatía isquémica e ictus. Además, aumenta la capacidad cardiorrespiratoria, fortalece músculos y huesos, mejora la salud mental y reduce el riesgo de varios tipos de cáncer. Las demás opciones describen efectos contrarios a los reales: la actividad física no reduce la capacidad pulmonar ni la movilidad, y bien planificada y progresiva no aumenta de forma relevante el riesgo de lesiones, sino que contribuye a prevenirlas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9771fd") }, {"long_answer": "Las recomendaciones de actividad física del Ministerio de Sanidad para niños y niñas de 6 a 12 años, al igual que las de la OMS para la población de 5 a 17 años, establecen al menos 60 minutos diarios de actividad física de intensidad moderada a vigorosa, que pueden repartirse en varios periodos a lo largo del día, incluyendo al menos tres días a la semana actividades vigorosas y de fortalecimiento muscular y óseo. Caminar dos horas al día no es la recomendación establecida, el deporte competitivo no es necesario y los videojuegos se consideran tiempo sedentario de pantalla, que debe limitarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977200") }, {"long_answer": "Al acercarse a un cruce en bicicleta o patinete, se debe enseñar a los niños y niñas a moderar la velocidad y a detenerse si es necesario, mirando a ambos lados y comprobando que no se aproximan vehículos antes de cruzar, respetando siempre las señales y semáforos. Esta conducta permite reaccionar a tiempo ante un conductor que no los ve, ya que los cruces son puntos de alto riesgo de atropello o colisión. Aumentar la velocidad, ignorar las señales o no prestar atención al entorno son conductas peligrosas que la educación vial pretende evitar, por lo que son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977209") }, {"option_1": "Solo deben usar cinturón los adultos, no los niños", "option_2": "Utilizar los sistemas de retención (cinturón o sillita) siempre que el autobús disponga de ellos", "long_answer": "En los autobuses interurbanos y escolares, los niños deben utilizar los sistemas de retención de que disponga el vehículo, sea el cinturón de seguridad o una sillita homologada adecuada a su talla y peso; la obligación de uso se aplica cuando el autobús cuenta con ellos. Su uso reduce de forma importante las lesiones en caso de frenazo o colisión. Afirmar que solo los adultos deben usar cinturón, que no es necesario en ningún caso o que solo los menores de tres años deben utilizarlo es incorrecto y contradice las recomendaciones de seguridad vial infantil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97720f") }, {"option_1": "Italia", "option_4": "Alemania", "long_answer": "En la temporada 2023-24, España fue uno de los primeros países del mundo, junto con Luxemburgo, Francia y EE.UU., en recomendar y utilizar de forma sistemática el anticuerpo monoclonal nirsevimab en recién nacidos durante la temporada y en lactantes menores de seis meses al inicio de esta, con el objetivo de reducir la morbimortalidad por VRS. Su implantación logró coberturas superiores al 90% y una reducción notable de las hospitalizaciones por bronquiolitis. Italia, Suecia y Alemania no lo incorporaron de forma sistemática en esa temporada, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97721b") }, {"long_answer": "En el ensayo pivotal MATISSE de la vacuna RSVpreF (Abrysvo) administrada a embarazadas, la eficacia frente a infección de vías respiratorias inferiores grave con asistencia médica por VRS en el lactante fue del 81,8% en los primeros 90 días de vida y descendió al 69,4% en los primeros 180 días, reflejando el descenso progresivo de los anticuerpos maternos transferidos. El valor del 81,8% corresponde a los 90 días, mientras que el 57,1% es la eficacia frente a la infección con asistencia médica de cualquier gravedad a 90 días, y el 40,6% no es la cifra de enfermedad grave a 180 días."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97721c") }, {"long_answer": "En el análisis del ensayo de la vacuna materna RSVpreF que recoge el documento, la eficacia frente a la infección de vías respiratorias inferiores con asistencia médica (IVRI AM) grave por VRS en el lactante a los 90 días de vida fue del 82,4%, el valor más alto observado, ya que la protección es máxima en los primeros meses, cuando los anticuerpos transferidos a través de la placenta son más abundantes. A medida que aumenta el tiempo desde el nacimiento la eficacia disminuye, por lo que los valores de 73,5%, 70,5% y 57,6% corresponden a otros desenlaces o a periodos de seguimiento más largos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97721e") }, {"long_answer": "En el ensayo MATISSE de la vacuna RSVpreF administrada durante el embarazo, la eficacia frente a la infección de vías respiratorias inferiores con asistencia médica (IVRI AM) por VRS, de cualquier gravedad, fue del 57,1% en los primeros 90 días de vida del lactante, cifra inferior a la observada frente a las formas graves, en torno al 82%. A los 180 días la eficacia frente a este desenlace se situó alrededor del 51%. Los valores de 54,5%, 50,0% y 49,2% no se corresponden con la eficacia a 90 días frente a IVRI AM por VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977222") }, {"long_answer": "En el ensayo de la vacuna materna RSVpreF, la incidencia de parto prematuro fue del 5,7% en el grupo de hijos e hijas de mujeres vacunadas, frente al 4,7% en el grupo placebo, diferencia que no alcanzó significación estadística. Aun así, por precaución, la autorización en la UE sitúa la administración a partir de la semana 24 de gestación y algunas recomendaciones, como la de EE.UU., la limitan a las semanas 32 a 36. Por tanto, el dato del grupo vacunado es 5,7%, y el 4,7% corresponde al grupo placebo, no al de vacunadas; 5,1% y 4,4% no son cifras del estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977226") }, {"long_answer": "El estudio realizado en Cataluña durante la temporada 2023-24 estimó que una dosis de nirsevimab redujo en torno a un 55% las visitas a urgencias hospitalarias por bronquiolitis en lactantes, mientras que la efectividad frente a hospitalización fue muy superior, cercana al 87%, y frente a ingreso en UCI alrededor del 90%. La reducción de consultas en atención primaria fue menor, en torno al 48%. Por tanto, el 48% corresponde a atención primaria y no a urgencias; el 82% y el 61% no son las cifras de este desenlace en el estudio catalán."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977228") }, {"long_answer": "En Galicia, que inició la inmunización con nirsevimab en la temporada 2023-24, la reducción muy significativa de las tasas semanales de hospitalización por VRS se observó en la cohorte de lactantes nacidos entre abril y septiembre de 2023, es decir, los menores de 6 meses inmunizados en la campaña de captación al inicio de la temporada, además de en los nacidos durante ella. Los nacidos entre abril y marzo del año anterior, en su segunda temporada, no formaban parte de la población diana general, salvo los de riesgo, por lo que no son la cohorte descrita. Los menores de 2 meses y los nacidos el año previo tampoco corresponden al dato recogido.", "answer": 3});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97722a") }, {"long_answer": "El estudio NIRSE-GAL, realizado en Galicia en la temporada 2023-24, estimó una efectividad del 82% de nirsevimab frente a hospitalizaciones por infección de vías respiratorias inferiores por VRS en los lactantes inmunizados, con coberturas de inmunización superiores al 90%. Este resultado es coherente con el obtenido en el ensayo HARMONIE y en otros estudios de vida real realizados en España. Los valores de 65,6%, 69,2% y 86,9% no corresponden a la efectividad estimada para este desenlace en Galicia, aunque algunos se aproximan a resultados de otros estudios o de otros desenlaces."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97722b") }, {"long_answer": "El estudio de impacto basado en los datos del Sistema de Vigilancia de Infección Respiratoria Aguda (SiVIRA) estimó que la administración de nirsevimab en la temporada 2023-24 habría evitado entre 7.510 y 10.213 hospitalizaciones por VRS en menores de un año en España durante el periodo de estudio, lo que supone una reducción de alrededor del 70-80% respecto a lo esperado. Este dato respalda el impacto poblacional de la estrategia de inmunización universal. Los intervalos de 2.000-4.000, 5.000-7.000 y 10.000-12.000 no corresponden a la estimación publicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97722e") }, {"long_answer": "Según la tabla de estrategias internacionales que recoge el documento, Irlanda recomienda la inmunización con nirsevimab en recién nacidos y la captación de lactantes menores de seis meses, contemplando además la posibilidad de vacunación materna entre las semanas 32 y 36 de gestación como estrategia complementaria. Cada país ha elegido una combinación distinta de anticuerpo monoclonal y vacuna materna según sus recursos y su epidemiología. Bélgica, EE.UU. y Países Bajos aparecen en el documento con estrategias que difieren en la edad de captación o en las semanas de vacunación materna, por lo que no se corresponden con la descrita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97722f") }, {"long_answer": "Según el documento, Finlandia recomienda la inmunización con nirsevimab en lactantes menores de tres meses que presentan determinadas condiciones de riesgo, con independencia de que la madre haya sido vacunada durante el embarazo, ya que en estos niños la protección materna puede ser insuficiente. Se trata de una estrategia más restrictiva que la universal adoptada en España, que incluye a todos los menores de seis meses al inicio de la temporada. Las franjas de 3-6, 6-9 y 9-12 meses no corresponden a la recomendación finlandesa recogida en la comparación internacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977230") }, {"long_answer": "Según la comparativa internacional del documento, Bélgica recomienda la inmunización con nirsevimab de los recién nacidos y la captación de lactantes menores de ocho meses, y contempla la posibilidad de vacunación materna entre las semanas 28 y 36 de gestación, combinando ambas estrategias según la situación de cada familia. Austria, EE.UU. y Canadá aparecen con recomendaciones que difieren en la edad de captación o en el intervalo de semanas para la vacunación materna; por ejemplo, EE.UU. limita la vacuna en embarazadas a las semanas 32 a 36. Por ello la respuesta correcta es Bélgica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977232") }, {"long_answer": "Entre las desventajas de la vacunación de embarazadas frente al VRS, el documento destaca un posible problema de aceptabilidad por parte de la población, ya que una parte de las gestantes muestra reticencia a vacunarse durante el embarazo, lo que limita la cobertura alcanzable y, con ello, la protección del lactante. La falta de protección antes de administrar el anticuerpo monoclonal es una limitación propia de la estrategia con nirsevimab, no de la vacunación materna, y la carga de trabajo no se señala como desventaja principal, por lo que la opción todas las anteriores tampoco es correcta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977234") }, {"long_answer": "El virus respiratorio sincitial (VRS) es la principal causa de infección de vías respiratorias inferiores, bronquiolitis y neumonía, en la población infantil menor de un año, y la primera causa de hospitalización por infección respiratoria en este grupo, sobre todo en los primeros meses de vida y en prematuros. Por ello se han incorporado estrategias de inmunización como nirsevimab o la vacunación materna. El adenovirus, el rinovirus y el virus de la gripe también causan infecciones respiratorias en lactantes, pero con una carga de enfermedad grave de vías bajas claramente inferior a la del VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97723a") }, {"long_answer": "La vacuna RSVpreF (Abrysvo), basada en la proteína F en conformación de prefusión, fue autorizada en la Unión Europea en 2023 para su administración a embarazadas, de modo que los anticuerpos maternos transferidos por vía placentaria inmunizan pasivamente al recién nacido y lo protegen frente al VRS hasta los seis meses de edad. Nirsevimab y palivizumab son anticuerpos monoclonales que se administran directamente al lactante, no vacunas, y mepolizumab es un anticuerpo anti-interleucina 5 empleado en el asma eosinofílica grave, sin relación con el VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97723d") }, {"long_answer": "En la temporada 2023-24, la vacunación de embarazadas frente al VRS con RSVpreF se utilizó en programas de salud pública en EE.UU., que la recomendó entre las semanas 32 y 36 de gestación como alternativa a nirsevimab, y en Argentina, que la incorporó a su calendario nacional. España optó por la inmunización universal con nirsevimab, al igual que Francia, que empleó también este anticuerpo, y en Portugal, Alemania, China y Rusia no se implantó la vacunación materna en esa temporada, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97723f") }, {"long_answer": "La utilización de nirsevimab en España en la temporada 2023-24, con coberturas superiores al 90% en la mayoría de comunidades autónomas, se tradujo en una reducción de entre el 71% y el 77% de las hospitalizaciones por VRS en menores de un año respecto a lo esperado, según las estimaciones de impacto que recoge el documento. Una reducción del 50% infravalora el efecto observado; el 90% de efectividad no es el dato de impacto poblacional descrito; y un aumento de hospitalizaciones contradice los resultados obtenidos, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977249") }, {"long_answer": "En el VRS, la glicoproteína G es la responsable de la unión del virus al receptor de la célula huésped, iniciando la infección, mientras que la proteína F, de fusión, permite la fusión de la envoltura viral con la membrana celular y la formación de sincitios. La proteína F, especialmente en su conformación de prefusión, es la diana de nirsevimab y de las vacunas actuales por estar muy conservada. Las proteínas H y J no forman parte de la estructura del VRS, por lo que la respuesta correcta es la proteína G."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97724b") }, {"option_2": "Respuesta de hipersensibilidad tipo I", "long_answer": "En la primera etapa de la infección por VRS se desencadena la respuesta inmune innata: las células del epitelio respiratorio reconocen el virus mediante receptores de reconocimiento de patrones y liberan interferones y citocinas que reclutan neutrófilos, macrófagos y células NK. Esta respuesta inespecífica precede a la adaptativa, humoral y celular, que se desarrolla días después y genera anticuerpos y linfocitos T específicos, aunque deja una inmunidad incompleta que permite reinfecciones. La hipersensibilidad tipo I, mediada por IgE, no es el mecanismo inicial de defensa frente al virus."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97724f") }, {"option_3": "En los dos primeros años de vida", "long_answer": "La primera infección sintomática por VRS se produce habitualmente en los dos primeros años de vida: prácticamente todos los niños se han infectado antes de los dos años y la mayor gravedad se concentra en los primeros meses, cuando el calibre de la vía aérea es pequeño y la inmunidad es inmadura. La infección no deja inmunidad duradera, por lo que las reinfecciones son frecuentes a lo largo de la vida, generalmente más leves salvo en mayores y personas con comorbilidades. Las franjas de 2-4, 5-10 y 10-15 años no corresponden a la primoinfección habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977251") }, {"long_answer": "Aunque el VRS se asocia sobre todo a la infancia, el documento destaca que su carga en adultos es relevante: según los datos de vigilancia en atención primaria que recoge, alrededor del 45% de los casos de VRS atendidos en este nivel corresponden a personas mayores de 65 años. Este dato, junto con las elevadas tasas de hospitalización y mortalidad en edades avanzadas, justifica la recomendación de vacunación frente al VRS en personas mayores. Los porcentajes de 25%, 35% y 55% no corresponden a la proporción descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977252") }, {"long_answer": "Al analizar las consultas en atención primaria por VRS en población adulta, el documento señala que el grupo de 60 a 64 años es el que presenta las tasas de incidencia más altas, superiores a 1.000 casos por 100.000 habitantes, lo que muestra que la carga de enfermedad comienza a aumentar ya antes de los 65 años. Los grupos de 45 a 59 años presentan tasas inferiores. Hay que tener en cuenta que la pregunta se refiere a los grupos de adultos incluidos en las opciones, por lo que la respuesta correcta es la franja de 60 a 64 años."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977256") }, {"long_answer": "La tasa de hospitalización por VRS en adultos aumenta de forma progresiva con la edad, y el documento señala que la más alta corresponde al grupo de 85 a 89 años, debido a la inmunosenescencia, la mayor prevalencia de comorbilidades cardiorrespiratorias y la fragilidad, que favorecen complicaciones como la neumonía o la descompensación de enfermedades crónicas. Los grupos de 65 a 74, 75 a 79 y 80 a 84 años presentan también tasas elevadas, pero inferiores a las del grupo de mayor edad, por lo que no son la respuesta correcta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97725a") }, {"long_answer": "Entre las personas hospitalizadas por VRS, la mayor proporción de fallecimientos se produce en el grupo de 85 a 89 años, en el que confluyen la inmunosenescencia, la fragilidad y la elevada carga de comorbilidades, que agravan la infección y sus complicaciones. La letalidad hospitalaria aumenta con la edad, por lo que los grupos de 65 a 69, 70 a 74 y 75 a 79 años presentan proporciones menores. Estos datos refuerzan la priorización de la vacunación frente al VRS en las personas de edad más avanzada y en las institucionalizadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97725b") }, {"long_answer": "Según los datos que recoge el documento, la tasa de ataque de VRS en adultos receptores de trasplante pulmonar es del 8,49%, una cifra elevada que refleja la vulnerabilidad de estos pacientes por la inmunosupresión y por afectar directamente al órgano trasplantado, en el que la infección puede desencadenar rechazo crónico. Por ello se consideran un grupo de riesgo en el que se plantea la vacunación frente al VRS. Los valores de 6,6%, 11% y 15% no corresponden a la tasa de ataque descrita para este grupo en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977260") }, {"answer": 1, "long_answer": "El primer ensayo clínico fase I/II de la vacuna RSVPreF3 adyuvada (con AS01E) tuvo como objetivo evaluar su seguridad, reactogenicidad e inmunogenicidad, medida al mes de la segunda dosis, en adultos jóvenes y posteriormente en mayores, para seleccionar la formulación y la dosis. Los ensayos de fase I/II no están diseñados para medir eficacia clínica, que se evaluó en el estudio fase III AReSVi-006 en adultos de 60 o más años frente a enfermedad del tracto respiratorio inferior por VRS. La inmunogenicidad en adultos de 50 a 59 años se estudió en otro ensayo posterior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977266") }, {"long_answer": "En el ensayo AReSVi-006 de la vacuna RSVPreF3 adyuvada, el documento recoge para el subgrupo analizado una eficacia del 67,2% frente a enfermedad del tracto respiratorio inferior (ETRI) por VRS en la segunda temporada, inferior a la observada en la primera, que superaba el 80%. Este descenso de la protección con el tiempo ha motivado la evaluación de la necesidad y el momento de la revacunación. Los valores de 78,8%, 55,9% y 81,5% corresponden a otros subgrupos, periodos o desenlaces, y no a la eficacia descrita para este grupo en la segunda temporada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977268") }, {"option_2": "Estudio AReSVi-018", "long_answer": "La no inferioridad de la respuesta inmune de la vacuna RSVPreF3 adyuvada en adultos de 50 a 59 años, incluidos los que presentan mayor riesgo por comorbilidades, respecto a los mayores de 60 años se evaluó en el estudio AReSVi-018, cuyos resultados permitieron ampliar la indicación a partir de los 50 años en personas con mayor riesgo. El estudio AReSVi-006 es el ensayo pivotal de eficacia en mayores de 60 años, el AReSVi-004 evaluó la persistencia de la respuesta y la revacunación, y el AReSVi-002 es el ensayo fase I/II inicial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977272") }, {"question": "Según el documento, ¿a partir de qué edad se autorizaron inicialmente en la UE las tres vacunas frente al VRS destinadas a adultos mayores?", "long_answer": "Las tres vacunas frente al VRS destinadas a adultos mayores, Arexvy (RSVPreF3 adyuvada), Abrysvo (RSVpreF bivalente) y mResvia (de ARNm), fueron autorizadas inicialmente en la Unión Europea para su uso en personas de 60 años o más, población en la que se realizaron los ensayos pivotales de eficacia frente a enfermedad del tracto respiratorio inferior por VRS. Posteriormente se han ido ampliando algunas indicaciones a edades inferiores en personas con riesgo aumentado. Las edades de 50, 55 y 65 años no corresponden a la autorización inicial común de las tres vacunas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97727e") }, {"long_answer": "La definición de error de medicación adoptada por la OMS y otros organismos lo considera cualquier incidente prevenible que puede causar daño al paciente o dar lugar a una utilización inapropiada de los medicamentos, cuando estos están bajo el control de los profesionales sanitarios, del paciente o del consumidor. Puede producirse en cualquier fase: prescripción, transcripción, dispensación, preparación, administración o seguimiento. No se limita a incidentes sin daño, no equivale al uso apropiado de los medicamentos y no se restringe a las vacunas, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977280") }, {"long_answer": "El tercer reto mundial de seguridad del paciente de la OMS, Medicación sin daño, lanzado en 2017, tiene como objetivo reducir en un 50% los daños graves y evitables asociados a los medicamentos en un plazo de cinco años, actuando sobre pacientes, profesionales, medicamentos y sistemas de utilización. El primer reto, Una atención limpia es una atención más segura, se centró en la higiene de manos, y el segundo, La cirugía segura salva vidas, en la seguridad quirúrgica. Reducir en un 25% los daños, mejorar la eficiencia o prevenir solo los errores de prescripción no definen este reto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977285") }, {"long_answer": "Una de las particularidades más importantes de la medicación en pediatría es la falta de disponibilidad de presentaciones y formas farmacéuticas adaptadas a los niños, lo que obliga a manipular, diluir o fraccionar medicamentos diseñados para adultos y a realizar cálculos de dosis según el peso o la superficie corporal, con mayor riesgo de errores de hasta diez veces la dosis. Además, los niños requieren ajuste de dosis, presentan una farmacocinética y farmacodinámica distintas según la edad y toleran peor los eventos adversos, por lo que las demás opciones son falsas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97728b") }, {"long_answer": "Se recomienda utilizar como referencia en los hospitales la lista de medicamentos de alto riesgo establecida por el ISMP porque se elabora a partir de estudios sobre eventos adversos prevenibles por medicamentos y de los errores comunicados a sus sistemas de notificación, identificando los fármacos que, cuando se utilizan incorrectamente, tienen mayor probabilidad de causar daños graves o mortales. No se justifica por incluir un amplio espectro de medicamentos, ya que su valor es precisamente la selección, ni por ser más actualizada que otras listas, por lo que las demás opciones no son la razón correcta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977296") }, {"long_answer": "En la prevención de errores con medicamentos de alto riesgo, deben limitarse las prácticas que dependen de la memoria humana o de la vigilancia de los profesionales, como las advertencias, la formación aislada o la confianza en que se recuerden las dosis, porque son las de menor efectividad. En su lugar se priorizan las prácticas de alta efectividad, basadas en la estandarización, la automatización y la informatización, como la prescripción electrónica con alertas o las bombas inteligentes. Por tanto, no deben limitarse las prácticas automatizadas ni las moderadamente efectivas, y la opción ninguna de las anteriores es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977297") }, {"long_answer": "Las recomendaciones sobre medicamentos de alto riesgo indican que los centros sanitarios deben combinar prácticas de alta efectividad, como la estandarización, la automatización o las funciones forzadas, con prácticas de efectividad baja o moderada, como la formación, las alertas o el doble chequeo, ya que ninguna práctica aislada es suficiente para prevenir todos los errores. Depender únicamente de prácticas de baja efectividad es insuficiente, prescindir completamente de ellas desaprovecha su efecto complementario y aplicar solo las de alta efectividad no siempre es factible, por lo que la respuesta correcta es la combinación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977298") }, {"long_answer": "Es más probable lograr mejoras implantando pocas prácticas de alta efectividad que muchas de baja efectividad porque las primeras, basadas en el diseño de los sistemas, la estandarización, la automatización o las funciones forzadas, tienen un mayor impacto al no depender de la memoria ni de la atención de las personas. Las prácticas de baja efectividad no son innecesarias, pues complementan a las anteriores, ni son más difíciles de implantar; en realidad suelen ser más sencillas, pero su impacto aislado es menor. Por ello, las demás opciones no explican la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977299") }, {"long_answer": "Es necesario combinar distintas prácticas de prevención de errores con medicamentos de alto riesgo porque ninguna práctica, por sí sola, es totalmente efectiva para evitar todos los errores que pueden producirse a lo largo del proceso de utilización del medicamento. Combinar varias barreras, de alta y baja efectividad, en distintos puntos del circuito reduce la probabilidad de que un error alcance al paciente, según el modelo de capas de defensa. El motivo no es que las prácticas de alta efectividad sean menos costosas ni que exista un requisito normativo, por lo que las demás opciones no son correctas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97729a") }, {"question": "¿Qué recomendación se hace para reducir errores en la administración intravenosa de medicamentos de alto riesgo en pacientes pediátricos?", "long_answer": "Para reducir errores en la administración intravenosa de medicamentos de alto riesgo en pediatría se recomienda disponer de bombas de infusión inteligentes con bibliotecas de fármacos que incluyan límites de dosis y concentraciones estandarizadas por peso, capaces de alertar o bloquear la programación de dosis fuera de rango, algo especialmente útil dada la variabilidad de dosis en niños. Las letras mayúsculas resaltadas actúan sobre la confusión entre nombres similares en el almacenamiento y la prescripción, y las encuestas a profesionales o la notificación de incidentes son medidas de gestión del riesgo, no barreras en el momento de la administración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97729d") }, {"option_1": "Administrar el aminoglucósido en bolo intravenoso rápido", "option_3": "Preparar las diluciones según el criterio de cada profesional", "option_4": "Evitar el doble chequeo para agilizar la administración", "long_answer": "Para reducir errores en la administración de aminoglucósidos en pediatría, fármacos de alto riesgo por su estrecho margen terapéutico y su nefrotoxicidad y ototoxicidad, se recomienda administrar las infusiones intravenosas mediante una bomba de infusión inteligente con biblioteca de fármacos, que controla la velocidad y alerta ante programaciones erróneas. Deben administrarse en infusión intermitente y no en bolo rápido; las diluciones deben seguir protocolos estandarizados y no el criterio individual; y el doble chequeo independiente es una práctica recomendada, por lo que evitarlo es incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772a9") }, {"long_answer": "Para evitar errores al administrar medicamentos líquidos a los niños se recomienda no intercambiar los dosificadores de diferentes medicamentos, ya que cada uno está calibrado para su presentación y concentración, y usar uno distinto puede provocar errores de dosis importantes. Además, se aconseja medir con la jeringa oral o el cuentagotas que incluye el envase y agitar el frasco antes de cada uso en las suspensiones. Utilizar una cuchara doméstica, no agitar el frasco o no emplear el dosificador indicado son prácticas que favorecen la administración de dosis incorrectas, por lo que son falsas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b2") }, {"long_answer": "En relación con los centros sanitarios, el documento distingue entre normas de autorización y normas de acreditación. Las normas de autorización, reguladas en el Real Decreto 1277/2003 y en la normativa autonómica, establecen los requisitos mínimos que debe cumplir un centro para poder funcionar e inscribirse en el registro. Las de acreditación son de carácter voluntario y reconocen niveles de calidad superiores a esos mínimos. Las expresiones habilitación y registro, certificación y validación o verificación y control no corresponden a las dos categorías de normas que describe el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b6") }, {"long_answer": "La experiencia acumulada y la evolución de las técnicas quirúrgicas, con procedimientos menos invasivos, y de las técnicas anestésicas, con fármacos de acción más corta y mejor control del dolor y de las náuseas, han aumentado la seguridad de la cirugía mayor ambulatoria (CMA). Esta mayor seguridad obliga a revisar y ampliar las indicaciones, de modo que pacientes y procedimientos antes excluidos pueden hoy intervenirse sin ingreso. La eficacia, la calidad y el coste son dimensiones relevantes de la CMA, pero el cambio de indicación se fundamenta en la mejora de la seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b7") }, {"long_answer": "En el documento de estándares y recomendaciones del bloque quirúrgico (BQ) del Ministerio de Sanidad se citan como referencia las guías y criterios elaborados por sociedades científicas españolas, en particular la Asociación Española de Cirujanos y la Sociedad Española de Anestesiología, Reanimación y Terapéutica del Dolor, sobre organización, gestión y seguridad del BQ. La OCDE y la OMS elaboran informes y estrategias de carácter general; la Agencia de Calidad del Ministerio es quien promueve el propio documento de estándares; y la federación de asociaciones de enfermería no figura como autora de esas guías específicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772bb") }, {"option_3": "Sustituir el consentimiento informado escrito de la intervención.", "long_answer": "El documento de estándares del bloque quirúrgico recomienda que la información de acogida destinada a los pacientes ingresados incluya fotografías del BQ, de modo que el paciente y sus familiares puedan comprender mejor el proceso asistencial y el entorno al que va a acceder, reduciendo la ansiedad prequirúrgica. La información específica sobre el procedimiento y sus riesgos no forma parte de la información de acogida, sino del proceso de consentimiento informado, que debe realizarse de forma individualizada y que en ningún caso puede ser sustituido por un documento general de acogida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772bc") }, {"long_answer": "Según el artículo 8 de la Ley 41/2002, básica reguladora de la autonomía del paciente, el consentimiento informado es por regla general verbal, pero se prestará por escrito en los casos de intervención quirúrgica, procedimientos diagnósticos y terapéuticos invasivos y, en general, en la aplicación de procedimientos que suponen riesgos o inconvenientes de notoria y previsible repercusión negativa sobre la salud del paciente. La estancia en hospitalización convencional no requiere por sí misma consentimiento escrito, y las opciones que omiten la intervención quirúrgica están incompletas, por lo que no son correctas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c0") }, {"long_answer": "El listado de verificación de la seguridad quirúrgica de la OMS divide la intervención en tres fases: la entrada, antes de la inducción anestésica, en la que se confirma la identidad del paciente, el sitio quirúrgico, el consentimiento y los riesgos anestésicos; la pausa quirúrgica, antes de la incisión, con la presentación del equipo y la confirmación de la profilaxis antibiótica; y la salida, antes de que el paciente abandone el quirófano, con el recuento de instrumental, gasas y agujas y el etiquetado de muestras. Por tanto, no se divide en una, dos ni cuatro fases."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c2") }, {"option_4": "Herramientas estructuradas como SBAR, las sesiones informativas (briefing) y las de revisión (debriefing)", "long_answer": "Para facilitar el trabajo en equipo en el quirófano se recomienda utilizar herramientas de comunicación estructurada, como la técnica SBAR (situación, antecedentes, evaluación y recomendación), las sesiones informativas previas a la intervención (briefing) y las de revisión posteriores (debriefing), además del listado de verificación quirúrgica. Estas herramientas reducen la variabilidad de la información transmitida y los errores por fallos de comunicación, una de las principales causas de eventos adversos quirúrgicos. Los mensajes de texto, las llamadas telefónicas o los correos electrónicos no son herramientas estructuradas para el trabajo en equipo dentro del quirófano."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c9") }, {"long_answer": "Entre las normas básicas de asepsia quirúrgica de la AORN figura la higiene de manos antes y después del contacto con el paciente, además del lavado quirúrgico antes de la intervención, la vestimenta adecuada y el mantenimiento del campo estéril. La higiene de manos es la medida más eficaz para prevenir la transmisión de microorganismos. Vestir incorrectamente o no lavarse las manos son conductas contrarias a la asepsia, y la AORN no recomienda el uso de calzas para proteger el calzado de calle, ya que no han demostrado reducir la infección y su manipulación puede contaminar las manos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ce") }, {"option_2": "Realizar los recuentos entre dos enfermeras", "long_answer": "Para prevenir la retención inadvertida de cuerpos extraños se recomienda que los recuentos de gasas, compresas, agujas, torundas, instrumental y otros objetos se realicen en todos los procedimientos y entre dos enfermeras, la instrumentista y la circulante, de forma audible y simultánea, al inicio, antes del cierre de cavidades y al final de la intervención, registrando los resultados en el expediente intraoperatorio del paciente. Las demás opciones, no contar las gasas, no registrar los recuentos o no contar agujas y torundas en todos los procedimientos, son contrarias a esta recomendación y aumentan el riesgo de retención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d0") }, {"option_2": "Mantener los teléfonos móviles a más de un metro de distancia de los equipos y sistemas electromédicos", "long_answer": "Para el uso de teléfonos móviles en el bloque quirúrgico se recomienda controlar su utilización y mantenerlos a más de un metro de distancia de los equipos y sistemas electromédicos, con el fin de evitar interferencias electromagnéticas que puedan alterar su funcionamiento, y disponer de un espacio dentro del BQ donde su uso no esté restringido. Por tanto, no controlar la utilización de los móviles, no habilitar un espacio de uso libre o no evitar las posibles interferencias con los aparatos de electromedicina son prácticas contrarias a la recomendación, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d3") }, {"option_3": "Que los pacientes tengan un papel activo en la mejora de su seguridad", "long_answer": "Uno de los retos que plantea la OMS, a través de iniciativas como Pacientes por la seguridad del paciente, es que los pacientes tengan un papel activo en la mejora de su propia seguridad: informarse e implicarse en sus cuidados, participar en las decisiones sobre su tratamiento y preguntar para conocer su diagnóstico, pruebas, tratamiento y cuidados, por ejemplo confirmando su identidad o el lado de la intervención. Las demás opciones niegan esa implicación y ese derecho a la información, por lo que son contrarias al enfoque de la OMS y no pueden considerarse retos en seguridad del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d6") }, {"option_1": "Servicio de hostelería", "long_answer": "Las unidades finales clientes del bloque quirúrgico son los servicios quirúrgicos que utilizan sus quirófanos para intervenir a sus pacientes, como cirugía general, traumatología, urología, ginecología u oftalmología, que realiza un gran volumen de procedimientos, muchos de ellos en régimen de cirugía mayor ambulatoria. Medicina preventiva colabora con el BQ en el control de la infección y en la vigilancia ambiental, pero como servicio de apoyo, no como cliente; la gestión de residuos y el servicio de hostelería son servicios generales del hospital, no unidades asistenciales que utilicen el bloque."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d7") }, {"long_answer": "Según el Real Decreto 1030/2006, por el que se establece la cartera de servicios comunes del SNS, la cartera de servicios se define como el conjunto de técnicas, tecnologías o procedimientos, entendiendo por tales cada uno de los métodos, actividades y recursos basados en el conocimiento y la experimentación científica, mediante los que se hacen efectivas las prestaciones sanitarias. Las demás opciones restringen la definición a la gestión de pacientes, a los recursos para la cirugía o a la investigación científica, lo que no se corresponde con la definición normativa de cartera de servicios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772dc") }, {"long_answer": "Según las restricciones de acceso, el bloque quirúrgico se divide en tres zonas: de acceso general o no restringida, por la que pueden circular pacientes, familiares y personal con ropa de calle; de acceso limitado o semirrestringida, que exige pijama quirúrgico, gorro y calzado adecuado; y de acceso restringido, que comprende los quirófanos y las zonas de preparación, donde además es obligatoria la mascarilla. Esta zonificación busca controlar el tránsito y reducir el riesgo de infección. Las demás opciones clasifican por tipo de usuario o de uso, no por restricción de acceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772dd") }, {"long_answer": "Para el traslado del paciente desde la unidad de hospitalización convencional al quirófano se recomienda un sistema de transporte que reduzca las molestias para el paciente y la interferencia con las actividades clínicas, con recorridos cortos, directos y preferiblemente exclusivos, que preserven su intimidad y seguridad. No es necesario mantenerlo en su cama en todo momento, ya que suele transferirse a una camilla o mesa quirúrgica; no debe hacerse pasar por circulaciones limpias y sucias de forma indistinta; y el sistema no debe exigir un esfuerzo físico extraordinario al personal, por lo que esas opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772de") }, {"question": "¿Cuál de las siguientes es una actividad de enfermería en el área de preparación prequirúrgica?", "option_1": "Realizar la incisión quirúrgica", "option_3": "Prescribir la premedicación anestésica", "option_4": "Decidir la técnica anestésica que se va a emplear", "long_answer": "En el área de preparación prequirúrgica, la enfermera recibe al paciente, verifica su identidad y comprueba que dispone de las pruebas complementarias necesarias, el consentimiento informado y la preparación indicada, como ayuno, retirada de prótesis o canalización de vía venosa, además de aplicar las medidas pautadas. La comprobación de las pruebas complementarias es, por tanto, una actividad propia de enfermería. Realizar la incisión es competencia del cirujano, y prescribir la premedicación o decidir la técnica anestésica corresponde al anestesiólogo, por lo que las demás opciones no son actividades de enfermería."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772df") }, {"long_answer": "Al finalizar la intervención, antes del cierre definitivo y de que el paciente abandone el quirófano, la enfermera quirúrgica debe realizar el recuento del material quirúrgico, incluyendo gasas, compresas, agujas e instrumental, y confirmar que coincide con el recuento inicial, registrándolo, ya que forma parte de la fase de salida del listado de verificación quirúrgica y previene la retención de cuerpos extraños. Colaborar en la anestesia corresponde a fases previas, la preparación prequirúrgica se realiza antes de la intervención, y la coordinación de la salida del paciente no es la actividad característica que se señala al finalizar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e0") }, {"long_answer": "Al finalizar las actuaciones anestesiológicas en el quirófano, el anestesiólogo es responsable de anotar en la historia clínica las circunstancias del acto anestésico, como la técnica empleada, los fármacos administrados, las incidencias y el estado del paciente, ya que este registro garantiza la continuidad asistencial en la unidad de recuperación postanestésica. La preparación preanestésica es previa a la intervención; el alta del paciente no se indica al terminar la anestesia sino tras su recuperación; y la verificación de protocolos de ingreso en la URPA no es la responsabilidad que se destaca en ese momento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e1") }, {"option_2": "Unidad de recuperación postanestésica (URPA)", "long_answer": "Tras un procedimiento anestésico, el destino más probable del paciente es la unidad de recuperación postanestésica (URPA), donde se vigilan las constantes vitales, la recuperación de la conciencia y de los reflejos, el dolor, las náuseas y las posibles complicaciones inmediatas hasta que cumple criterios de alta a su unidad de destino. Solo una parte de los pacientes pasa directamente a una unidad de cuidados críticos, a la sala de hospitalización convencional o al hospital de día de CMA, y permanecer en el quirófano no constituye un destino postanestésico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e7") }, {"long_answer": "En la programación quirúrgica en bloque, cada servicio quirúrgico tiene asignados quirófanos en días y horarios fijos, lo que facilita la planificación y la previsión del inicio de las intervenciones, pero dificulta la programación de los casos de urgencia relativa o diferida, que no encuentran hueco en bloques ya ocupados. Aumentar la eficiencia en el uso de los quirófanos, permitir una mejor previsión de la hora de comienzo o facilitar la planificación de los equipos son ventajas de este sistema, no desventajas, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e9") }, {"long_answer": "Reservar una parte del tiempo quirúrgico como programación abierta, no asignada de forma fija a un servicio, permite disponer de flexibilidad para incluir intervenciones que no caben en los bloques asignados y así evitar las cancelaciones por falta de tiempo, además de facilitar la atención de casos de urgencia relativa. La programación abierta no busca suplir la falta de planificación de los quirófanos, que sigue existiendo, ni pretende generar o resolver un exceso de tiempo vacío, por lo que la respuesta que mejor refleja el problema que se evita son las cancelaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772eb") }, {"long_answer": "Según el documento de estándares del bloque quirúrgico, entre las funciones del coordinador médico del BQ está promover el estudio, por parte del Comité de Quirófanos, de los asuntos que afectan al funcionamiento del bloque, actuando como enlace entre los servicios quirúrgicos, la anestesia y la dirección. La planificación y dirección de la operativa diaria, la asignación de la cirugía programada en los quirófanos y la gestión de admisiones y urgencias se atribuyen a otras figuras o unidades, como la supervisión del bloque o la unidad de admisión, por lo que no son la función que se destaca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ed") }, {"long_answer": "La gestión de la documentación clínica corresponde a la unidad de admisión y de documentación clínica del hospital, encargada de custodiar, archivar y facilitar el acceso a la historia clínica conforme a la Ley 41/2002 y a la normativa de protección de datos, garantizando su integridad, confidencialidad y disponibilidad para la asistencia. La unidad de cuidados intensivos, la de cirugía general y la de pediatría generan y utilizan documentación clínica en su actividad asistencial, pero no son las instancias responsables de su gestión centralizada, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ee") }, {"long_answer": "Según el artículo 17 de la Ley 41/2002, básica reguladora de la autonomía del paciente, los centros sanitarios tienen la obligación de conservar la documentación clínica en condiciones que garanticen su correcto mantenimiento y seguridad durante el tiempo adecuado para la debida asistencia al paciente y, como mínimo, cinco años contados desde la fecha del alta de cada proceso asistencial. Algunas comunidades autónomas han fijado plazos superiores, pero el mínimo estatal es de cinco años, por lo que tres, siete o diez años no corresponden al plazo establecido en la ley básica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f4") }, {"long_answer": "El sistema de información del bloque quirúrgico incluye como componente esencial la gestión de pacientes: registro de la lista de espera, programación quirúrgica, admisión, seguimiento del circuito asistencial e información clínica de cada intervención, integrada con la historia clínica electrónica. Este componente permite planificar la actividad, evaluar el rendimiento de los quirófanos y garantizar la trazabilidad. La gestión de vacaciones del personal, el inventario de la cafetería o los precios de los servicios de limpieza no forman parte del sistema de información específico del BQ, por lo que son opciones incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772fb") }, {"option_3": "Número de plazas de aparcamiento del hospital", "long_answer": "En el dimensionado del bloque quirúrgico, es decir, en el cálculo del número de quirófanos necesarios, debe considerarse el rendimiento de la actividad quirúrgica por sala, que depende de las horas de funcionamiento, la duración media de las intervenciones, los tiempos de recambio y el índice de ocupación, junto con la demanda prevista. El número de pacientes atendidos en urgencias generales o las plazas de aparcamiento del hospital no son variables utilizadas para calcular las salas quirúrgicas necesarias, por lo que la opción todos los anteriores también es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772fc") }, {"long_answer": "El diseño de los bloques quirúrgicos, en relación con el control de la infección nosocomial, se basa en varios elementos complementarios: la segregación de circulaciones limpias y sucias, para evitar el cruce de material estéril con material usado y residuos; la ventilación del quirófano con presión positiva respecto a zonas adyacentes, renovaciones de aire y filtración de alta eficacia; y, en determinados quirófanos, la circulación de aire con flujo laminar unidireccional sobre el campo operatorio. Como cada una de las tres primeras opciones es correcta, la respuesta adecuada es la que las engloba a todas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977300") }, {"long_answer": "En la zona postquirúrgica, el oficio limpio se destina al almacenamiento del material fungible y de los productos limpios que se utilizan en la atención de los pacientes durante la recuperación postanestésica, como sueros, sistemas de infusión, apósitos o sondas. La ropa sucia y los residuos se depositan en el oficio sucio; los equipos portátiles de reanimación se guardan en el almacén de equipos; y los equipos y productos de limpieza se ubican en el cuarto de limpieza, por lo que las demás opciones corresponden a otros locales de esta zona."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977302") }, {"long_answer": "En la zona postquirúrgica del bloque, el almacén de equipos tiene como función guardar los equipos portátiles que se utilizan en la reanimación y el despertar de los pacientes, como monitores de transporte, bombas de infusión, respiradores portátiles o calentadores, de forma que estén disponibles, protegidos y listos para su uso. La lencería y el material estéril se almacenan en sus respectivos oficios, y la preparación de medicamentos se realiza en una zona específica con condiciones adecuadas, por lo que las demás opciones no corresponden a la función de este almacén."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97730c") }, {"long_answer": "En los locales de pública concurrencia, entre los que se incluyen los hospitales, el Reglamento Electrotécnico para Baja Tensión (ITC-BT-28) exige disponer de un suministro complementario al normal, procedente de un grupo electrógeno, baterías u otra fuente, cuyo objetivo es asegurar la alimentación eléctrica de los servicios de seguridad, como el alumbrado de emergencia, los sistemas contra incendios o los ascensores de evacuación, en caso de fallo del suministro normal. La eficiencia energética no es su finalidad, y la autonomía del alumbrado de emergencia o evitar el pánico son consecuencias concretas, no el objetivo general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977312") }, {"option_3": "Cable resistente al fuego (RF)", "long_answer": "En caso de un sistema de alimentación ininterrumpida (SAI) centralizado, que alimenta servicios críticos y de seguridad del bloque quirúrgico, se recomienda que el cableado de distribución sea resistente al fuego, identificado como RF, para que mantenga el suministro durante un tiempo determinado aunque se produzca un incendio y permita continuar la actividad y la evacuación con seguridad. El cable coaxial, la fibra óptica y el cable HDMI se utilizan para la transmisión de señales de datos o de imagen y no son conductores de potencia adecuados para la distribución eléctrica de un SAI."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977315") }, {"long_answer": "Para potencias elevadas se recomienda utilizar transformadores trifásicos, ya que reparten la carga entre las tres fases, ofrecen mayor rendimiento, menor volumen y coste por kilovatio y una distribución más equilibrada de la energía que varios transformadores monofásicos de potencia equivalente. Los transformadores monofásicos se reservan para potencias menores, como los transformadores de aislamiento de cada quirófano. Los términos transformador de potencia variable o de corriente constante no describen el tipo recomendado en el documento para estas instalaciones, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977316") }, {"long_answer": "Según las recomendaciones de instalaciones del bloque quirúrgico, para proteger el primario de un transformador de potencia elevada, de tipo trifásico, se recomienda un interruptor automático trifásico, coherente con el número de fases del circuito, que permita interrumpir la alimentación ante sobrecargas o cortocircuitos y aísle el equipo para su mantenimiento. Los interruptores monofásicos o bipolares no corresponden a la alimentación trifásica de estos transformadores, y la denominación omnipolar alude a una característica de corte, no al tipo de interruptor que recomienda el documento para esta protección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97731a") }, {"long_answer": "Debe limitarse el número de personas en el interior del quirófano para minimizar el riesgo de infección del sitio quirúrgico, ya que cada persona desprende partículas y microorganismos de la piel, y el número de ocupantes, sus movimientos y la apertura de puertas aumentan la contaminación microbiana del aire y alteran el régimen de ventilación. La sobrecarga de la climatización, los costes o la eficiencia del equipo pueden verse afectados, pero no constituyen el motivo principal de esta recomendación, que forma parte de las medidas de prevención de la infección quirúrgica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97731c") }, {"long_answer": "La sobrepresión o presión positiva del quirófano respecto a las zonas adyacentes tiene como objetivo evitar la entrada de aire desde áreas menos limpias al interior del quirófano a través de puertas y rendijas, de forma que el flujo de aire vaya siempre del local más limpio al menos limpio, lo que protege el campo quirúrgico de la contaminación. Evitar la salida de aire es el objetivo de la presión negativa, propia de las salas de aislamiento de infecciones de transmisión aérea; la circulación del aire y el control de la humedad dependen de otros parámetros de la climatización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977320") }, {"long_answer": "Para garantizar la estanqueidad de la red de conductos de climatización del bloque quirúrgico se recomiendan conductos de chapa galvanizada tipo METU, con uniones mecánicas y juntas que reducen las fugas de aire y permiten la limpieza interior. Los conductos de fibra con aislamiento interior no se recomiendan porque pueden desprender fibras, acumular suciedad y dificultan la limpieza y la desinfección; los conductos flexibles deben limitarse a tramos cortos de conexión; y la forma circular por sí sola no garantiza la estanqueidad exigida, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977321") }, {"long_answer": "Para sellar todas las juntas del sistema de conductos de climatización del bloque quirúrgico se recomienda una clase de estanqueidad C, según la clasificación de las normas UNE-EN de conductos metálicos, que admite unas fugas de aire muy reducidas. Una estanqueidad elevada evita pérdidas de caudal, mantiene las presiones diferenciales entre locales y reduce la entrada de contaminantes al aire tratado. Las clases A y B permiten fugas mayores, inadecuadas para un entorno quirúrgico, y la clase D, de máxima exigencia, no es la que recomienda el documento con carácter general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977322") }, {"long_answer": "Se recomienda instalar compuertas o registros de limpieza en las cercanías de todas las compuertas de regulación y cortafuegos de la red de conductos, ya que son puntos donde se acumula suciedad y que requieren inspección, mantenimiento y comprobación periódica de su funcionamiento. Estos registros facilitan la limpieza interior de los conductos y el acceso para revisar los elementos de regulación. La entrada de aire del climatizador, la difusión en la sala o la zona de recuperación no son los emplazamientos que el documento señala para estas compuertas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977328") }, {"long_answer": "Es recomendable alimentar la instalación de climatización del quirófano desde el grupo electrógeno y el sistema de alimentación ininterrumpida (SAI) para garantizar el suministro eléctrico en caso de corte del suministro normal, de modo que se mantengan la ventilación, la sobrepresión y la filtración del aire durante la intervención, evitando la contaminación del campo quirúrgico y la interrupción de la actividad. Esta medida no está destinada a ahorrar energía, reducir los costes de mantenimiento ni aumentar la velocidad del aire, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977330") }, {"long_answer": "Las tomas de extracción de gases anestésicos situadas en las torretas del anestesiólogo se conectan a un eyector alimentado por aire comprimido, que mediante efecto Venturi genera la depresión necesaria para aspirar los gases espirados sobrantes del circuito anestésico y evacuarlos al exterior, evitando la exposición del personal a los anestésicos inhalatorios. No se conectan a un compresor de aire, que produce aire a presión, ni a un tanque de almacenamiento o a un sistema de reciclaje, ya que estos gases se eliminan y no se reutilizan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977331") }, {"long_answer": "Las alarmas ópticas y acústicas permiten detectar de inmediato una caída de presión en cada toma de gases medicinales o de vacío para garantizar la seguridad de los pacientes, ya que de estos suministros dependen la oxigenación, la ventilación mecánica, la anestesia y la aspiración durante la intervención, y un fallo no detectado podría tener consecuencias graves. Aunque la caída de presión puede deberse a una fuga, el objetivo de la alarma no es solo detectarla, ni prevenir incendios o facilitar la supervisión del personal, sino permitir actuar rápidamente para proteger al paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977332") }, {"long_answer": "La información a pacientes y cuidadores para la prevención de la infección de localización quirúrgica debe incluir los riesgos de estas infecciones, las medidas para prevenirlas, como la ducha preoperatoria, no rasurar la zona o el cuidado de la herida, y los signos de alarma que deben vigilar tras el alta, como enrojecimiento, calor, dolor creciente, supuración o fiebre. Los efectos secundarios de los antibióticos, los beneficios de la cirugía o los tipos de vendajes pueden explicarse en otros contextos, pero no son el contenido central de la información orientada a prevenir la infección quirúrgica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977335") }, {"long_answer": "Antes de la primera intervención de la jornada, los miembros del equipo quirúrgico deben realizar la descontaminación quirúrgica de las manos con una solución antiséptica quirúrgica, con frotado con solución alcohólica de acción residual o con lavado con jabón antiséptico, limpiando además las uñas, para reducir al máximo la flora residente y transitoria bajo los guantes. El lavado con agua y jabón no antiséptico es insuficiente, la solución hidroalcohólica de uso en la higiene de manos habitual no sustituye a la preparación quirúrgica, y omitir la descontaminación es claramente incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977336") }, {"long_answer": "Según las recomendaciones de prevención de la infección de localización quirúrgica, durante las primeras 48 horas tras la cirugía debe utilizarse suero salino estéril para limpiar la herida, si es necesario, ya que no daña los tejidos en cicatrización y mantiene la esterilidad mientras la herida no está sellada. Pasadas las 48 horas, el paciente puede ducharse con agua corriente. El alcohol y el peróxido de hidrógeno son citotóxicos y retrasan la cicatrización, y el agua corriente no se recomienda en ese periodo inicial, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97733a") }, {"long_answer": "Según las normas de acceso del bloque quirúrgico que recoge el documento, los familiares autorizados para acompañar al paciente en el área de reanimación deben utilizar una bata verde desechable y cubrecalzado desechable, de modo que su ropa y su calzado de calle no introduzcan contaminación en esta zona. No se exigen guantes, que no aportan beneficio en este contexto, ni el traje quirúrgico completo con mascarilla y gorro, propio del personal que accede a la zona restringida, ni el pijama blanco con calzado exclusivo, que corresponde al personal del área."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97733c") }, {"long_answer": "La norma de acceso al quirófano, zona de acceso restringido del bloque quirúrgico, establece el uso obligatorio de pijama quirúrgico, calzas o calzado exclusivo, gorro que cubra todo el cabello y mascarilla quirúrgica, con el fin de reducir la dispersión de partículas y microorganismos en el entorno del campo estéril. La bata verde con guantes no constituye la vestimenta de acceso, y la restricción a personal no autorizado o a pacientes y familiares es una característica de la zona, pero no define la norma de vestimenta que se exige para entrar al quirófano."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97733d") }, {"long_answer": "Según la zonificación del bloque quirúrgico que describe el documento, la zona semirrestringida comprende el pasillo de acceso a los quirófanos y los almacenes, áreas en las que se exige pijama quirúrgico, gorro y calzado adecuado, aunque no necesariamente mascarilla. Los aseos del personal, el control central, la sala de trabajo y el estar del personal pertenecen a la zona de acceso limitado o no restringido, mientras que los quirófanos y los pasillos intermedios con lavabos forman parte de la zona restringida, por lo que las demás opciones no corresponden a la zona semirrestringida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97734f") }, {"long_answer": "El protocolo ITU-Zero señala que, en los últimos 15 años, el número de pacientes ingresados en las UCI españolas con infección del tracto urinario relacionada con sonda uretral (ITU-SU) ha seguido una tendencia ascendente, según los datos del registro ENVIN-HELICS, de modo que se ha convertido en una de las infecciones relacionadas con dispositivos más frecuentes en estas unidades. Este aumento justificó el desarrollo del proyecto ITU-Zero, con medidas para reducir el sondaje innecesario y mejorar su mantenimiento. Por tanto, no ha disminuido ni se ha mantenido constante, y sí existe información al respecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977357") }, {"long_answer": "Según los datos de vigilancia que recoge el protocolo ITU-Zero, el 30,39% de las cepas de Escherichia coli aisladas en infecciones del tracto urinario relacionadas con sonda uretral en UCI son resistentes a ciprofloxacino, lo que pone de manifiesto la elevada resistencia a fluoroquinolonas y la importancia de guiar el tratamiento por el antibiograma y de reducir el uso innecesario de sondas y antibióticos. Los valores de 30,50%, 35,40% y 21,50% no corresponden a la cifra publicada para este microorganismo y antibiótico, aunque alguno se aproxime a ella."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977362") }, {"option_2": "Evitar acodamientos del tubo y mantener la bolsa colectora por debajo del nivel de la vejiga", "long_answer": "Para mantener el flujo de orina libre de obstáculos en un paciente con sonda uretral, el protocolo ITU-Zero recomienda evitar acodamientos y torsiones del tubo y mantener la bolsa colectora siempre por debajo del nivel de la vejiga, sin que toque el suelo, para favorecer el drenaje por gravedad e impedir el reflujo de orina. Los lavados vesicales rutinarios no están indicados y aumentan el riesgo de infección; conectar la sonda al sistema colector es un paso del sondaje que no garantiza por sí mismo el flujo; y colocar la bolsa por encima de la vejiga favorece el reflujo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97736a") }, {"option_4": "Solo si las manos están visiblemente sucias", "long_answer": "En la atención a pacientes con sonda urinaria, el protocolo recomienda realizar la higiene de manos inmediatamente después de retirarse los guantes tras manipular drenajes o el sistema colector, ya que los guantes pueden presentar microperforaciones y las manos se contaminan al quitarlos. La higiene se realiza también antes de manipular el dispositivo, según los cinco momentos de la OMS, pero la pregunta se refiere al momento posterior a la manipulación. Limitar la higiene de manos a cuando están visiblemente sucias es incorrecto, y entrar en la habitación no es el momento que corresponde a lo preguntado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97736f") }, {"question": "Según el documento, ¿cuál es la principal causa de muerte entre los pacientes operados que presentan una infección nosocomial?", "long_answer": "Según el documento sobre prevención de la infección quirúrgica, la infección del sitio quirúrgico es la principal causa de muerte entre los pacientes operados que presentan una infección nosocomial, por delante de otras infecciones asociadas a la asistencia como las respiratorias, ya que puede progresar a infecciones de órgano o espacio y a sepsis. Por ello su prevención mediante medidas como la profilaxis antibiótica adecuada, la correcta preparación de la piel o la normotermia es prioritaria. La insuficiencia cardiaca y el cáncer no son infecciones nosocomiales, y las infecciones respiratorias, aunque frecuentes, no ocupan el primer lugar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977378") }, {"long_answer": "En el protocolo Infección Quirúrgica Zero, la antisepsia de la piel con clorhexidina alcohólica al 2% es una de las medidas del paquete preventivo y se apoya en un nivel de evidencia alto, con recomendación fuerte. Ensayos clínicos y metaanálisis muestran que reduce la infección de localización quirúrgica frente a la povidona yodada, gracias a la acción bactericida rápida del alcohol y al efecto residual de la clorhexidina. Por eso no son correctas las opciones de evidencia moderada, baja o muy baja: la recomendación no se basa en estudios observacionales ni en opiniones de expertos, sino en estudios de alta calidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97737a") }, {"long_answer": "El protocolo Infección Quirúrgica Zero indica aplicar la clorhexidina alcohólica al 2% sobre la piel limpia y seca, frotando durante al menos 30 segundos, y dejarla secar al aire un mínimo de 2 minutos antes de colocar los campos o de usar el bisturí eléctrico. Así se consigue el efecto antiséptico y se evita el riesgo de incendio por el alcohol. Diez segundos con secado inmediato es insuficiente, secar con toalla arrastra el antiséptico y elimina su efecto residual, y lavar con agua después de aplicarla anula su acción, por lo que las demás opciones son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97737b") }, {"long_answer": "La eliminación correcta del vello, es decir, no eliminarlo salvo que interfiera con la intervención y, si es necesario, hacerlo con cortadora eléctrica y no con cuchilla, es una de las medidas del protocolo Infección Quirúrgica Zero. Se apoya en un nivel de evidencia alto, procedente de ensayos clínicos y revisiones sistemáticas que demuestran que el rasurado con cuchilla aumenta la infección de localización quirúrgica. Por ello no son correctos los niveles moderado, bajo o muy bajo: la recomendación no se basa en estudios de menor calidad ni en consenso de expertos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977388") }, {"long_answer": "Entre las estrategias de implantación del protocolo Infección Quirúrgica Zero se propone adjuntar a la historia clínica del paciente un recordatorio o listado de verificación con las intervenciones preventivas (profilaxis antibiótica, antisepsia con clorhexidina alcohólica, eliminación correcta del vello, normotermia y normoglucemia). Así se facilita que el equipo las aplique y se deja constancia de su cumplimiento. No hacer ningún registro, confiar solo en la memoria del personal o considerar innecesario cualquier registro adicional va en contra de la filosofía del proyecto, basada en la verificación sistemática y la medición del cumplimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97738a") }, {"option_1": "Fiebre, vasodilatación periférica y taquicardia", "option_3": "Vasodilatación cutánea, hiperventilación y diuresis", "option_4": "Hiperventilación, diuresis y vasodilatación esplácnica", "long_answer": "Según el protocolo Infección Quirúrgica Zero, los sistemas de termorregulación más importantes en el ser humano son la sudoración, la vasoconstricción arteriovenosa y el temblor. Sudar permite perder calor, mientras que la vasoconstricción arteriovenosa y el temblor lo conservan y lo producen. La anestesia general y regional inhibe estas respuestas, lo que explica la facilidad con que aparece hipotermia perioperatoria. Las demás opciones no son correctas: la fiebre y la taquicardia no son mecanismos termorreguladores primarios, y la hiperventilación, la diuresis o la vasodilatación esplácnica no regulan la temperatura de forma significativa en humanos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977394") }, {"long_answer": "El Programa de Cirugía Segura del SNS se plantea varios objetivos específicos, entre ellos promover el uso del listado de verificación quirúrgica, impulsar la cultura de seguridad en los bloques quirúrgicos e implementar un programa nacional para la prevención y el control de la infección del sitio quirúrgico, que se concreta en el proyecto Infección Quirúrgica Zero. Evaluar la eficacia de los medicamentos no es un objetivo del programa, establecer una cirugía preventiva no tiene relación con él y reducir la seguridad de los pacientes es justo lo contrario de lo que persigue."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977397") }, {"long_answer": "El Programa de Cirugía Segura propone medir la cultura de seguridad en los bloques quirúrgicos porque permite identificar problemas en la comunicación y el trabajo en equipo entre los profesionales, que están detrás de muchos eventos adversos quirúrgicos. Con esta medición basal se pueden planificar intervenciones de mejora y valorar después su impacto. Evaluar la eficiencia del personal, la limpieza de los quirófanos o la disponibilidad de material son aspectos de gestión o de calidad estructural que los cuestionarios de cultura de seguridad no miden."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97739b") }, {"long_answer": "Para la fase piloto del Programa de Cirugía Segura se prevé que participen centros con especial interés en el proyecto que opten voluntariamente por incorporarse. La participación voluntaria favorece el compromiso de los equipos y la viabilidad de la implantación, que después se extiende al resto. No se seleccionan los centros por el número de quejas por errores, por tener menos de 100 camas ni por contar con una certificación de calidad, porque ninguno de esos criterios aparece en el diseño del programa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97739e") }, {"long_answer": "El Programa de Cirugía Segura recomienda recoger los datos en una plataforma digital creada para el proyecto, donde los centros participantes registran los indicadores de forma homogénea. Esto facilita el análisis agregado, la comparación entre hospitales y la devolución de resultados a los equipos. Las encuestas telefónicas a pacientes, los formularios en papel entregados a cada paciente y las entrevistas presenciales con el personal no son el instrumento previsto: son métodos más costosos, difíciles de estandarizar y poco prácticos para un registro multicéntrico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a1") }, {"long_answer": "El programa analiza el efecto de los listados de verificación quirúrgica sobre la seguridad del paciente y sobre la comunicación dentro del equipo de trabajo, porque su valor está en reducir complicaciones y mortalidad y en mejorar el trabajo en equipo en el quirófano. Reducir la duración de las cirugías no es su finalidad; de hecho, el listado añade unos minutos al proceso. Mejorar la relación entre pacientes y equipo médico no es el objetivo central, y aumentar la tasa de complicaciones es lo contrario de lo que se busca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a2") }, {"long_answer": "El listado de verificación quirúrgica de la OMS es una herramienta que apoya los procedimientos de práctica clínica mediante la comprobación sistemática de elementos críticos antes de la inducción, antes de la incisión y antes de que el paciente salga del quirófano, sin poner en duda el juicio clínico de los profesionales. La OMS insiste en que no es un instrumento normativo ni pretende sustituir ni cuestionar las decisiones clínicas. Tampoco busca excluir al equipo de la toma de decisiones: al contrario, fomenta la participación y la comunicación de todos sus miembros."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a4") }, {"question": "¿Qué crítica hicieron los autores del listado SURPASS al listado de verificación quirúrgica de la OMS?", "option_2": "Que se centra exclusivamente en la fase preoperatoria, previa al ingreso", "option_3": "Que se centra únicamente en la comunicación entre los miembros del equipo quirúrgico", "option_4": "Que no es efectivo para prevenir complicaciones quirúrgicas", "long_answer": "Los autores del sistema SURPASS señalaron que el listado de verificación de la OMS se centra excesivamente en el acto quirúrgico y en lo que ocurre dentro del quirófano, cuando muchos errores se producen antes del ingreso, en la planta o tras la intervención. Por ello SURPASS abarca todo el recorrido quirúrgico del paciente, desde la indicación hasta el alta. No es correcto decir que la crítica fuera que el listado de la OMS solo atiende a la fase preoperatoria o solo a la comunicación entre profesionales, ni que no fuera eficaz para prevenir complicaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a5") }, {"long_answer": "En los estudios recogidos por el Programa de Cirugía Segura, los profesionales destacan que el listado de verificación quirúrgica mejora la comunicación dentro del equipo y ayuda a prevenir errores, como la cirugía en lugar equivocado o la omisión de la profilaxis antibiótica. También refieren una mayor sensación de trabajo en equipo. Las demás opciones describen percepciones negativas, como la inseguridad sobre la pertenencia al equipo, la idea de que no mejora la seguridad o la resistencia al cambio, que no son lo que destacan mayoritariamente los profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a7") }, {"long_answer": "Las recomendaciones basadas en la evidencia indican valorar el riesgo de complicaciones trombóticas en todo paciente quirúrgico teniendo en cuenta tanto el tipo de cirugía (por ejemplo, ortopédica mayor u oncológica) como las características del paciente (edad, antecedentes de trombosis, cáncer, obesidad, inmovilidad). A partir de esa valoración se elige la profilaxis adecuada. Ajustar dosis de heparina o aplicar un método preventivo son pasos posteriores a la valoración, no la forma de valorar el riesgo, y afirmar que no es necesario valorarlo es incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ba") }, {"option_4": "Todas las anteriores", "answer": 4, "long_answer": "Según los estándares del Bloque Quirúrgico, la información que se da a los pacientes debe incluir una noción elemental de su patología quirúrgica, los beneficios esperados de la cirugía y sus posibles riesgos, la descripción de las fases por las que va a pasar y el calendario más frecuente de recuperación. Como las tres primeras opciones forman parte de esa información, la respuesta correcta es la que las engloba a todas. Ofrecer una información completa y comprensible facilita la toma de decisiones del paciente y su colaboración durante todo el proceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772bf") }, {"option_4": "Todas las anteriores", "answer": 4, "long_answer": "Los estándares del Bloque Quirúrgico establecen que los centros en los que existe un BQ deben disponer de una serie de documentos y procedimientos que garantizan los derechos de los pacientes y la seguridad jurídica, entre ellos la cartera de servicios, los procedimientos escritos para ensayos clínicos y el informe de alta, además de otros como el archivo de pólizas o el libro de reclamaciones. Como las tres primeras opciones forman parte de esa relación, la respuesta correcta es la que las incluye a todas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c4") }, {"option_2": "Prescindir de la formación del equipo quirúrgico", "long_answer": "Para prevenir los errores de localización, de procedimiento o de persona se recomienda realizar un proceso de verificación preoperatorio que confirme la identidad del paciente, el procedimiento y el lado o lugar correcto con la documentación y con el propio paciente, junto con el marcado del sitio quirúrgico y la pausa quirúrgica antes de la incisión. Las demás opciones van en sentido contrario a lo recomendado: la cultura de seguridad debe facilitar la comunicación abierta, la formación del equipo es necesaria y el uso de abreviaturas en la documentación debe evitarse porque induce a errores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c5") }, {"long_answer": "Los estándares del Bloque Quirúrgico describen el riesgo de incendio en el quirófano mediante el triángulo del fuego: comburente (oxígeno, óxido nitroso), fuente de ignición y combustible. Entre los materiales inflamables que pueden actuar como combustible se citan los tubos traqueales, los circuitos respiratorios y el material textil, como campos, gasas y batas, además de las soluciones con alcohol o el propio vello del paciente. Como las tres opciones son materiales inflamables señalados, la respuesta correcta es todos los anteriores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c6") }, {"option_1": "Suero fisiológico", "long_answer": "El láser es una de las principales fuentes de ignición en el quirófano, junto con el bisturí eléctrico, las fuentes de luz de fibra óptica y los desfibriladores. En presencia de un comburente como el oxígeno y de material inflamable puede desencadenar un incendio, especialmente en cirugía de vía aérea. El suero fisiológico no puede provocar ignición, las luces LED generan muy poco calor y no se consideran fuente relevante, y los equipos de resonancia magnética no se usan como fuente de calor en el campo quirúrgico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c7") }, {"long_answer": "Para minimizar el riesgo asociado al triángulo del fuego se recomienda proteger el vello corporal próximo al campo quirúrgico, por ejemplo cubriéndolo con gel hidrosoluble, porque es un combustible que puede prender. También se debe limitar la concentración de oxígeno, dejar secar por completo las soluciones antisépticas alcohólicas y evitar que se acumulen bajo los campos. Por eso son incorrectas las demás opciones: aumentar el oxígeno potencia la combustión, dejar el área mojada favorece la acumulación de vapores inflamables y usar soluciones inflamables incrementa el riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c8") }, {"long_answer": "Según los estándares del Bloque Quirúrgico, la infección de localización quirúrgica representa en torno al 14% de las infecciones nosocomiales, lo que la sitúa entre las más frecuentes en el hospital, junto a la infección urinaria, la respiratoria y la bacteriemia. Además prolonga la estancia, aumenta los costes y la morbimortalidad, y por eso es objeto de programas específicos como Infección Quirúrgica Zero. Los porcentajes del 10%, 20% y 25% no corresponden al dato que recoge la fuente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772cb") }, {"option_2": "Asegurar la trazabilidad del proceso de transfusión", "long_answer": "Entre las recomendaciones de seguridad para el manejo de hemoderivados está asegurar la trazabilidad de todo el proceso de transfusión, desde la extracción de la muestra para pruebas cruzadas hasta la administración y el registro del componente, además de la identificación inequívoca del receptor. Esto permite detectar y prevenir errores de compatibilidad. Las demás opciones describen prácticas contrarias a las recomendaciones: no identificar al receptor, no revisar los medicamentos de nombre o aspecto parecido y no limitar las órdenes verbales o telefónicas son factores que aumentan el riesgo de error."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772cc") }, {"long_answer": "Los estándares del Bloque Quirúrgico señalan que la atención a pacientes en edades extremas, niños y ancianos, debe guiarse por criterios específicos debido a sus características especiales: diferencias anatómicas y fisiológicas, mayor fragilidad, comorbilidad y polimedicación en los ancianos, o mayor riesgo de hipotermia y de errores de dosificación en los niños. Las demás opciones afirman lo contrario de la realidad: estos pacientes no tienen menor sensibilidad a las complicaciones ni mayor tolerancia a la anestesia, y en ellos prevenir complicaciones es más difícil, no más fácil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772cf") }, {"long_answer": "La cirugía de urgencia es uno de los principales factores de riesgo para la retención de cuerpos extraños, como gasas o instrumental, en la herida quirúrgica, junto con un cambio inesperado del procedimiento y un índice de masa corporal elevado. En estas situaciones el recuento sistemático es más difícil por la presión del tiempo. Por eso no son correctas la cirugía planificada, que es la situación de menor riesgo, ni un IMC bajo, ya que el factor de riesgo es la obesidad. La edad avanzada no figura entre los factores descritos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d1") }, {"option_1": "Concentrar las cirugías complejas en hospitales con alto volumen de actividad", "long_answer": "Entre las medidas para reducir los efectos adversos del proceso quirúrgico se recomienda concentrar las cirugías complejas en hospitales con un alto volumen de actividad, porque la experiencia acumulada del equipo y del centro se asocia a menor mortalidad y menos complicaciones. Las demás opciones van en sentido contrario a lo recomendado: se deben disponer equipos quirúrgicos de urgencia, prevenir la infección quirúrgica y realizar auditorías periódicas de los efectos adversos para aprender de ellos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d2") }, {"long_answer": "Los sistemas de notificación y análisis de incidentes, en el ámbito de cada departamento o servicio, son una herramienta básica de gestión de la seguridad en el Bloque Quirúrgico, porque permiten aprender de los errores y de los casi incidentes y poner en marcha medidas para evitar que se repitan. Las demás opciones describen lo contrario de lo que recomiendan los estándares: sí se debe establecer una taxonomía común en seguridad, implantar sistemas de notificación también a nivel nacional y promover la garantía jurídica de confidencialidad de quien notifica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d4") }, {"long_answer": "Los estándares del Ministerio definen el Bloque Quirúrgico como una organización de profesionales sanitarios que ofrece asistencia multidisciplinar a procesos asistenciales mediante cirugía, en un espacio donde se agrupan los quirófanos con sus locales de apoyo, y que cumple unos requisitos funcionales, estructurales y organizativos que garantizan condiciones de seguridad, calidad y eficiencia. Por eso la respuesta es una unidad organizativa de profesionales sanitarios. No es un simple espacio para pacientes, ni un área de hospitalización, ni un centro de rehabilitación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d5") }, {"long_answer": "Según los estándares del Bloque Quirúrgico, la unidad de cirugía mayor ambulatoria es uno de sus principales clientes, porque una parte muy importante de la actividad quirúrgica programada se realiza hoy de forma ambulatoria y comparte quirófanos y recursos del BQ. La cirugía pediátrica, la cirugía cardiaca y la interrupción voluntaria del embarazo son actividades más específicas, con menor volumen relativo o con circuitos propios, por lo que no se consideran el principal cliente del bloque."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e2") }, {"long_answer": "Los estándares del Bloque Quirúrgico consideran la programación de los quirófanos uno de los componentes más importantes de su gestión, porque de ella depende el rendimiento de un recurso muy costoso, el cumplimiento de los tiempos de espera y la coordinación de profesionales, camas y material. Una buena programación reduce cancelaciones, retrasos y tiempos muertos. El área de recepción, el proceso de recuperación y el protocolo de la unidad de recuperación postanestésica son elementos necesarios, pero no se señalan como el eje principal de la gestión del bloque."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e3") }, {"long_answer": "NCEPOD son las siglas de National Confidential Enquiry into Patient Outcome and Death, organismo británico que analiza las muertes y los resultados perioperatorios y que ha propuesto una clasificación de la urgencia quirúrgica en categorías (inmediata, urgente, preferente y programada). Esta clasificación se usa en los estándares del Bloque Quirúrgico para priorizar la cirugía no programada. Las demás opciones son traducciones inventadas que no corresponden a ninguna organización ni clasificación reconocida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e6") }, {"long_answer": "En la programación por bloques se asignan a cada cirujano o servicio franjas fijas de quirófano. A los cirujanos les resulta conveniente porque saben de antemano qué días y horas tienen quirófano y pueden planificar mejor su actividad quirúrgica y el resto de su trabajo. Este sistema no aporta mayor flexibilidad horaria; la rigidez es precisamente uno de sus inconvenientes. Tampoco se busca reducir la utilización de los quirófanos ni aumentar los tiempos de cambio entre intervenciones, que son efectos indeseables."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f0") }, {"long_answer": "La hoja circulante u hoja de ruta quirúrgica acompaña al paciente a lo largo de todo su paso por el Bloque Quirúrgico y su finalidad es proporcionar una visión integral del proceso, recogiendo la información relevante de cada fase: preparación, anestesia, intervención, recuperación y alta del bloque. Así se facilita la continuidad asistencial y la coordinación entre profesionales. No tiene como fin dar seguridad al personal médico, ni es por sí sola el instrumento de prevención de errores, ni sustituye a la historia clínica como registro de todos los datos clínicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f1") }, {"long_answer": "La Ley Orgánica 15/1999 de protección de datos de carácter personal regulaba el tratamiento de los datos personales y protegía especialmente los relativos a la salud del paciente, considerados datos especialmente protegidos, que exigen garantías reforzadas de confidencialidad y seguridad. Hoy esta materia se rige por el Reglamento europeo de protección de datos y la Ley Orgánica 3/2018. No regula la gestión económico-administrativa sanitaria ni define las responsabilidades de los centros de salud, y los derechos y obligaciones de los pacientes en documentación clínica corresponden a la Ley 41/2002."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977305") }, {"long_answer": "En la zona de personal del Bloque Quirúrgico, la secretaría se encarga de controlar el trabajo administrativo: gestión de la programación, documentación, comunicaciones y registros de actividad. Esto permite que los profesionales sanitarios se dediquen a la asistencia. Las sesiones clínicas se realizan en la sala de reuniones, la atención a los pacientes corresponde a otras zonas del bloque y el almacenamiento de lencería se hace en los almacenes u oficios destinados a ello, no en la secretaría."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977307") }, {"option_4": "Todas las anteriores", "answer": 4, "long_answer": "Los estándares del Bloque Quirúrgico indican que las instalaciones eléctricas deben garantizar el alumbrado normal, el alumbrado de emergencia, el suministro eléctrico a los equipos y la seguridad de las personas frente a riesgos eléctricos, como los contactos indirectos o las microdescargas en pacientes con dispositivos intracardiacos. Como las tres primeras opciones son funciones que deben asegurarse, la respuesta correcta es la que las incluye a todas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977309") }, {"long_answer": "La sección HE3 del Código Técnico de la Edificación regula la eficiencia energética de las instalaciones de iluminación mediante el valor de eficiencia energética de la instalación (VEEI), que relaciona la potencia instalada con la superficie iluminada y el nivel de iluminancia media obtenido. Se expresa en W/m² por cada 100 lux. El nivel de iluminación, el índice de deslumbramiento y el rendimiento de color son parámetros de calidad lumínica, pero no miden la eficiencia energética de la instalación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97730e") }, {"long_answer": "El SAI estático es un sistema electrónico que almacena la energía en baterías y, mediante rectificador e inversor, la entrega sin interrupción cuando falla la red. Es el más utilizado para proteger los equipos críticos del quirófano. El SAI dinámico, en cambio, almacena la energía en forma cinética mediante un volante de inercia. Centralizado o centralizado redundante se refieren a cómo se organiza la instalación, no al modo de almacenar la energía, por lo que no responden a la pregunta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977313") }, {"long_answer": "Para los equipos cuya interrupción de servicio puede poner en peligro a pacientes o personal, los estándares y el reglamento electrotécnico exigen dos condiciones a la vez: limitar la corriente de fuga, para evitar descargas eléctricas, y evitar las interrupciones de suministro, de modo que un primer defecto de aislamiento no corte la alimentación. Ambas se consiguen con el sistema IT mediante transformador de aislamiento y vigilador de aislamiento. Por eso la respuesta es la que incluye las dos opciones; elegir solo una o ninguna sería incompleto o incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977314") }, {"long_answer": "Los equipos que no deben protegerse con diferenciales, ni en el primario ni en el secundario del transformador, se alimentan mediante un sistema de neutro aislado o sistema IT. Con un transformador de aislamiento y un vigilador de aislamiento, un primer defecto no provoca el disparo ni corta el suministro, sino que se señaliza para corregirlo, manteniendo así la continuidad en equipos vitales. Neutro flotante o tierra aislada no son la denominación normalizada del sistema, y la puesta a tierra convencional sí requiere protección diferencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97731b") }, {"long_answer": "La norma UNE 100713 sobre instalaciones de acondicionamiento de aire en hospitales establece para los quirófanos un caudal mínimo de aire exterior de 1200 m³/h para diluir los contaminantes, como gases anestésicos y partículas. Este aporte se combina con la filtración en varias etapas y la sobrepresión respecto a las zonas adyacentes. Los caudales de 500 y 1000 m³/h son insuficientes según la norma, y 1500 m³/h no es la cifra que recoge como mínimo recomendado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977324") }, {"long_answer": "Los estándares del Bloque Quirúrgico recomiendan para el difusor de flujo laminar una velocidad del aire a la salida de 0,15 m/s. Un flujo unidireccional suave arrastra las partículas fuera de la zona del campo quirúrgico sin generar turbulencias que las resuspendan, y resulta confortable para el equipo. Velocidades inferiores no garantizan el barrido de contaminantes y velocidades superiores favorecen las turbulencias, las corrientes molestas y la pérdida de calor del paciente, por lo que no son las recomendadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977327") }, {"long_answer": "Se recomienda instalar una toma para medir la presión en el conducto de impulsión del aire a la sala, para comprobar que el caudal y la presión aportados son los adecuados y que se mantiene la sobrepresión del quirófano respecto a las zonas adyacentes. Medir en la entrada de aire del climatizador o en el filtro absoluto informa del estado del equipo o de la colmatación del filtro, pero no de las condiciones de impulsión, y la difusión de aire de la sala no es el punto indicado para la toma de presión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97732a") }, {"long_answer": "Para conseguir la sobrepresión del quirófano se recomienda que el caudal de retorno o extracción sea aproximadamente un 15% inferior al de impulsión. El exceso de aire impulsado sale por las rendijas y puertas hacia las zonas menos limpias, impidiendo que entre aire contaminado. Si el retorno fuera igual a la impulsión no habría sobrepresión, y si fuera mayor la sala quedaría en depresión, propia de salas de aislamiento de infecciones por vía aérea. Instalar un filtro G4 es una medida de filtración y no genera sobrepresión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97732b") }, {"long_answer": "Los estándares recomiendan mantener una sobrepresión de al menos 5 Pa entre el quirófano y el pasillo limpio, de manera que el aire fluya siempre desde la zona más limpia a la menos limpia y no al revés. Este gradiente se consigue regulando los caudales de impulsión y retorno y debe comprobarse periódicamente. Los valores de 10, 15 y 20 Pa no son el mínimo que establece la recomendación; diferencias excesivas además dificultan la apertura de puertas y generan corrientes molestas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97732c") }, {"long_answer": "A las instalaciones mecánicas del Bloque Quirúrgico les son de aplicación el Real Decreto 314/2006, que aprueba el Código Técnico de la Edificación, y el Real Decreto 1942/1993, que aprueba el Reglamento de instalaciones de protección contra incendios. La norma UNE-EN ISO 7396-1 se refiere específicamente a los sistemas de canalización de gases medicinales y el Real Decreto 393/2007 a la norma básica de autoprotección, por lo que las combinaciones que los incluyen no corresponden a lo que señala el documento para las instalaciones mecánicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97732d") }, {"option_1": "Únicamente oxígeno", "option_3": "Helio y argón", "option_4": "Monóxido de carbono e hidrógeno", "long_answer": "Las instalaciones de gases medicinales del Bloque Quirúrgico incluyen el oxígeno y el aire comprimido medicinal, junto con otros como el protóxido de nitrógeno y la red de vacío. El oxígeno y el aire medicinal son imprescindibles para la ventilación y la anestesia de los pacientes. Las demás opciones no son correctas: limitarse solo al oxígeno es insuficiente, y el helio, el argón, el monóxido de carbono o el hidrógeno no forman parte de la red de gases medicinales de un quirófano."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977333") }, {"long_answer": "Durante la intervención, el equipo quirúrgico que trabaja en el campo estéril debe llevar ropa de quirófano estéril, es decir, bata y guantes estériles, además de gorro y mascarilla. Esta barrera evita que los microorganismos de la piel y la ropa del personal contaminen el campo y la herida, y es una medida básica de prevención de la infección de localización quirúrgica. La ropa no estéril solo es válida para quienes no participan directamente en el campo, y la ropa casual o deportiva no está permitida en el bloque."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977334") }, {"option_2": "Ducharse con jabón el día previo o el mismo día de la cirugía", "option_3": "Usar cortadora eléctrica si es necesario eliminar el vello", "long_answer": "Las guías de prevención de la infección de localización quirúrgica desaconsejan utilizar de forma rutinaria la descontaminación nasal con antimicrobianos tópicos, como la mupirocina, para eliminar Staphylococcus aureus, porque favorece la aparición de resistencias; se reserva para casos seleccionados. En cambio, sí se recomienda que el paciente se duche con jabón el día previo o el mismo día de la cirugía, que si hay que eliminar el vello se use cortadora eléctrica, y que se administre profilaxis antibiótica antes de la cirugía contaminada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977338") }, {"long_answer": "Cuando se sospecha una infección de la herida quirúrgica, o una celulitis alrededor de ella, se recomienda administrar un antibiótico que cubra los microorganismos causales más probables, teniendo en cuenta el tipo de cirugía, la flora local y los patrones de resistencia, y ajustarlo después según el cultivo. No intervenir y esperar a que cure sola puede permitir que la infección progrese. Los enemas no tienen relación con el tratamiento de la herida, y las soluciones cloradas no están recomendadas para el desbridamiento de heridas quirúrgicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97733e") }, {"long_answer": "En la zona restringida o estéril del Bloque Quirúrgico, el personal debe llevar traje quirúrgico de quirófano, gorro que cubra todo el pelo, calzado exclusivo del área quirúrgica y mascarilla, que cubra totalmente boca y nariz. Este conjunto limita la dispersión de partículas y microorganismos en la zona de mayor exigencia de asepsia. Las demás opciones son incompletas: les falta el gorro, la mascarilla o el calzado exclusivo, o sustituyen el traje por una bata y cubrecalzado desechables, que no es la vestimenta recomendada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97733f") }, {"long_answer": "Los estándares del Bloque Quirúrgico, al definir la vestimenta para la zona restringida o estéril, recomiendan que las personas que acceden a ella, incluidos los pacientes mientras no se inicia el manejo de la vía aérea, lleven mascarilla que cubra totalmente la boca y la nariz. El objetivo es reducir la emisión de gotas y microorganismos en el entorno quirúrgico. Por ello no son correctas las opciones que plantean no usarla, usarla solo en pacientes inmunodeprimidos o con enfermedades transmisibles, o dejarla a criterio de cada paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977343") }, {"long_answer": "El documento del proyecto ITU-Zero señala que el riesgo de infección urinaria asociada a sonda aumenta aproximadamente un 5% por cada día que se mantiene el sondaje vesical. Por eso la duración del sondaje es el principal factor de riesgo modificable y el proyecto insiste en revisar a diario la indicación y retirar la sonda en cuanto deje de ser necesaria. Los porcentajes del 2%, 3% y 4% no corresponden al dato que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977347") }, {"long_answer": "Según el documento del proyecto ITU-Zero, alrededor del 50% de los pacientes sondados presentan bacteriuria al décimo día del sondaje uretral, y la proporción se acerca al 100% en sondajes de un mes. Esto se debe a la formación de biopelícula en la superficie de la sonda y al ascenso de microorganismos por su luz o por el espacio periuretral. Las cifras del 30%, 40% y 60% no corresponden a lo que indica el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97734b") }, {"question": "¿Cuál de los siguientes es un criterio clínico para el diagnóstico de infección urinaria?", "option_2": "Exantema cutáneo generalizado", "option_3": "Diarrea acuosa", "long_answer": "La fiebre superior a 38 ºC es uno de los criterios clínicos para el diagnóstico de infección urinaria en el paciente sondado, junto con la tensión suprapúbica o la urgencia urinaria, siempre acompañados de confirmación microbiológica con urocultivo positivo. El exantema cutáneo generalizado, la diarrea acuosa y la tos con dolor de cabeza no son manifestaciones de infección urinaria; orientan a otros focos o procesos, por lo que no se incluyen entre los criterios diagnósticos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977350") }, {"long_answer": "Según el último informe del registro ENVIN-HELICS recogido en el documento del proyecto ITU-Zero, la tasa de infección urinaria relacionada con sonda uretral en las UCI fue de 3,75 episodios por 1000 días de sonda uretral. Este indicador relaciona los episodios con los días reales de exposición al dispositivo, lo que permite comparar unidades y seguir la evolución en el tiempo, y es la base sobre la que se fija el objetivo de reducción del proyecto. Las cifras de 5,21, 2,88 y 4,67 no corresponden al dato publicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977351") }, {"long_answer": "Escherichia coli es el bacilo gramnegativo identificado con mayor frecuencia en las infecciones urinarias relacionadas con sonda uretral según el registro ENVIN, seguido de otros como Klebsiella pneumoniae, Pseudomonas aeruginosa o Proteus. Su origen es la flora intestinal del propio paciente, que coloniza la zona perineal y asciende por la sonda. Pseudomonas aeruginosa y Klebsiella pneumoniae son frecuentes pero menos que E. coli, y Acinetobacter baumannii es un aislamiento mucho menos habitual en este tipo de infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977354") }, {"long_answer": "Según los datos del registro ENVIN recogidos en el documento del proyecto ITU-Zero, Candida albicans es el microorganismo que ha disminuido su presencia en las infecciones urinarias relacionadas con sonda uretral entre 2001 y 2017, mientras que han ganado peso otros patógenos. Escherichia coli se ha mantenido como el bacilo gramnegativo más frecuente, y la evolución de Candida glabrata y Klebsiella pneumoniae no muestra esa tendencia descendente en el periodo analizado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97735a") }, {"option_4": "Cambio rutinario de la sonda cada 7 días", "long_answer": "El proyecto ITU-Zero recomienda aplicar protocolos institucionales para la colocación del catéter urinario, que incluyan indicaciones adecuadas, inserción aséptica con material estéril por personal entrenado y mantenimiento con sistema cerrado, junto con la retirada en cuanto deje de ser necesario. El sondaje no debe indicarse sistemáticamente en todos los pacientes críticos, los lavados vesicales rutinarios aumentan el riesgo de infección porque abren el sistema, y el cambio rutinario de la sonda a intervalos fijos no está recomendado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97735b") }, {"option_1": "Para obtener muestras de orina en pacientes que orinan espontáneamente", "option_2": "En pacientes con incontinencia urinaria sin lesiones cutáneas, por comodidad", "option_4": "En pacientes ambulatorios continentes como medida preventiva", "long_answer": "Entre las indicaciones de sondaje uretral que recoge el proyecto ITU-Zero está la úlcera por presión de categoría III o IV en la zona sacrococcígea en pacientes incontinentes, para evitar que la orina contamine la lesión y dificulte su curación. Otras indicaciones son la retención aguda u obstrucción urinaria, la necesidad de medir con precisión la diuresis en el paciente crítico o determinadas cirugías. No se debe sondar para obtener muestras en pacientes que orinan espontáneamente, como prevención en pacientes continentes ni por comodidad en la incontinencia sin lesiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977365") }, {"option_2": "Sustituir el uso de guantes en la manipulación de la sonda", "option_3": "Proteger al paciente, al profesional y al entorno sanitario de microorganismos nocivos", "long_answer": "Según el protocolo de higiene de manos del proyecto ITU-Zero, basado en la estrategia de la OMS, la finalidad de la higiene de manos es proteger al paciente, al profesional y al entorno sanitario de los microorganismos nocivos, interrumpiendo la transmisión a través de las manos. En el paciente sondado previene la colonización de la sonda y del sistema de drenaje. No se dirige específicamente a las enfermedades respiratorias, no sustituye al uso de guantes y no tiene relación con la esterilización del instrumental, que requiere otros procesos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977368") }, {"long_answer": "El protocolo de higiene de manos del proyecto ITU-Zero establece como método prioritario la fricción con productos de base alcohólica, por ser más rápida, más eficaz para eliminar la flora transitoria, mejor tolerada por la piel y accesible en el punto de atención. El lavado con agua y jabón se reserva para cuando las manos están visiblemente sucias o contaminadas con materia orgánica. El uso de guantes no sustituye la higiene de manos, y las soluciones yodadas no son el método indicado para la higiene de manos habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977370") }, {"long_answer": "El objetivo principal del proyecto Infección Quirúrgica Zero es reducir en un 15% la tasa de infección de localización quirúrgica en los hospitales participantes, mediante la aplicación de un paquete de medidas preventivas: profilaxis antibiótica adecuada, antisepsia de la piel con clorhexidina alcohólica, eliminación correcta del vello, mantenimiento de la normotermia y control de la glucemia. Los porcentajes del 5%, 10% y 20% no corresponden al objetivo fijado por el proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977373") }, {"long_answer": "La profilaxis antibiótica adecuada, con el antibiótico indicado, administrado en los 60 minutos previos a la incisión y redosificado según su vida media y la duración de la cirugía, es una medida con nivel de evidencia alto en la prevención de la infección de localización quirúrgica. Su eficacia está demostrada por numerosos ensayos clínicos aleatorizados y metaanálisis en distintos tipos de cirugía, por lo que forma parte del paquete de Infección Quirúrgica Zero. Los niveles moderado, bajo y muy bajo no reflejan la solidez de esta evidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977377") }, {"long_answer": "En la tabla de antimicrobianos para profilaxis del protocolo Infección Quirúrgica Zero, la vancomicina tiene un intervalo de redosificación de 12 horas, porque su vida media es larga. En la práctica, en la mayoría de las intervenciones no es necesario repetir la dosis. El intervalo de 3 a 4 horas corresponde a antibióticos de vida media corta como la cefazolina o la cefoxitina, y los de 6 y 8 horas no corresponden a la vancomicina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977379") }, {"long_answer": "La clorhexidina alcohólica al 2% combina la acción bactericida instantánea del alcohol con la acción más permanente de la clorhexidina, que se une a la queratina de la piel y mantiene un efecto residual en las capas profundas durante horas. Esta suma de rapidez y persistencia explica su superioridad frente a otros antisépticos en la prevención de la infección quirúrgica. Las demás opciones no explican su mecanismo: su efecto no se basa en una acción antiviral, fungicida del alcohol ni antiinflamatoria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97737c") }, {"long_answer": "El protocolo Infección Quirúrgica Zero explica que el rasurado con cuchilla produce microerosiones en la piel próxima a la incisión, que se colonizan por bacterias y aumentan el riesgo de infección. Por eso la eliminación correcta del vello consiste en no eliminarlo si no es necesario y, si hay que hacerlo, usar cortadora eléctrica, que no lesiona la piel. Los productos depilatorios no tienen acción antibacteriana ni antifúngica, y eliminar el vello no estimula el sistema inmunitario ni incrementa la circulación sanguínea en la zona de la incisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97737f") }, {"question": "¿Cuál es el principal mecanismo de producción de hipotermia en la primera hora tras la inducción anestésica?", "option_1": "Redistribución del calor desde el compartimento central (core) hacia la periferia", "option_2": "Pérdida de calor por convección", "option_3": "Pérdida de calor por radiación", "option_4": "Pérdida de calor por evaporación", "long_answer": "En la primera hora tras la inducción anestésica, el principal mecanismo de hipotermia es la redistribución del calor desde el compartimento central (core) hacia la periferia, porque los anestésicos producen vasodilatación y anulan la vasoconstricción termorreguladora. Esto puede hacer descender la temperatura central entre 1 y 1,5 ºC. Después, el paciente sigue perdiendo calor por radiación, que es la vía más importante, y por convección, conducción y evaporación, pero estas vías no explican el descenso brusco inicial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977382") }, {"question": "¿Por qué el mantenimiento de la normoglucemia perioperatoria contribuye a prevenir la infección quirúrgica?", "option_1": "Porque la hiperglucemia altera la función fagocítica de los neutrófilos y favorece la infección", "option_2": "Porque la hiperglucemia aumenta la actividad de los linfocitos T y B", "option_3": "Porque la glucosa elevada tiene efecto bactericida directo", "option_4": "Porque la normoglucemia produce vasoconstricción y reduce el sangrado", "long_answer": "El mantenimiento de la normoglucemia previene la infección quirúrgica porque la hiperglucemia altera la función de los neutrófilos, reduciendo su quimiotaxis, su capacidad fagocítica y su actividad bactericida, y empeora la respuesta inflamatoria y la cicatrización. Por eso el protocolo Infección Quirúrgica Zero recomienda mantener la glucemia por debajo de 180 mg/dl. La hiperglucemia no aumenta la actividad de los linfocitos T y B, la glucosa elevada no tiene efecto bactericida, y la normoglucemia no actúa produciendo vasoconstricción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977390") }, {"long_answer": "Para el pincelado de la piel antes de la intervención se recomienda la solución alcohólica de clorhexidina al 2%, que ha demostrado mayor eficacia que la povidona yodada en la prevención de la infección quirúrgica gracias a su acción rápida y su efecto residual. La clorhexidina acuosa no tiene la acción inmediata del alcohol, y las soluciones de yodo o povidona yodada, alcohólicas o no, son alternativas para cuando la clorhexidina está contraindicada, pero no la primera elección según el protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977398") }, {"long_answer": "Para la medición basal de la cultura de seguridad, el Programa de Cirugía Segura recomienda la versión española del Hospital Survey on Patient Safety Culture, cuestionario validado y adaptado en España que explora dimensiones como la comunicación, el trabajo en equipo, la notificación de incidentes o el apoyo de la dirección. Las encuestas de satisfacción del paciente miden otros aspectos, las entrevistas individuales no permiten una medición estandarizada y comparable, y no se propone un cuestionario genérico distinto del validado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a6") }, {"long_answer": "Según la revisión de Borchard y colaboradores, citada en el Programa de Cirugía Segura, la tasa de cumplimiento del listado de verificación quirúrgica en la fase de pausa quirúrgica o time-out fue del 91%, más alta que en las fases de entrada y de salida del quirófano. El time-out, inmediatamente antes de la incisión, es el momento en que se confirma con todo el equipo la identidad del paciente, el procedimiento y el sitio. Las cifras del 60%, 75% y 100% no corresponden a ese estudio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b2") }, {"option_4": "Acortar la duración de la intervención quirúrgica", "long_answer": "El documento recomienda evitar ayunos prolongados antes de la cirugía porque mejora el bienestar del paciente, reduciendo la sed, el hambre, la ansiedad y el malestar, y disminuye la respuesta catabólica. Las guías actuales permiten líquidos claros hasta dos horas antes de la anestesia y sólidos hasta seis horas antes. Prevenir la broncoaspiración es la razón para mantener un ayuno mínimo, no para acortarlo, y evitar ayunos prolongados no reduce las infecciones postoperatorias ni acorta la duración de la intervención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b4") }, {"long_answer": "En el pasado se recomendaban ayunos prolongados, a menudo desde la medianoche anterior, para prevenir la broncoaspiración del contenido gástrico tras la inducción anestésica, cuando se pierden los reflejos protectores de la vía aérea. Hoy se sabe que los líquidos claros se vacían del estómago en pocas horas y las guías permiten ayunos más cortos. El ayuno prolongado no evita el catabolismo ni la hiperglucemia, sino que los favorece; no responde a las guías actuales y no previene la deshidratación, sino que la favorece."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b6") }, {"option_1": "Eliminación del vello con maquinilla eléctrica (cortadora) el mismo día de la cirugía, solo si es necesario", "option_4": "Rasurado con cuchilla en el quirófano tras el pincelado antiséptico", "long_answer": "Para disminuir la infección asociada a la eliminación del vello, se recomienda no eliminarlo salvo que interfiera con la intervención y, si es necesario, hacerlo con maquinilla eléctrica (cortadora) el mismo día de la cirugía, porque no produce microerosiones en la piel. El rasurado con cuchilla, ya sea el día antes o el mismo día, provoca pequeñas lesiones que se colonizan y aumentan el riesgo de infección, especialmente cuanto más tiempo pasa hasta la incisión. Rasurar con cuchilla en el quirófano tras el pincelado, además, rompe la antisepsia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b9") }, {"long_answer": "Según el documento, los campos quirúrgicos autoadhesivos de plástico aumentan el riesgo de infección de herida quirúrgica, por lo que no se recomienda su uso rutinario. La humedad que se acumula bajo el plástico favorece la proliferación bacteriana en la piel próxima a la incisión, y al retirarlo pueden arrastrarse microorganismos hacia la herida. Por ello no es correcto afirmar que disminuyen la infección o que no presentan diferencias, y la evidencia disponible sí es suficiente para desaconsejar su uso sistemático."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773bb") }, {"long_answer": "El documento recoge que el lavado intracavitario de la herida durante la operación disminuye la incidencia de infección de herida quirúrgica, porque arrastra mecánicamente restos de tejido, coágulos y bacterias del lecho quirúrgico antes del cierre. Por ello no son correctas las opciones que afirman que la aumenta o que no tiene efecto. Tampoco es correcto atribuir el beneficio exclusivamente al antiséptico empleado, ya que el efecto principal descrito es el arrastre mecánico de la contaminación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773bc") }, {"long_answer": "Entre las medidas preventivas estructurales y de comportamiento en el quirófano se recomienda minimizar los movimientos dentro de la sala y el número de personas presentes, porque cada persona y cada movimiento dispersan partículas y microorganismos que aumentan la contaminación del aire y el riesgo de infección. Las normas deben restringir, no facilitar, la entrada y salida de personas; las puertas y ventanillas deben permanecer cerradas para mantener la sobrepresión; y en el campo quirúrgico solo se usa material estéril."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773be") }, {"long_answer": "Según el documento, el uso de mascarillas por el personal de quirófano disminuye significativamente la contaminación del espacio quirúrgico, porque retiene las gotas y partículas emitidas al hablar, toser o respirar, que pueden transportar microorganismos de la vía respiratoria superior hacia el campo. No es correcto decir que la aumenta ni que no tiene efecto. Tampoco se plantea que el efecto dependa del tipo de mascarilla, ya que la recomendación general es que todo el personal la lleve cubriendo boca y nariz."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c1") }, {"option_2": "Sustituir la valoración forense por la valoración sanitaria", "option_3": "Promover la mediación entre la víctima y el agresor", "long_answer": "El Protocolo de actuación sanitaria frente a la violencia sexual incluye entre sus objetivos específicos garantizar una actuación coordinada con los médicos forenses, de modo que la exploración sanitaria y la recogida de pruebas se hagan en un solo acto cuando sea posible, evitando reconocimientos repetidos. Además busca reducir la victimización secundaria, no incrementarla. La mediación entre víctima y agresor está excluida en violencia sexual, y la valoración sanitaria no sustituye a la forense, sino que se coordina con ella."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c6") }, {"long_answer": "El Protocolo de Palermo define la trata de personas como la captación, el transporte, el traslado, la acogida o la recepción de personas, recurriendo a la amenaza, al uso de la fuerza u otras formas de coacción, al rapto, al fraude, al engaño o al abuso de poder o de una situación de vulnerabilidad, con fines de explotación. Por eso la opción correcta es el transporte de personas mediante coacción para su explotación. El consentimiento de la víctima no excluye la trata cuando se emplean esos medios, y la trata no se limita a la explotación sexual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c9") }, {"option_2": "Disminución del riesgo de enfermedades crónicas", "long_answer": "Los estudios recogidos en el protocolo describen entre las consecuencias para la salud de la violencia sexual los trastornos gastrointestinales, como el colon irritable o el dolor abdominal crónico, además de dolor pélvico, problemas ginecológicos, trastornos del sueño, ansiedad, depresión o estrés postraumático. Las demás opciones son incorrectas porque afirman lo contrario de lo observado: la violencia sexual no reduce los síntomas somáticos ni el riesgo de enfermedades crónicas, ni mejora el estado de salud general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d0") }, {"option_4": "Todas las anteriores", "answer": 4, "long_answer": "La Ley 33/2011, General de Salud Pública, establece que las actuaciones de salud pública deben realizarse en condiciones de igualdad, sin discriminación por razón de nacimiento, origen racial o étnico, sexo, religión, convicción u opinión, edad, discapacidad, orientación o identidad sexual, enfermedad o cualquier otra condición o circunstancia personal o social. Por tanto, ni la edad, ni la ocupación laboral, ni la etnia pueden ser motivo de discriminación, y la respuesta correcta es la que incluye a todas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d2") }, {"long_answer": "En el marco del protocolo, la vulnerabilidad se define como una condición social de riesgo, que no es intrínseca a la persona, sino derivada de factores sociales, económicos o de discriminación, que limita e invalida a las personas para satisfacer sus necesidades y ejercer sus derechos, y las expone a sufrir daños, como la violencia. Las demás opciones describen justamente lo contrario: un estado de bienestar, la inmunidad frente a las enfermedades o una situación de privilegio no corresponden al concepto de vulnerabilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d5") }, {"long_answer": "En el contexto de la violencia de género, el embarazo es una etapa de especial vulnerabilidad porque añade dificultades a la posibilidad de independizarse de la pareja: la dependencia económica, el cuidado futuro del hijo o la hija y el vínculo con el agresor hacen más difícil romper la relación. Además, la violencia suele iniciarse o agravarse en este periodo. Las demás opciones son incorrectas, porque el embarazo no hace más fácil abandonar al agresor, no disminuye la vulnerabilidad ni aporta más recursos de protección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d8") }, {"long_answer": "El embarazo se considera de alto riesgo en el contexto de la violencia de género porque las mujeres embarazadas pueden ser más vulnerables a la violencia, incluida la sexual, que con frecuencia se inicia o se intensifica en este periodo y repercute en la salud materna y fetal, con más riesgo de aborto, parto prematuro o bajo peso al nacer. Las demás opciones son incorrectas: el embarazo no aumenta la protección frente a la violencia ni reduce su probabilidad, y estar embarazada no hace que la mujer busque más ayuda."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b8") }, {"long_answer": "El objetivo último del Surgical Care Improvement Project, iniciativa estadounidense citada en los estándares del Bloque Quirúrgico, es mejorar la calidad de la asistencia quirúrgica reduciendo las complicaciones postoperatorias evitables, como la infección de localización quirúrgica, los eventos cardiovasculares o la enfermedad tromboembólica. Para ello promueve medidas basadas en la evidencia, como la profilaxis antibiótica adecuada o la tromboprofilaxis. No pretende reducir el número de cirugías, incentivar técnicas innovadoras ni aumentar los costes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772b9") }, {"long_answer": "Según un estudio publicado en el Journal of the American Medical Association y citado en los estándares del Bloque Quirúrgico, alrededor del 22% de las muertes de pacientes relacionadas con complicaciones postoperatorias podrían haberse prevenido. Este dato muestra la importancia de aplicar medidas de seguridad en el proceso quirúrgico, como el listado de verificación o la prevención de la infección y de la tromboembolia. Los porcentajes del 15%, 30% y 40% no corresponden al dato recogido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772bd") }, {"option_2": "Únicamente la firma del paciente, sin información sobre riesgos", "option_3": "La situación de la lista de espera quirúrgica del servicio", "option_4": "Los honorarios del anestesiólogo", "long_answer": "El consentimiento informado para la técnica anestésica debe incluir los riesgos generales del procedimiento y los riesgos específicos personalizados, es decir, los derivados de las circunstancias clínicas y personales de cada paciente, de forma que pueda decidir con conocimiento. Las demás opciones no son contenidos del consentimiento: una firma sin información sobre los riesgos no es válida, y la lista de espera del servicio o los honorarios del anestesiólogo no forman parte de la información clínica que hay que facilitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772be") }, {"question": "En la información escrita que se entrega al paciente quirúrgico, ¿qué apartado recoge las pautas para las primeras horas tras la intervención?", "long_answer": "Los estándares del Bloque Quirúrgico recomiendan entregar al paciente información por escrito organizada en varios apartados: instrucciones para el día anterior a la intervención, instrucciones para el postoperatorio inmediato, instrucciones tras el alta y datos de acceso a los recursos de atención continuada. Las pautas para las primeras horas tras la cirugía corresponden a las instrucciones para el postoperatorio inmediato. Las del día anterior se refieren a la preparación, las post-alta al periodo domiciliario posterior y los datos de atención continuada a cómo contactar con el centro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c1") }, {"long_answer": "La OMS recomienda que una única persona, el coordinador de la lista de comprobación, sea la responsable de verificar y confirmar en cada fase (entrada, pausa quirúrgica y salida) que el equipo ha completado sus tareas antes de continuar. Habitualmente esta función la asume la enfermera circulante, aunque puede ser cualquier profesional del equipo. Por eso no es correcto atribuirla de forma obligatoria al cirujano, al anestesista o al auxiliar de enfermería: lo que define la función es el rol de coordinador, no la categoría profesional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d9") }, {"option_2": "Unidad exclusivamente administrativa sin espacio físico propio", "option_3": "Espacio donde se agrupan los quirófanos y sus locales de apoyo, junto con la organización de profesionales asociada", "long_answer": "Los estándares del Ministerio describen el Bloque Quirúrgico como el espacio físico en el que se agrupan los quirófanos con sus locales de apoyo, junto con la organización de profesionales que realiza en él la actividad quirúrgica, y analizan sus distintas tipologías según el tipo de hospital y la actividad. Por eso la respuesta correcta une espacio y organización. No es solo un espacio para el personal sanitario, ni una unidad exclusivamente administrativa sin espacio propio, ni una sala de espera para pacientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e4") }, {"long_answer": "Según los estándares del Bloque Quirúrgico, un objetivo razonable de utilización de los quirófanos en actividad programada es de unas 40 horas por quirófano y semana, lo que supone aprovechar de forma adecuada la jornada de mañana de lunes a viernes. Una utilización de 20 o 30 horas implicaría infrautilizar un recurso muy costoso, y 50 horas por semana requeriría extender la actividad programada más allá de la jornada habitual, por lo que no se propone como objetivo estándar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e5") }, {"long_answer": "Los estándares del Bloque Quirúrgico señalan que el modo más rentable de asignar el tiempo de quirófano es asignarlo a un servicio quirúrgico de una especialidad concreta, que se responsabiliza de programarlo y de aprovecharlo. Así se facilita la planificación, se reducen tiempos muertos y se mejora la eficiencia. Dejar los quirófanos abiertos a todos los cirujanos dificulta la previsión, y asignarlos por orden de llegada de los pacientes o por orden alfabético de los cirujanos no responde a ningún criterio de gestión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ea") }, {"long_answer": "Para evitar demoras en la cirugía urgente se recomienda implicar a anestesiólogos, cirujanos y otras especialidades médicas en la evaluación preoperatoria, de forma que el paciente esté optimizado cuanto antes y se decida con rapidez el momento de la intervención según su grado de urgencia. Trasladar todas las urgencias a horario nocturno o al día siguiente retrasa la atención y aumenta los riesgos, y cancelar sistemáticamente las cirugías menos urgentes no es una medida de organización recomendada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ef") }, {"long_answer": "La hoja circulante u hoja de ruta quirúrgica es el documento que caracteriza al Bloque Quirúrgico, porque acompaña al paciente durante todo su paso por él y recoge la información de cada fase: identificación, verificaciones, anestesia, intervención, recuento, recuperación y alta del bloque. La historia clínica es un documento común a toda la asistencia, el informe de alta corresponde al final del episodio y la receta médica es un documento de prescripción, por lo que ninguno de ellos es específico del bloque."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f3") }, {"long_answer": "Todo paciente tiene derecho a la confidencialidad sobre su estado de salud y sobre los datos de su historia clínica, de modo que nadie pueda acceder a ellos sin su autorización salvo en los casos previstos por la ley, según la Ley 41/2002 de autonomía del paciente y la normativa de protección de datos. No puede exigir la eliminación de sus datos clínicos, que deben conservarse durante los plazos legales; no tiene derecho a acceder a datos de otros pacientes, y la cesión de datos a terceros requiere consentimiento o habilitación legal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f5") }, {"long_answer": "Para conseguir un buen rendimiento de los quirófanos se recomienda registrar los retrasos respecto a la programación prevista, junto con las cancelaciones y los desajustes entre la duración prevista y la real, y analizarlos para corregir sus causas. Las demás opciones van en contra de una buena gestión: no se trata de hacer un número ilimitado de intervenciones, sino de ajustar la programación a la capacidad real; los desajustes sí deben registrarse, y es necesario fijar objetivos para el personal implicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f6") }, {"long_answer": "La utilización porcentual de los quirófanos por una especialidad se calcula dividiendo el tiempo de quirófano efectivamente utilizado por esa especialidad entre las horas de quirófano que tiene asignadas, y multiplicando por 100. Este indicador muestra en qué medida la especialidad aprovecha el tiempo que se le ha concedido. Las demás fórmulas no son correctas: restar o sumar tiempos de cambio sin relacionarlos con las horas asignadas no da un porcentaje de utilización, y dividir horas disponibles entre horas asignadas no mide el uso real."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f7") }, {"long_answer": "Para lograr un buen rendimiento de los quirófanos es importante registrar los desajustes entre la duración prevista y la real de las intervenciones, porque permiten mejorar la estimación de tiempos, ajustar la programación y reducir retrasos, horas extra y cancelaciones. Los objetivos del personal se fijan, no se registran como indicador de rendimiento; una tasa de cancelaciones alta es un problema que hay que evitar, y la alta utilización es un resultado deseable, no el dato que hay que recoger para mejorar la programación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f8") }, {"option_4": "Todas las anteriores", "answer": 4, "long_answer": "Según los estándares del Bloque Quirúrgico, el programa funcional de un BQ general debe contemplar el análisis de su capacidad de producción en distintos escenarios, el estudio de las necesidades de equipamiento y el desarrollo de los requerimientos funcionales de cada zona de la unidad, entre otros aspectos de organización y dimensionado. Como las tres primeras opciones forman parte del contenido del programa funcional, la respuesta correcta es la que las incluye a todas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f9") }, {"long_answer": "Los estándares del Bloque Quirúrgico señalan varias innovaciones tecnológicas que han transformado la actividad quirúrgica en los últimos años: la introducción de robots en los quirófanos, la docencia realizada fuera de las salas mediante sistemas de imagen y transmisión, y la aplicación de sistemas de información y comunicación para gestionar el proceso y la historia clínica. Como las tres son innovaciones con impacto en la organización y el diseño del bloque, la respuesta correcta es todas las anteriores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772fa") }, {"long_answer": "Los cambios demográficos, sobre todo el envejecimiento de la población, deben tenerse en cuenta en la planificación del Bloque Quirúrgico porque modifican la frecuentación quirúrgica, el tipo de procesos y la complejidad de los pacientes, lo que obliga a ajustar el dimensionado de los recursos, como quirófanos, camas de recuperación y personal, según la edad de la población atendida. La incorporación de robots y la ventilación no dependen de la demografía, y el envejecimiento tiende a aumentar, no a reducir, la frecuentación quirúrgica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977301") }, {"long_answer": "En la zona postquirúrgica, el oficio sucio es el local destinado a almacenar de forma transitoria los residuos generados en la zona y el material usado o contaminado hasta su retirada, separado de los circuitos limpios. La ropa limpia y el material estéril se guardan en almacenes o en el oficio limpio, para evitar su contaminación, y los equipos portátiles disponen de su propio espacio de almacenamiento, por lo que ninguno de ellos corresponde al oficio sucio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977303") }, {"long_answer": "En la zona postquirúrgica, el oficio de limpieza es el local donde se guardan los equipos y productos de limpieza que utiliza el personal encargado de higienizar el área. Separarlo de otros locales evita mezclar circuitos y facilita la organización del trabajo. Los residuos generados se almacenan en el oficio sucio, mientras que la ropa limpia y el material estéril tienen sus propios almacenes o el oficio limpio, por lo que las demás opciones no corresponden a este local."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977308") }, {"long_answer": "La sección SU4 del Documento Básico de Seguridad de Utilización del Código Técnico de la Edificación tiene como objetivo la seguridad frente al riesgo causado por una iluminación inadecuada, estableciendo niveles mínimos de alumbrado normal y de emergencia en zonas de circulación y evacuación. La eficiencia energética de la iluminación corresponde a la sección HE3; las reglas para instalaciones y emplazamientos especiales se recogen en el Reglamento electrotécnico de baja tensión, y la iluminación de los lugares de trabajo se regula en la normativa de prevención de riesgos laborales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97730b") }, {"long_answer": "El alumbrado de evacuación es la parte del alumbrado de emergencia que permite reconocer y utilizar las rutas de evacuación cuando los locales están o pueden estar ocupados. El alumbrado ambiente o antipánico evita el pánico y permite llegar hasta las rutas de evacuación, el de zonas de alto riesgo garantiza la seguridad de quienes realizan actividades peligrosas, y el de reemplazamiento permite continuar las actividades normales, como una intervención quirúrgica, por lo que ninguno de ellos tiene esta función específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97730d") }, {"long_answer": "El Reglamento electrotécnico de baja tensión, en su instrucción para locales de pública concurrencia, exige que el suministro especial complementario de quirófanos y salas de intervención entre en funcionamiento en un tiempo máximo de 0,5 segundos, de modo que los equipos y el alumbrado esenciales apenas noten el fallo de red. Un tiempo de 1, 2 o 3 segundos supera el máximo permitido y podría comprometer equipos de soporte vital o la iluminación del campo quirúrgico durante la intervención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977317") }, {"long_answer": "El vigilador de aislamiento es el dispositivo que, en las instalaciones con sistema IT del quirófano, controla de forma continua la resistencia de aislamiento y debe señalizar mediante alarma óptica y acústica en la propia sala la aparición de un defecto de aislamiento, para corregirlo sin interrumpir el suministro. No tiene como función indicar la temperatura ni limitar la corriente de fuga, que se consigue con el transformador de aislamiento, y su función principal no es memorizar defectos, sino avisar de ellos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977318") }, {"question": "¿Cuál de las siguientes NO es una recomendación para el vigilador de aislamiento?", "answer": 2, "long_answer": "La monitorización de la temperatura no es una función ni una recomendación del vigilador de aislamiento, cuya misión es controlar la resistencia de aislamiento del sistema IT del quirófano. Las recomendaciones para estos equipos incluyen poder localizar los fallos de forma individual por circuito, tener una resistencia interna elevada para no alterar la instalación y dar una alarma si se interrumpe la conexión a tierra, ya que en ese caso el vigilador dejaría de medir correctamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97731e") }, {"long_answer": "La recomendación principal para la red de conductos de climatización del Bloque Quirúrgico es mantenerla lo más corta posible, porque así se reducen las pérdidas de carga, la superficie donde se puede acumular suciedad y la dificultad de limpieza y mantenimiento. Una red larga es justo lo contrario de lo recomendado. Los conductos de fibra con aislamiento interior no se recomiendan, porque pueden desprender partículas y retener suciedad, y la forma circular o rectangular no es el aspecto principal que se destaca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97731f") }, {"long_answer": "Los estándares del Bloque Quirúrgico recomiendan que los conductos de aire tengan un coeficiente de rugosidad bajo, del orden de 0,3 μm, para que las superficies interiores sean lisas, dificulten la acumulación de polvo y microorganismos y faciliten la limpieza. Este valor es compatible con los materiales metálicos habituales. Las cifras de 0,1, 0,5 y 0,7 μm no son las que recoge la recomendación del documento para los conductos de la instalación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977325") }, {"long_answer": "Para alcanzar el grado de filtración exigido en los quirófanos, la norma UNE 100713 establece tres niveles de filtración: un prefiltro a la entrada del climatizador, un segundo filtro de alta eficacia a la salida y un tercer filtro absoluto HEPA en la impulsión a la sala, lo más cerca posible de los difusores. Con uno o dos niveles no se consigue la calidad de aire que requieren las salas de cirugía, y no se exige un cuarto nivel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977337") }, {"question": "¿Qué se debe evitar utilizar durante la intervención como método para reducir el riesgo de infección de localización quirúrgica?", "option_2": "Cubrir la incisión con un apósito adecuado al final de la intervención", "long_answer": "Durante la intervención se debe evitar la irrigación de la herida y el lavado intracavitario como método para reducir el riesgo de infección de localización quirúrgica, porque las guías basadas en la evidencia no han demostrado beneficio de su uso sistemático con este fin. En cambio, sí se recomienda cubrir la incisión con un apósito adecuado al final de la intervención, procurar el cierre por primera intención cuando sea posible y tratar adecuadamente la infección si aparece, por lo que esas opciones no son prácticas que deban evitarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977340") }, {"long_answer": "Según el documento, las infecciones relacionadas con la asistencia sanitaria son una de las principales causas de morbilidad y mortalidad en los pacientes hospitalizados, y entre ellas destacan la infección urinaria asociada a sonda, la neumonía asociada a ventilación, la bacteriemia y la infección quirúrgica. Además prolongan la estancia y aumentan los costes. Las infecciones respiratorias, gastrointestinales o de la piel son localizaciones concretas, pero el documento se refiere al conjunto de las infecciones asociadas a la asistencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977344") }, {"long_answer": "Según el documento del proyecto ITU-Zero, alrededor de un 2% de los pacientes con bacteriuria asociada a sondaje uretral desarrollan bacteriemia, una complicación grave que eleva la mortalidad y prolonga la estancia hospitalaria. Aunque el porcentaje parece bajo, la gran cantidad de pacientes sondados hace que el número absoluto de bacteriemias de origen urinario sea relevante. Los valores del 1%, 3% y 4% no corresponden al dato que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977346") }, {"long_answer": "Según el documento del proyecto ITU-Zero, entre el 60% y el 80% de los pacientes ingresados en las UCI de adultos son portadores de un catéter uretral durante su estancia, sobre todo para controlar la diuresis. Esta elevada utilización explica que la infección urinaria relacionada con sonda sea una de las infecciones más frecuentes en el paciente crítico y justifica la importancia de revisar diariamente la indicación. Los demás intervalos no corresponden al dato del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977349") }, {"long_answer": "Las guías oficiales recogidas en el documento coinciden en que la principal medida para prevenir la infección urinaria relacionada con sonda uretral es el uso apropiado de la sonda: sondar solo cuando está indicado, insertarla de forma aséptica, mantener el sistema cerrado y retirarla lo antes posible. El uso de mascarilla, guantes de látex o batas estériles no es la recomendación clave en este caso; la inserción requiere guantes estériles, no simplemente de látex, y las batas estériles no son necesarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97734d") }, {"long_answer": "Según el informe ENVIN-HELICS de 2017 recogido en el documento del proyecto ITU-Zero, el 75,71% de los pacientes incluidos fueron portadores de sonda uretral durante su ingreso en UCI. Esta cifra confirma que es uno de los dispositivos invasivos más utilizados en el paciente crítico y, por tanto, un objetivo prioritario de las medidas preventivas. Los porcentajes del 68,29%, 82,16% y 91,43% no corresponden al dato publicado en ese informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977352") }, {"long_answer": "Según los datos del registro ENVIN de 2017 recogidos en el documento del proyecto ITU-Zero, el 10,42% de los pacientes con infección urinaria relacionada con sonda uretral presentaron aislamiento de enterobacterias productoras de betalactamasas de espectro extendido. Este dato refleja la importancia de las bacterias multirresistentes en estas infecciones y la necesidad de un uso prudente de antibióticos. Los porcentajes del 7,93%, 13,27% y 5,61% no corresponden al dato publicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977355") }, {"long_answer": "Según el documento del proyecto ITU-Zero, con datos del registro ENVIN de 2017, el porcentaje de bacterias multirresistentes (colonización o infección) aisladas durante el ingreso en UCI en relación con los pacientes con infección urinaria fue del 0,31%. Este indicador forma parte de la vigilancia de las resistencias en el paciente crítico. Los valores del 0,08%, 0,15% y 0,25% no corresponden al dato que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977356") }, {"long_answer": "Según el informe de 2017 recogido en el documento del proyecto ITU-Zero, el 45,76% de las cepas de Klebsiella pneumoniae aisladas fueron resistentes a ciprofloxacino. Esta alta tasa de resistencia a fluoroquinolonas limita las opciones terapéuticas empíricas en la infección urinaria relacionada con sonda y refuerza la importancia de prevenirla y de usar antibióticos de forma prudente. Los porcentajes del 39,29%, 61,50% y 51,30% no corresponden al dato publicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977359") }, {"long_answer": "El objetivo principal del proyecto ITU-Zero es reducir en un 40% la tasa media estatal de infección urinaria relacionada con sonda uretral en las UCI, mediante la aplicación de un paquete de medidas sobre la indicación, inserción, mantenimiento y retirada precoz de la sonda, junto con un plan de seguridad integral. Reducir la ratio de utilización de sonda es un objetivo secundario, no el principal, y reducir un 20% la tasa o un 50% las resistencias no corresponden a los objetivos planteados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97735f") }, {"long_answer": "El proyecto ITU-Zero recomienda valorar diariamente la necesidad de mantener la sonda uretral y retirarla en cuanto deje de ser necesaria, porque el riesgo de infección aumenta con cada día de sondaje. La sedación del paciente no es por sí sola un criterio de retirada; la retención aguda de orina es una indicación para sondar, no para retirar la sonda, y la necesidad de una intervención quirúrgica tampoco es el criterio que marca la retirada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977361") }, {"long_answer": "El proyecto ITU-Zero recomienda realizar higiene de manos inmediatamente antes y después de la inserción de la sonda uretral, así como antes y después de cualquier manipulación de la sonda o del sistema de drenaje, para evitar la transmisión de microorganismos. Los lavados vesicales rutinarios no están recomendados porque abren el sistema; vaciar la bolsa y no cambiar rutinariamente sondas ni sistemas son medidas de mantenimiento, pero no lo que se debe hacer antes y después de la inserción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977366") }, {"option_2": "Solo al finalizar el turno de trabajo", "long_answer": "Según el protocolo de higiene de manos del proyecto ITU-Zero, las manos deben limpiarse justo antes de manipular cualquier sonda urinaria o sistema de drenaje, que corresponde al momento antes de realizar una tarea aséptica, y también inmediatamente después. Limitar la higiene al final del turno deja sin proteger todas las manipulaciones intermedias, después de dar la mano al paciente lo que procede es la higiene tras el contacto, y antes de administrar medicación no es el momento relacionado con la sonda."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97736b") }, {"option_1": "Realizar la inserción de la sonda con técnica limpia, sin guantes", "option_2": "Pautar antibiótico sistemáticamente a todo paciente con bacteriuria asintomática", "long_answer": "Una consideración clave en el cuidado del paciente con sonda urinaria es asegurarse de que la indicación del sondaje permanente es adecuada, porque evitar sondajes innecesarios es la medida más eficaz para prevenir la infección urinaria asociada. Las demás opciones son incorrectas: la inserción debe hacerse con técnica aséptica y guantes estériles, no con técnica limpia sin guantes; la bacteriuria asintomática no debe tratarse sistemáticamente con antibióticos, y el sistema de drenaje debe ser cerrado, nunca abierto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97736c") }, {"option_1": "Sustituir la necesidad de usar guantes", "option_2": "Proteger al paciente, al profesional y al entorno sanitario de microorganismos patógenos", "option_3": "Eliminar la necesidad de una inserción aséptica de la sonda", "long_answer": "Según el Programa de Seguridad Integral ITU-Zero, basado en la estrategia de la OMS, la higiene de manos tiene como objetivo proteger al paciente, al profesional y al entorno sanitario de los microorganismos patógenos, interrumpiendo su transmisión a través de las manos. No sustituye al uso de guantes cuando están indicados, no elimina la necesidad de una inserción aséptica de la sonda y no tiene relación con la esterilización del instrumental, que requiere procesos específicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97736d") }, {"long_answer": "Las infecciones asociadas a la asistencia sanitaria son las que se adquieren como consecuencia de la atención sanitaria, clásicamente en el hospital, y que no estaban presentes ni en periodo de incubación en el momento del ingreso. Se incluyen las relacionadas con dispositivos y procedimientos, como la infección urinaria por sonda o la infección quirúrgica. No se definen por el tipo de microorganismo, ya que pueden ser virales, bacterianas o fúngicas, ni por su localización, como las respiratorias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977374") }, {"long_answer": "En la tabla de antimicrobianos para profilaxis del protocolo Infección Quirúrgica Zero, el aztreonam tiene una vida media de 1,5 a 2 horas, por lo que en intervenciones prolongadas puede ser necesario repetir la dosis para mantener concentraciones eficaces en los tejidos. Esta información se utiliza para calcular el intervalo de redosificación. Las vidas medias de 3-5, 4-6 y 7-8 horas no corresponden al aztreonam."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977375") }, {"long_answer": "En la tabla de antimicrobianos para profilaxis del protocolo Infección Quirúrgica Zero, el ciprofloxacino se administra en perfusión de unos 30 minutos, lo que permite alcanzar concentraciones adecuadas en los tejidos y reducir los efectos adversos de una administración rápida. Es importante tenerlo en cuenta para que la infusión termine dentro de los 60 minutos previos a la incisión. Un bolo de 5 minutos es demasiado rápido, y los tiempos de 20-30 o 40-60 minutos no coinciden con el valor que recoge la tabla."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97737d") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977383") }, {"option_3": "Mantenimiento de la glucemia por encima de 250 mg/dl durante la intervención", "long_answer": "Según el protocolo Infección Quirúrgica Zero, un punto crítico para mantener la normoglucemia es medir periódicamente la glucemia antes y después de la intervención quirúrgica, para detectar y corregir la hiperglucemia y mantener la glucosa por debajo de 180 mg/dl durante el perioperatorio. Usar cortadoras de pelo pertenece a la medida de eliminación correcta del vello, y mantener la glucemia por encima de 250 mg/dl es justo lo contrario de lo que se recomienda."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977384") }, {"long_answer": "El protocolo Infección Quirúrgica Zero indica que cada hospital debe adaptar las intervenciones preventivas propuestas a su propia organización, respetando su contenido esencial basado en la evidencia pero ajustando circuitos, responsables y materiales a su realidad. Así se facilita su implantación y su cumplimiento. Aplicarlas tal cual sin adaptación puede chocar con la organización local, ignorarlas es contrario al proyecto y modificarlas sin consultar puede alterar su eficacia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977385") }, {"long_answer": "Para la implantación del protocolo Infección Quirúrgica Zero se recomienda utilizar el ciclo PDCA (planificar, hacer, verificar y actuar) de mejora continua de la calidad, que permite planificar las medidas, aplicarlas, medir su cumplimiento y corregir las desviaciones. Las demás opciones son incorrectas: sí es necesaria una estrategia específica; el liderazgo de la dirección es importante, pero no suficiente por sí solo, y la implicación de las comisiones hospitalarias, como la de infecciones, es clave para el éxito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977387") }, {"long_answer": "El protocolo Infección Quirúrgica Zero recomienda que en las áreas de atención donde se aplica la intervención exista un stock suficiente de los materiales necesarios, como clorhexidina alcohólica, cortadoras eléctricas, sistemas de calentamiento o glucómetros, para que su falta no impida cumplir las medidas. También se aconseja utilizar cartelería específica como recordatorio. Depender de la disponibilidad puntual del material, no preparar las áreas o prescindir de la cartelería dificulta la implantación del protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977389") }, {"long_answer": "En la fase de postimplantación del protocolo Infección Quirúrgica Zero se sugiere realizar, como mínimo, alguna comprobación general de que las medidas preventivas se siguen cumpliendo razonablemente bien, para evitar que la adherencia disminuya con el tiempo. No realizar ninguna comprobación supone perder el control del cumplimiento; la verificación no debe depender exclusivamente de Medicina Preventiva, sino implicar a los equipos, y no se plantea sustituir los listados de verificación por sistemas más generales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977392") }, {"long_answer": "El objetivo principal del Programa de Cirugía Segura del Sistema Nacional de Salud es reducir la tasa de eventos adversos en los pacientes quirúrgicos, mediante la implantación del listado de verificación quirúrgica, la mejora de la cultura de seguridad y la prevención de la infección quirúrgica. Mejorar la calidad asistencial es un fin general de todo el sistema, y promover la cultura de seguridad o reforzar la formación en cirugía segura son tareas o estrategias del programa para alcanzar su objetivo principal, no el objetivo en sí."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977393") }, {"long_answer": "Una de las tareas del Programa de Cirugía Segura es promover la cultura de seguridad en cirugía, es decir, que los profesionales del bloque compartan actitudes y prácticas orientadas a prevenir errores, comunicar los incidentes y trabajar en equipo. Esta tarea se apoya en la medición basal de la cultura de seguridad y en el uso del listado de verificación. El programa no pretende incrementar el número de intervenciones, reducir la calidad de la atención ni es un proyecto de investigación en cirugía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977395") }, {"long_answer": "El listado de verificación quirúrgica de la OMS incluye la identificación del paciente y la confirmación del lugar y del procedimiento quirúrgico, tanto en la entrada antes de la inducción anestésica como en la pausa quirúrgica antes de la incisión, además de otros puntos como la alergia conocida, el riesgo de vía aérea difícil o de hemorragia, y la profilaxis antibiótica. La medición de la presión arterial, el control de la temperatura ambiente y el análisis de sangre del paciente no son elementos del listado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a0") }, {"long_answer": "El cuestionario de seguridad, en su versión española del Hospital Survey on Patient Safety Culture, se utiliza en el Programa de Cirugía Segura para evaluar el clima o la cultura de seguridad del paciente entre los profesionales del bloque quirúrgico, explorando la comunicación, el trabajo en equipo, la notificación de incidentes o el apoyo de la dirección. No mide la satisfacción de los pacientes, ni la eficiencia del personal quirúrgico, ni la limpieza de los quirófanos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c2") }, {"long_answer": "El Protocolo de actuación sanitaria frente a la violencia sexual se aplica en los distintos ámbitos asistenciales del sistema sanitario donde puede atenderse a una víctima, entre ellos atención primaria, urgencias, atención hospitalaria y los centros de atención a la salud mental, donde se pueden detectar situaciones de violencia sexual y sus secuelas psicológicas. Los centros de atención odontológica, las oficinas de farmacia y los centros de rehabilitación física no se recogen como ámbitos de aplicación del protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c3") }, {"long_answer": "El Protocolo se elaboró mediante consensos de grupos de trabajo técnico en los que participaron profesionales de distintas disciplinas y representantes de las comunidades autónomas, sociedades científicas y otros organismos, integrando la evidencia disponible y la experiencia práctica. No se basó en entrevistas individuales con expertos, en un análisis estadístico de casos reales ni en la simple revisión de protocolos extranjeros, aunque estos pudieran consultarse como referencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773df") }, {"long_answer": "El embarazo se considera una etapa de máxima vulnerabilidad afectiva y psicológica porque altera el funcionamiento hormonal y metabólico de la mujer, lo que se acompaña de cambios emocionales, más sensibilidad al estrés y mayor riesgo de trastornos como la ansiedad o la depresión perinatal. Si además existe violencia, el impacto sobre la salud mental es mayor. Las demás opciones son incorrectas: ser una etapa feliz no explica la vulnerabilidad, el embarazo sí influye en la salud mental y no aumenta la autonomía personal de la mujer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f2") }, {"long_answer": "Según los datos recogidos en el protocolo, el 23,3% de las personas sin hogar usuarias de centros asistenciales de alojamiento en España son mujeres. Esta menor presencia no significa que el sinhogarismo femenino sea poco frecuente, sino que las mujeres recurren más a soluciones informales, como alojarse con conocidos, y tienen más barreras de acceso a estos recursos, lo que aumenta su exposición a la violencia. Los porcentajes del 24%, 35% y 38% no corresponden al dato del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f3") }, {"long_answer": "La falta de oportunidades laborales es uno de los factores que explican la vulnerabilidad económica de las mujeres sin hogar, ya que dificulta disponer de ingresos estables y acceder a una vivienda, y se suma a la brecha salarial, la precariedad y las cargas de cuidados. Las demás opciones atribuyen la situación a características individuales, como la inestabilidad emocional o una mala gestión financiera, o a la dependencia de la asistencia social, cuando el protocolo subraya los factores estructurales y sociales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f9") }, {"long_answer": "Según la encuesta de la Agencia de los Derechos Fundamentales de la Unión Europea, el 42% de las personas LGBTI refirieron haber sufrido discriminación en el último año en algún ámbito de su vida, como el trabajo, la educación, la vivienda o los servicios sanitarios. Este dato refleja una situación de vulnerabilidad que puede afectar a su salud y a su acceso a los servicios. Los porcentajes del 35%, 48% y 50% no corresponden al dato de la encuesta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773fe") }, {"long_answer": "En los casos de violencia sexual, la recogida de muestras analíticas y biológicas es fundamental para obtener pruebas que puedan utilizarse en el proceso judicial, como restos biológicos del agresor para el análisis de ADN, siempre preservando la cadena de custodia y en coordinación con medicina forense. No tiene como finalidad determinar enfermedades previas a la agresión. El análisis toxicológico y la valoración de la anticoncepción de emergencia son actuaciones concretas, pero no explican la importancia principal de la recogida de muestras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977401") }, {"option_2": "Un certificado de aptitud laboral", "long_answer": "En el momento del alta hospitalaria, a la paciente que ha sufrido violencia sexual se le debe entregar un informe detallado de las exploraciones realizadas y de los tratamientos administrados, incluidas las profilaxis de infecciones de transmisión sexual y la anticoncepción de emergencia, así como las citas de seguimiento. Este informe garantiza la continuidad asistencial y puede tener valor en el proceso judicial. La medicación diaria no es un elemento general del alta, un certificado de aptitud laboral no procede y la lista de servicios no sustituye al informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977404") }, {"long_answer": "La recogida de muestras y evidencias durante la exploración sanitaria en casos de violencia sexual tiene como objetivo realizar las pruebas forenses que permitan documentar la agresión e identificar al agresor, en coordinación con medicina forense y en un único acto cuando sea posible, para evitar exploraciones repetidas. La protección de la cadena de custodia es un requisito del procedimiento para que las pruebas tengan validez, pero no su objetivo. Las medidas profilácticas y el apoyo psicológico forman parte de otras actuaciones de la atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977406") }, {"long_answer": "La intervención profesional sobre el entorno familiar y social de la mujer que ha sufrido una agresión sexual tiene como objetivo facilitar una mejor recuperación del trauma, implicando a las personas cercanas como red de apoyo, evitando actitudes culpabilizadoras y favoreciendo que la mujer se sienta protegida y creída. Las demás opciones son contrarias a la ética y a los objetivos del protocolo: no se pretende evitar la denuncia, proteger al agresor ni ocultar la situación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977407") }, {"option_3": "Realizar una citología cervical de cribado", "long_answer": "En la primera visita de seguimiento tras la agresión sexual el protocolo común del SNS indica informar a la víctima sobre las infecciones de transmisión sexual que pueden aparecer, sus síntomas y la necesidad de completar los controles serológicos, así como sobre los posibles efectos secundarios de los tratamientos profilácticos pautados (antirretrovirales, antibióticos, anticoncepción de emergencia) para favorecer la adherencia. La ecografía no forma parte de la actuación sistemática, la citología de cribado no tiene relación con la agresión y se rige por el programa poblacional, y una prueba de paternidad carece de sentido en este contexto asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977409") }, {"long_answer": "El protocolo común para la actuación sanitaria frente a la violencia sexual organiza la atención psicológica en etapas. En las 72 horas siguientes a la agresión se aplican los primeros auxilios psicológicos, cuyo fin es restablecer la sensación de seguridad física y emocional, contener, escuchar sin juzgar y atender las necesidades básicas. La intervención psicológica temprana corresponde a una fase posterior, cuando persiste sintomatología significativa, y el tratamiento psicológico se reserva para cuadros que interfieren gravemente en la vida cotidiana pasadas varias semanas. La terapia cognitivo-conductual es una modalidad de tratamiento, no la intervención propia de las primeras 72 horas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97740c") }, {"option_3": "Únicamente la credibilidad del relato de la víctima", "option_4": "Exclusivamente si existe una denuncia previa", "long_answer": "En la intervención psicológica temprana el protocolo plantea una evaluación global de la persona: su grado de vulnerabilidad, los factores de riesgo y de protección y las distintas áreas de su vida que se han visto afectadas (emocional, relacional, social, laboral o académica), con el fin de ajustar la intervención y detectar a quien necesitará tratamiento especializado. No se limita a los síntomas físicos, que son competencia de la atención médica. Valorar la credibilidad del relato no es función del profesional sanitario y genera revictimización, y la atención psicológica no está condicionada a la existencia de una denuncia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97740d") }, {"long_answer": "Según el protocolo común del SNS, el tratamiento psicológico especializado se indica cuando, pasadas cuatro a seis semanas desde la agresión, persiste sintomatología que interfiere gravemente en la vida cotidiana de la persona, lo que sugiere evolución hacia un trastorno como el estrés postraumático. Antes de ese plazo muchas reacciones son respuestas esperables ante un hecho traumático y se abordan con primeros auxilios psicológicos (primeras 72 horas) e intervención temprana. Esperar al mes sin más criterio o hasta el año supondría retrasar una atención necesaria, mientras que en las 72 horas siguientes lo indicado son los primeros auxilios psicológicos y no un tratamiento estructurado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97740f") }, {"long_answer": "La intervención psicológica temprana busca ayudar a la víctima a conectar con sus propios recursos personales y redes de apoyo, reforzando su capacidad de afrontamiento y su autonomía para favorecer la recuperación y prevenir la cronificación de los síntomas. Por eso se basa en el respeto a sus tiempos y decisiones. Evitar la expresión emocional sería contraproducente, ya que se trata de facilitarla en un entorno seguro, y limitar su toma de decisiones contradice el principio de empoderamiento. La valoración del riesgo suicida forma parte de cualquier atención en salud mental, pero no constituye el objetivo específico de esta etapa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977412") }, {"long_answer": "En la atención a la violencia sexual y de género, el personal de trabajo social sanitario es quien desarrolla la función de coordinación sociosanitaria: valora la situación social de la víctima, informa sobre derechos y recursos y deriva a los servicios sociales, a los recursos especializados de atención a la violencia y a los dispositivos comunitarios, garantizando la continuidad asistencial. El equipo de Atención Primaria participa en la detección y el seguimiento, pero la derivación a recursos sociales es competencia propia de trabajo social. Medicina Interna y la Unidad de Enfermedades Infecciosas intervienen en aspectos clínicos concretos, como la profilaxis de infecciones, y no en esta coordinación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977415") }, {"long_answer": "La intervención profesional sobre el entorno familiar y social de la mujer agredida tiene como objetivo facilitar su recuperación del trauma, convirtiendo a las personas cercanas en una red de apoyo que la crea, no la culpabilice y respete sus decisiones. El protocolo recomienda orientar a la familia sobre las reacciones esperables tras una agresión y sobre cómo acompañar sin revictimizar. Las demás opciones son contrarias a los principios del protocolo: nunca se pretende impedir la recuperación, proteger a la persona agresora ni minimizar la violencia sufrida, ya que la minimización es precisamente una de las actitudes del entorno que más dificultan la recuperación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977419") }, {"long_answer": "La Ley 8/2021, de 2 de junio, reforma la legislación civil y procesal para el apoyo a las personas con discapacidad en el ejercicio de su capacidad jurídica, adaptando el ordenamiento español a la Convención de Naciones Unidas sobre los derechos de las personas con discapacidad. Sustituye el modelo de incapacitación y sustitución en la toma de decisiones por un sistema de apoyos que respeta la voluntad y preferencias de la persona. El protocolo de violencia sexual la cita al abordar la atención a mujeres con discapacidad. Las Leyes 5/2019, 10/2018 y 12/2020 no corresponden a esta reforma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97741a") }, {"question": "Según la Ley 8/2021, ¿con qué carácter pueden establecerse medidas de apoyo de tipo representativo (curatela representativa) para las personas con discapacidad?", "option_1": "Nunca pueden establecerse", "option_2": "Solo de forma excepcional, en casos muy concretos", "option_3": "En la mayoría de los casos", "option_4": "En todos los casos, de forma automática", "long_answer": "La Ley 8/2021 elimina la tutela, la patria potestad prorrogada y la rehabilitada para las personas adultas con discapacidad y establece un sistema basado en medidas de apoyo que respetan su voluntad, deseos y preferencias. La curatela pasa a ser fundamentalmente asistencial, y solo de manera excepcional y en casos muy concretos, cuando no sea posible conocer la voluntad de la persona, puede atribuirse al curador funciones de representación. Por tanto no es cierto que nunca puedan establecerse, ni que deban aplicarse en la mayoría o en todos los casos, ya que eso supondría volver al modelo sustitutivo que la reforma pretende superar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97741b") }, {"long_answer": "Antes de cualquier exploración, el protocolo establece que se debe informar a la propia víctima, adaptando la información a su edad, madurez o tipo de discapacidad, y a su representante legal cuando proceda, explicando qué se va a hacer, para qué y obteniendo el consentimiento. En menores y personas con discapacidad se debe garantizar su derecho a ser escuchadas y a participar en las decisiones. El médico forense participa en la exploración conjunta, pero no es a quien se informa previamente; la policía no debe recibir información clínica sin el marco legal adecuado, y los testigos no tienen ningún papel en el consentimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97741c") }, {"long_answer": "En los casos de agresión sexual con penetración vaginal cierta o presunta, las recomendaciones forenses recogidas en el protocolo permiten la toma de muestras biológicas hasta unos 10 días después de la agresión, ya que en la cavidad vaginal los restos de semen y de ADN pueden persistir más tiempo que en otras localizaciones gracias a las técnicas actuales de análisis. En la cavidad oral y la región anal los plazos son mucho más cortos. Por ello, plazos de 3, 5 o 7 días se quedan cortos para la vía vaginal y no justifican renunciar a la recogida de muestras pasado ese tiempo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97741e") }, {"option_1": "Personas del entorno cercano y conocidas por la víctima, con frecuencia familiares", "option_2": "Personas desconocidas sin relación previa con la víctima", "option_3": "Profesionales sanitarios", "option_4": "Mujeres adultas desconocidas", "answer": 1, "long_answer": "En la violencia sexual sobre la infancia y la adolescencia la persona agresora suele ser un hombre del entorno cercano de la víctima, conocido por ella y con frecuencia un familiar o alguien con una relación de confianza o autoridad, lo que facilita el acceso al menor, la repetición del abuso y el secreto. Los estudios citados en el protocolo, como los de Save the Children, muestran que la gran mayoría de los agresores son conocidos. La idea de que el agresor suele ser un desconocido es un mito que dificulta la detección. Los profesionales sanitarios y las mujeres desconocidas no constituyen el perfil habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977421") }, {"option_3": "Delegar toda la actuación en los servicios sociales sin intervención sanitaria", "long_answer": "Ante la violencia sexual en la infancia, los servicios de salud deben priorizar el enfoque de prevención y detección temprana, porque el sistema sanitario es uno de los lugares donde con más frecuencia se pueden identificar indicadores de abuso, y una detección precoz permite proteger al menor y reducir las secuelas. Delegar toda la actuación en servicios sociales vulnera la responsabilidad sanitaria y la atención integral. Conocer a los ofensores menores sin responsabilidad penal no es una acción sanitaria prioritaria, y brindar asesoramiento jurídico o representación legal corresponde a otros profesionales, no a los servicios de salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977422") }, {"question": "¿Cuál de los siguientes indicadores comportamentales es más específico de violencia sexual en niñas, niños y adolescentes?", "long_answer": "Las conductas sexualmente seductoras o los comportamientos y conocimientos sexuales impropios para la edad se consideran indicadores con mayor especificidad de violencia sexual en la infancia y adolescencia, porque reflejan una exposición a la sexualidad adulta que el menor no puede haber adquirido por su desarrollo normal. El protocolo pide a los profesionales estar atentos a ellos. La delincuencia, las fugas del hogar y las autolesiones o conductas agresivas son indicadores de malestar y posible maltrato, pero son inespecíficos, ya que pueden deberse a muchas otras situaciones de riesgo psicosocial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977426") }, {"option_2": "Repetir la exploración y el relato del menor tantas veces como sea necesario", "option_3": "Confrontar al menor con la persona presuntamente agresora", "option_4": "Condicionar la asistencia sanitaria a la presentación de denuncia", "long_answer": "La pauta general que rige toda la actuación sanitaria ante la violencia sexual en niñas, niños y adolescentes es asegurar que prevalece su interés superior, recogido en la Ley Orgánica 8/2021 de protección integral a la infancia. Esto implica evitar la victimización secundaria, actuar con celeridad y adaptar la atención a su edad y madurez. Repetir exploraciones y relatos genera revictimización, por lo que el protocolo recomienda una única exploración conjunta con el forense. Confrontar al menor con el agresor es contrario a su protección, y la asistencia sanitaria nunca se condiciona a la denuncia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97742c") }, {"question": "Según el protocolo Infección Quirúrgica Zero (IQZ), ¿qué porcentaje del total de infecciones nosocomiales en enfermos hospitalizados suponen las infecciones de localización quirúrgica (ILQ)?", "long_answer": "El protocolo del proyecto Infección Quirúrgica Zero, con datos del estudio EPINE, señala que las infecciones de localización quirúrgica suponen alrededor del 25,7% de las infecciones relacionadas con la asistencia sanitaria en pacientes hospitalizados, situándose entre las más frecuentes junto con las respiratorias y urinarias. Esta magnitud justifica un programa específico de prevención basado en medidas de eficacia demostrada. Las cifras de 5,7% y 15,3% infravaloran su peso dentro de las infecciones nosocomiales, mientras que un 37,1% lo sobreestima."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97742d") }, {"long_answer": "El protocolo IQZ destaca que las infecciones de localización quirúrgica tienen un gran impacto en la morbimortalidad: prolongan la estancia hospitalaria, aumentan los reingresos y los costes y multiplican aproximadamente por cinco el riesgo de muerte de los pacientes que las sufren frente a los que no las presentan. Un aumento del 50% infravaloraría claramente este efecto. Las opciones que indican reducción del riesgo de muerte o ausencia de efecto son incorrectas, puesto que la ILQ es una complicación grave y evitable que empeora el pronóstico del paciente quirúrgico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97742f") }, {"long_answer": "La antisepsia de la piel con clorhexidina alcohólica al 2% ha demostrado una eficacia notable en la prevención de las infecciones de localización quirúrgica, superior a la de la povidona yodada, y por eso es una de las medidas básicas del proyecto IQZ. Combina la acción rápida del alcohol con el efecto residual de la clorhexidina. El uso de guantes estériles es una norma de asepsia general, pero no es la medida destacada por su eficacia diferencial. La povidona yodada queda como alternativa cuando la clorhexidina está contraindicada, y los antibióticos de amplio espectro no se recomiendan, ya que la profilaxis debe ser adecuada y de espectro ajustado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977431") }, {"long_answer": "El protocolo IQZ considera altamente factible reducir alrededor de un 60% la frecuencia de las infecciones de localización quirúrgica si se aplican de forma conjunta y sistemática las mejores medidas preventivas disponibles, como la profilaxis antibiótica adecuada, la antisepsia con clorhexidina alcohólica, la correcta eliminación del vello y el mantenimiento de la normotermia y la normoglucemia. Una reducción del 30% o del 45% infravalora el potencial de estas intervenciones, mientras que un 75% excede lo que la evidencia considera alcanzable. Aun así, el objetivo oficial del proyecto se fijó de forma prudente en una reducción del 15%."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977434") }, {"long_answer": "La intervención STOP-ILQ es el conjunto estandarizado de medidas preventivas individuales que se aplican a cada paciente quirúrgico dentro del proyecto Infección Quirúrgica Zero para prevenir las infecciones de localización quirúrgica: adecuación de la profilaxis antibiótica, pincelado con clorhexidina alcohólica al 2%, eliminación correcta del vello, mantenimiento de la normotermia y control de la glucemia. No es un plan de seguimiento postoperatorio ni un sistema de alerta temprana de infecciones, y aunque incluye la adecuación de la profilaxis antibiótica, no se limita a mejorar la adherencia a ella, sino que integra varias medidas en un paquete."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977435") }, {"question": "¿Cuál de las siguientes medidas preventivas NO tiene carácter obligatorio, sino opcional, en el proyecto Infección Quirúrgica Zero (IQZ)?", "answer": 4, "long_answer": "La medida que no es obligatoria es el mantenimiento de la normotermia, que el proyecto IQZ incluye junto con el control de la normoglucemia como medidas opcionales que cada centro puede incorporar. Las tres medidas básicas de cumplimiento obligatorio en todos los hospitales participantes son la adecuación de la profilaxis antibiótica, el pincelado de la piel con clorhexidina alcohólica al 2% y la eliminación correcta del vello, evitando el rasurado y usando maquinilla eléctrica cuando sea necesario. Todas ellas forman parte del paquete STOP-ILQ y se registran en el listado de verificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977438") }, {"question": "¿Cuál es el principal mecanismo de pérdida de calor en el paciente quirúrgico que favorece la hipotermia?", "answer": 2, "long_answer": "La radiación es el principal mecanismo de pérdida de calor en el paciente quirúrgico, responsable de la mayor parte de las pérdidas, porque la piel expuesta transfiere calor a las superficies más frías del quirófano. A ello se suma la redistribución del calor central hacia la periferia por la vasodilatación anestésica. La conducción (contacto con la mesa o soluciones frías) y la evaporación (preparación de la piel, cavidades abiertas) contribuyen en menor medida. La vasoconstricción no produce hipotermia: es la respuesta termorreguladora que intenta conservar el calor y que la anestesia inhibe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97743a") }, {"long_answer": "En el proyecto IQZ, el control de la normoglucemia perioperatoria se aplica a los pacientes quirúrgicos que cumplen unas condiciones clínicas específicas definidas en el protocolo, como el tipo de intervención y la situación metabólica del paciente, ya que es en ellos donde la hiperglucemia aumenta el riesgo de infección de localización quirúrgica. Los criterios de inclusión de una medida preventiva clínica no pueden basarse en la edad y el género por sí mismos, ni mucho menos en la nacionalidad o la situación socioeconómica, que no guardan relación con el riesgo de infección y supondrían una discriminación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97743b") }, {"long_answer": "Para la implantación del protocolo IQZ en los centros se recomienda utilizar el ciclo PDCA de mejora continua de la calidad (planificar, hacer, verificar y actuar), que permite introducir las medidas, evaluar su cumplimiento con indicadores y corregir las desviaciones de forma iterativa. Esta metodología se combina con una estrategia multimodal que incluye formación, recordatorios y retroalimentación de resultados. Una estrategia unimodal ha demostrado ser menos eficaz para cambiar la práctica clínica, la estrategia de mantenimiento no sirve para implantar un cambio y minimizar la formación del personal es contrario a los objetivos del proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97743d") }, {"long_answer": "El proyecto IQZ establece que los coordinadores del proyecto en cada hospital deben recibir una formación presencial en Madrid, organizada por el Ministerio de Sanidad y las sociedades científicas implicadas, para conocer en detalle las medidas preventivas, la metodología de implantación y el sistema de registro, y poder después formar y liderar a los equipos de sus centros. La formación en línea a través del curso STOP-ILQ es la formación mínima exigida al resto de profesionales implicados, no a los coordinadores. La formación a distancia genérica o autodidacta no garantiza la homogeneidad necesaria en un proyecto multicéntrico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97743f") }, {"option_3": "El profesional de enfermería del quirófano", "long_answer": "En el proyecto IQZ el profesional de enfermería del quirófano es la figura clave en la cumplimentación del listado de verificación, ya que está presente durante todo el proceso, prepara al paciente y comprueba la eliminación del vello, el pincelado con clorhexidina alcohólica, la administración de la profilaxis antibiótica y el control de la temperatura, por lo que registra la mayoría de los datos. El cirujano y el anestesiólogo aportan y verifican los apartados que les corresponden, como la indicación de la profilaxis, pero no anotan la mayor parte del listado. El médico de la planta quirúrgica no participa en el registro intraoperatorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977444") }, {"long_answer": "La vasoconstricción arteriovenosa termorreguladora es el mecanismo efector autonómico más importante y más utilizado por el ser humano para conservar el calor: al cerrar los cortocircuitos arteriovenosos de la piel de manos y pies reduce la pérdida de calor por la superficie cutánea. La anestesia la inhibe, lo que explica la rápida aparición de hipotermia perioperatoria. El temblor es un mecanismo de producción de calor que solo se activa con umbrales más bajos y tiene un coste metabólico alto. El sudor es la principal defensa frente al calor y la respiración no tiene un papel relevante en la termorregulación humana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977447") }, {"long_answer": "La evidencia recogida en el protocolo de prevención de la infección quirúrgica muestra que calentar los líquidos intravenosos entre 37 y 41 ºC disminuye aproximadamente 0,5 ºC la caída de la temperatura corporal central durante la cirugía, por lo que es una recomendación fuerte para prevenir la hipotermia perioperatoria, especialmente cuando se infunden grandes volúmenes. No eleva la temperatura central 2 ºC, ya que su efecto es preventivo y moderado, ni aumenta el riesgo de temblor, que precisamente se asocia a la hipotermia. Afirmar que no tiene efecto contradice la evidencia disponible."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977449") }, {"long_answer": "Durante la anestesia general o neuroaxial se recomienda monitorizar la temperatura central del paciente y mantener la normotermia, es decir, una temperatura igual o superior a 36 ºC, utilizando cuando sea necesario sistemas de calentamiento activo como mantas de aire caliente y calentadores de fluidos. La anestesia altera la termorregulación y favorece la hipotermia, que se asocia a más infección quirúrgica, coagulopatía y necesidad de transfusión. Aplicar hielo es contrario al objetivo, no existe una medicación indicada para elevar la temperatura y afirmar que no es necesario controlarla contradice las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97744b") }, {"long_answer": "El calentamiento de los líquidos intravenosos a una temperatura de entre 37 y 41 ºC reduce en torno a 0,5 ºC la caída de la temperatura corporal central que se produce durante la cirugía, por lo que se recomienda para prevenir la hipotermia perioperatoria y sus complicaciones, entre ellas la infección de localización quirúrgica. Su efecto es preventivo: no aumenta la caída de temperatura en 1 ni en 2 ºC, lo que sería contrario a su propósito, y afirmar que carece de efecto no se ajusta a la evidencia que sustenta esta recomendación fuerte."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97744f") }, {"option_2": "Prolongar el ayuno absoluto desde la medianoche anterior", "long_answer": "La administración preoperatoria de hidratos de carbono orales en forma de bebidas carbohidratadas claras, hasta dos horas antes de la cirugía programada, mejora la sensación de bienestar del paciente, reduce la sed y el hambre y previene la hipoglucemia y la deshidratación asociadas al ayuno, además de atenuar la resistencia a la insulina. Prolongar el ayuno absoluto desde la medianoche es precisamente la práctica que se pretende abandonar. Los líquidos intravenosos son una medida invasiva que no aporta el beneficio metabólico ni el confort de la vía oral, y afirmar que no se puede mejorar es incorrecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977451") }, {"long_answer": "El tratamiento preoperatorio con hidratos de carbono complejos por vía oral reduce el catabolismo inducido por el ayuno y por el estrés quirúrgico, ya que el paciente llega a la intervención en un estado metabólico alimentado. Con ello disminuye la resistencia a la insulina postoperatoria, se preserva la masa muscular y mejora el bienestar. Por tanto no aumenta la resistencia a la insulina, sino que la reduce, ni incrementa el riesgo de complicaciones postoperatorias. Tampoco es cierto que no tenga efecto en la recuperación, ya que forma parte de los programas de recuperación intensificada tras la cirugía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977460") }, {"long_answer": "Aedes aegypti, el vector más competente para la transmisión del dengue, el chikungunya y el Zika, fue eliminado de gran parte del continente americano gracias a las campañas de erradicación de mediados del siglo XX. Al abandonarse dichas campañas, el mosquito se reintrodujo y volvió a extenderse durante la década de 1980, lo que explica la reemergencia del dengue en la región y, posteriormente, la expansión del chikungunya y el Zika. Las décadas de 1970, 1990 y 2000 no corresponden al momento de reintroducción que recoge el Plan Nacional de enfermedades transmitidas por vectores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977464") }, {"long_answer": "El objetivo general del Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores es reducir la carga y la amenaza que suponen para la población las enfermedades humanas transmitidas por mosquitos del género Aedes, como el dengue, el chikungunya y el Zika, mediante la vigilancia entomológica y epidemiológica, el control vectorial y la preparación de la respuesta. La erradicación de todas las especies de Aedes en España no es un objetivo realista, dado que Aedes albopictus está ampliamente establecido. Este plan se centra en Aedes, no en otros vectores, e incrementar su propagación es lo contrario de lo que se persigue."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97746d") }, {"long_answer": "La principal vía de transmisión del virus Zika al ser humano es la picadura de mosquitos infectados del género Aedes, sobre todo Aedes aegypti y, en menor medida, Aedes albopictus, presente en España. Por eso las medidas de control vectorial y de protección frente a picaduras son la base de su prevención. El Zika puede transmitirse también por vía sexual, por transfusión sanguínea y de forma vertical durante el embarazo, con riesgo de microcefalia, pero se trata de vías secundarias en términos de número de casos. El contacto con material infectado no es una vía relevante de transmisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ca") }, {"long_answer": "La Estrategia Estatal para combatir las violencias machistas define la agresión sexual como los ataques sexuales realizados sin consentimiento, que atentan contra la libertad sexual y condicionan la vida sexual de otra persona, en línea con la Ley Orgánica 10/2022 de garantía integral de la libertad sexual, que sitúa el consentimiento en el centro. La primera opción es incorrecta porque habla de actos con consentimiento. Las estrategias de un adulto para ganarse la confianza de un menor por internet definen el grooming, y la distribución de imágenes sexuales para causar angustia corresponde a otra forma de violencia sexual digital."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773cd") }, {"long_answer": "Según los datos de la Macroencuesta de Violencia contra la Mujer recogidos en el protocolo, el 43,7% de las mujeres que han sufrido violencia sexual había utilizado algún servicio de urgencias en los 12 meses previos, porcentaje que asciende al 58,8% entre las que sufrieron una violación, frente al 28,3% de las mujeres que nunca han sufrido violencia sexual. Estas cifras muestran que los servicios sanitarios, y en especial urgencias, son un lugar clave para la detección. El 22,3% no corresponde a ninguno de estos grupos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d1") }, {"long_answer": "La Ley Orgánica 3/2007 para la igualdad efectiva de mujeres y hombres establece que las políticas, estrategias y programas de salud integrarán el principio de igualdad de trato, y que este derecho se concretará en el ámbito de la salud pública mediante un conjunto de actuaciones y programas dirigidos a evitar la discriminación entre mujeres y hombres por sus diferencias biológicas o por estereotipos sociales, incluida la atención a la violencia de género. No se concreta mediante la financiación de tratamientos concretos, la creación de un sistema de seguros de salud ni un sistema de identificación biométrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773d6") }, {"long_answer": "Durante el embarazo la violencia sexual es especialmente difícil de reconocer porque persisten falsas creencias y mitos que atribuyen su perpetración a personas desconocidas, cuando en realidad suele ejercerla la pareja u otras personas del entorno cercano de la mujer. Estos mitos hacen que la violencia sexual en la pareja se invisibilice y no se identifique como tal. Por ello es incorrecto afirmar que la mayoría de los agresores son desconocidos. Tampoco es una situación rara ni las embarazadas tienen menos probabilidades de sufrirla; de hecho, el embarazo puede ser un momento de inicio o agravamiento de la violencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773da") }, {"long_answer": "Durante el embarazo hay que prestar especial atención a los signos y síntomas de violencia de género porque las mujeres embarazadas pueden ser sometidas a violencia física y sexual, y esta etapa puede suponer el inicio o el agravamiento del maltrato, con consecuencias graves para la mujer y el feto, como aborto, parto prematuro o bajo peso al nacer. Por ello se considera embarazo de alto riesgo. Las demás opciones son falsas y estigmatizantes: no se trata de que exageren sus síntomas, y la violencia sí tiene consecuencias graves e impacto en la salud de la embarazada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e6") }, {"long_answer": "Conocer las barreras específicas que sufren las mujeres con discapacidad, como las dificultades de comunicación y de acceso físico, la dependencia de la persona cuidadora, el desconocimiento de sus derechos o la falta de credibilidad que se les atribuye, permite adaptar la atención y promover su inclusión efectiva en los servicios sanitarios y en los circuitos de protección frente a la violencia sexual. Estas mujeres presentan mayor riesgo de sufrirla. Las demás opciones son contrarias al enfoque de derechos del protocolo, ya que culpabilizan, invisibilizan o aumentan la discriminación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773e7") }, {"long_answer": "El protocolo describe los entornos rurales como espacios en los que con frecuencia persisten estructuras patriarcales y creencias sexistas y discriminatorias de género, unidas al control social, el aislamiento y el miedo al qué dirán, lo que dificulta que las mujeres reconozcan y denuncien la violencia sexual. Afirmar que son entornos urbanos con muchos recursos es incorrecto. Aunque el medio rural puede presentar dispersión y menor accesibilidad a algunos servicios, no se caracteriza por carecer de conexión con los servicios públicos, ni por una alta diversidad cultural como rasgo definitorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ee") }, {"long_answer": "Las mujeres que han sufrido violencia sexual recurren con frecuencia al consumo de alcohol, otras sustancias y psicofármacos como estrategia para paliar el sufrimiento, lo que puede conducir al desarrollo de problemas de adicción, que a su vez aumentan su vulnerabilidad y dificultan la recuperación. Las dificultades para dormir son una consecuencia del trauma en sí, más que del consumo de sustancias. El aumento de la autoestima y la reducción del estrés no son consecuencias del consumo, que únicamente produce un alivio transitorio y agrava el malestar a medio plazo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f0") }, {"long_answer": "Según la Macroencuesta de Violencia contra la Mujer de la Delegación del Gobierno contra la Violencia de Género citada en el protocolo, el 7,4% de las mujeres que habían sufrido violencia sexual refirió haber consumido alcohol para afrontar lo sucedido. Este dato refleja que el consumo de sustancias es una estrategia de afrontamiento presente en las víctimas y que los profesionales deben explorarlo como posible indicador y consecuencia de la violencia. Las cifras de 5,5%, 12,2% y 2,8% no corresponden a este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f1") }, {"option_4": "El elevado número de denuncias presentadas por las víctimas", "long_answer": "Una de las principales dificultades para conocer la magnitud real de la trata con fines de explotación sexual en España es que se trata de un delito vinculado a la delincuencia organizada, que actúa en la clandestinidad, controla a las víctimas mediante amenazas, deudas y aislamiento y dificulta su identificación. Por eso los casos detectados representan solo una parte del problema. Ni la falta de recursos financieros ni la falta de voluntad política se señalan como la causa principal, y las víctimas apenas denuncian, por miedo o por su situación administrativa, de modo que un elevado número de denuncias no es real."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773f7") }, {"long_answer": "Algunas autoras citadas en el protocolo relacionan el hecho de estar en situación de prostitución con un mayor riesgo de infección por VIH y otras infecciones de transmisión sexual, por la exposición a relaciones no protegidas impuestas, la violencia sexual asociada, la dificultad para negociar el uso del preservativo y las barreras de acceso a los servicios sanitarios. El uso de preservativos y mantener relaciones seguras son prácticas protectoras frente al VIH, no de riesgo, y no tener pareja con VIH tampoco constituye una práctica de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773fa") }, {"option_1": "Una mayor protección legal específica que el resto de la población", "option_2": "La ausencia de discriminación en el ámbito sanitario", "option_3": "La LGTBIfobia y el miedo a represalias o a ser estigmatizadas al revelar la violencia", "option_4": "Una mayor facilidad para denunciar la violencia sufrida", "long_answer": "Las personas LGTBI presentan una especial vulnerabilidad ante la violencia sexual por la LGTBIfobia social y estructural, que se traduce en estigmatización, rechazo y miedo a represalias o a sufrir nuevas discriminaciones si revelan la agresión o su orientación o identidad, lo que favorece el silencio y dificulta el acceso a la atención. El protocolo incluye este eje de desigualdad desde el enfoque interseccional. No disponen de una protección mayor que el resto, sí pueden encontrar discriminación en el ámbito sanitario y denunciar les resulta más difícil, no más fácil."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773fb") }, {"long_answer": "El objetivo principal de la detección temprana de la violencia sexual desde los servicios sanitarios es poder ofrecer una atención integral a las víctimas, que abarque las dimensiones física, psicológica y social, con continuidad asistencial y coordinación con otros recursos, para reducir las secuelas y evitar la cronificación. Identificar a los agresores es función policial y judicial, no sanitaria. El registro de casos para estadísticas es útil para la vigilancia, pero no es la finalidad de la detección, y la realización de pruebas forenses corresponde a la medicina forense en el marco judicial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977400") }, {"option_3": "Confirmar que la agresión ha producido un embarazo", "long_answer": "El test de embarazo se realiza en la atención inicial a la violencia sexual para detectar un posible embarazo previo a la agresión, dato imprescindible antes de pautar tratamientos como la anticoncepción de emergencia o determinados fármacos profilácticos y para orientar la atención. Un test realizado en las primeras horas no puede confirmar un embarazo derivado de la agresión, que solo se detectaría semanas después, por lo que debe repetirse en el seguimiento. No es en sí un tratamiento inmediato ni se realiza simplemente por seguir pautas, sino con una finalidad clínica concreta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97740a") }, {"long_answer": "Los primeros auxilios psicológicos, aplicados en las 72 horas siguientes a la agresión sexual, tienen como objetivo restablecer la sensación de seguridad física y emocional de la víctima: proporcionar un entorno protegido, escuchar sin juzgar, contener la angustia, atender necesidades básicas e informar de forma comprensible. Conectar a la víctima con sus recursos personales es más propio de la intervención psicológica temprana. La valoración del riesgo suicida debe estar presente en toda la atención, pero no es el objetivo central de esta fase, y facilitar la toma de decisiones es un elemento transversal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97740b") }, {"long_answer": "Según el protocolo común del SNS, la intervención psicológica temprana se plantea cuando, pasadas cuatro a seis semanas desde la agresión, la víctima presenta sintomatología significativa que no se ha resuelto espontáneamente, con el fin de evitar su cronificación. En las 72 horas siguientes a la agresión lo indicado son los primeros auxilios psicológicos, centrados en la seguridad y la contención. A los diez días o al mes muchas reacciones son todavía respuestas normales ante un trauma y no justifican por sí mismas una intervención estructurada sin valorar su evolución."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97740e") }, {"long_answer": "El apoyo psicológico a las víctimas de violencia sexual tiene como finalidad potenciar su autonomía y su autoestima, ayudándolas a recuperar el control sobre su vida, a procesar lo ocurrido y a tomar sus propias decisiones desde un enfoque de empoderamiento y no revictimizador. Las demás opciones describen justo lo contrario de lo que se pretende: fomentar la culpa y la vergüenza, promover el aislamiento o generar inseguridad son efectos de la propia violencia y de una mala atención, y la intervención profesional debe contrarrestarlos validando a la víctima y reforzando sus apoyos."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977417") });
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977418") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97741d") }, {"option_1": "Menos del 1%", "option_2": "Entre el 10% y el 20%", "option_3": "Entre el 40% y el 50%", "option_4": "Más del 70%", "answer": 2, "long_answer": "Según los datos de Save the Children recogidos en el protocolo, se estima que entre un 10% y un 20% de la población en España ha sufrido algún tipo de abuso sexual durante la infancia, una magnitud elevada que contrasta con el bajo número de casos detectados y denunciados. Esta cifra justifica que los profesionales sanitarios presten atención a los indicadores de violencia sexual en la consulta pediátrica y en la atención a adultos. Un porcentaje inferior al 1% infravalora claramente el problema, mientras que cifras del 40-50% o superiores al 70% no se corresponden con los estudios disponibles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977428") }, {"long_answer": "Las conductas sexuales impropias para la edad, como conocimientos sexuales precoces, juegos sexuales con contenido adulto o conductas sexualizadas con otras personas, son uno de los indicadores más relevantes de que una niña, niño o adolescente puede haber sido víctima de violencia sexual, por lo que deben motivar una valoración cuidadosa. No indican una explicación médica de los dolores abdominales recurrentes ni que el menor haya sido sometido a exploraciones repetitivas, que de hecho deben evitarse. Actuar con celeridad y prioridad es un principio de actuación, no algo que esas conductas indiquen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97742a") }, {"long_answer": "El protocolo promueve que cualquier profesional de la salud que tenga conocimiento o sospecha de un caso de violencia sexual sobre un niño, niña o adolescente notifique su ocurrencia, en cumplimiento del deber de comunicación que establece la Ley Orgánica 8/2021 de protección integral a la infancia y la adolescencia, para activar los mecanismos de protección. La producción de materiales de sensibilización y la prevención sobre factores de riesgo son estrategias de prevención primaria, no la respuesta ante un caso conocido o sospechado, y la primera opción no describe una actuación concreta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977432") }, {"long_answer": "El objetivo principal del proyecto Infección Quirúrgica Zero, impulsado por el Ministerio de Sanidad y las sociedades científicas de Medicina Preventiva y Enfermería, es reducir un 15% la tasa de infección de localización quirúrgica en los hospitales participantes mediante la aplicación del paquete de medidas preventivas STOP-ILQ. Aunque la evidencia sugiere que con las mejores medidas podrían alcanzarse reducciones mayores, el proyecto fijó un objetivo prudente y medible. Las cifras del 5%, 25% y 50% no corresponden al objetivo establecido en el protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977437") }, {"option_4": "Inhibición de la síntesis de ácido fólico", "long_answer": "En la combinación de alcohol y clorhexidina para la antisepsia cutánea, el alcohol aporta una acción bactericida rápida mediante la coagulación y desnaturalización de las proteínas de los microorganismos, mientras que la clorhexidina altera la membrana celular y proporciona un efecto residual prolongado sobre la piel. Esta suma explica su superioridad frente a la povidona yodada en la prevención de la infección quirúrgica. La inhibición de la pared celular es el mecanismo de los betalactámicos, la inhibición de la síntesis de ácido fólico corresponde a las sulfamidas y la destrucción directa del ADN no es el mecanismo principal de estos antisépticos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97743e") }, {"long_answer": "Para que la intervención preventiva del proyecto IQZ pueda aplicarse de forma sistemática se recomienda disponer en las áreas de atención a los pacientes de un stock suficiente de los materiales necesarios, como clorhexidina alcohólica al 2%, maquinillas eléctricas para la eliminación del vello, termómetros y sistemas de calentamiento, y los antibióticos de la profilaxis. La falta de material es una barrera frecuente para el cumplimiento. Los muebles nuevos, el material quirúrgico avanzado o los equipos de alta tecnología no son requisitos de esta intervención, basada en medidas sencillas y de bajo coste."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977440") }, {"long_answer": "Las sesiones bimensuales de evaluación del programa en cada servicio tienen como objetivo revisar las tasas de cumplimentación del listado de verificación y el grado de cumplimiento de las medidas preventivas, compartiendo los resultados con los profesionales para identificar problemas y aplicar mejoras, en la lógica del ciclo de mejora continua. No son espacios para realizar procedimientos quirúrgicos, ni su finalidad es evaluar la satisfacción del personal o discutir temas generales, sino la retroalimentación de indicadores concretos del proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977442") }, {"long_answer": "El protocolo recomienda que en cada centro se clarifique quién rellena cada apartado del listado de verificación según sus propios procedimientos de trabajo y la organización del bloque quirúrgico, de forma que las responsabilidades queden definidas y no se produzcan omisiones ni duplicidades. Dejar que cada profesional decida libremente genera variabilidad y apartados sin cumplimentar. Los pacientes no deben rellenar un registro clínico de seguridad, y designar a un único profesional para todo el listado no es realista, ya que distintos apartados dependen de la información de cirugía, anestesia y enfermería."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977450") }, {"long_answer": "Para prevenir la broncoaspiración durante la inducción anestésica en cirugía programada se recomienda un ayuno de 2 horas para los líquidos claros y de 6 horas para los alimentos sólidos, siguiendo las guías de las sociedades de anestesiología. Este intervalo es suficiente para el vaciamiento gástrico y evita los efectos negativos del ayuno prolongado, como la deshidratación, la hipoglucemia o el malestar. Un ayuno de 12 horas o el ayuno desde la medianoche no aportan más seguridad, un ayuno indiferenciado de 6 horas impide la ingesta de líquidos claros, y no establecer ningún ayuno aumentaría el riesgo de aspiración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977457") }, {"long_answer": "En la cesárea, el pincelado de la piel con solución alcohólica de clorhexidina disminuye la infección de la herida quirúrgica en comparación con otros antisépticos como la povidona yodada, gracias a su rápida acción bactericida y a su efecto residual. Por ello se recomienda como antiséptico de elección en la preparación de la piel. No es cierto que no tenga efecto ni que aumente el riesgo de infección, y su eficacia sí ha sido evaluada en ensayos clínicos y revisiones sistemáticas en cirugía obstétrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977458") }, {"long_answer": "En la cesárea, cuando el tejido celular subcutáneo tiene un grosor superior a 2 centímetros, se recomienda suturarlo porque disminuye el riesgo de hematoma o seroma y, con ello, de dehiscencia e infección de la herida quirúrgica, al eliminar el espacio muerto donde se acumulan líquidos. En grosores menores no se ha demostrado beneficio. No aumenta el riesgo de complicaciones ni la pérdida hemática, y afirmar que no tiene efecto en la recuperación contradice la evidencia que sustenta esta recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977459") }, {"question": "¿Qué grupo de enfermedades transmitidas por vectores se considera emergente en España por haber presentado transmisión autóctona en los últimos años?", "long_answer": "El Plan Nacional de Prevención, Vigilancia y Control de las Enfermedades Transmitidas por Vectores señala como enfermedades emergentes en España la fiebre del Nilo occidental, con brotes en Andalucía y Extremadura, la fiebre hemorrágica de Crimea-Congo, transmitida por garrapatas del género Hyalomma, y la meningoencefalitis por virus Toscana, transmitida por flebotomos. El paludismo, el dengue y la fiebre amarilla circularon de forma endémica en el pasado. El Zika, el chikungunya y la fiebre del Valle del Rift se diagnostican sobre todo como casos importados, por lo que no forman un grupo emergente autóctono equivalente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97745a") }, {"long_answer": "El Plan Nacional de enfermedades transmitidas por vectores recuerda que en España circularon de forma endémica en el pasado el paludismo, eliminado oficialmente en 1964, el dengue, con epidemias a principios del siglo XX, y la fiebre amarilla, que causó brotes en ciudades portuarias en los siglos XVIII y XIX. La fiebre del Nilo occidental y la fiebre hemorrágica de Crimea-Congo son enfermedades emergentes actuales. El Zika nunca ha sido endémico en España, la fiebre del Valle del Rift no se ha detectado y la fiebre exantemática mediterránea o la enfermedad de Lyme son enfermedades endémicas actuales, no del pasado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97745f") }, {"long_answer": "Aedes aegypti es el vector más competente para la transmisión del dengue, el chikungunya y el Zika, y también de la fiebre amarilla urbana, porque es un mosquito muy adaptado al entorno humano, con preferencia por picar a personas y capacidad de realizar varias ingestas de sangre en un mismo ciclo. Aedes albopictus, el mosquito tigre establecido en España, también puede transmitirlos, pero con menor competencia vectorial. Aedes japonicus tiene un papel secundario y Aedes polynesiensis es un vector de distribución limitada al Pacífico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977461") }, {"long_answer": "Aedes albopictus, conocido como mosquito tigre, se detectó por primera vez en España en 2004, en el municipio de Sant Cugat del Vallès (Barcelona). Desde entonces se ha expandido por todo el litoral mediterráneo y otras zonas del país, y es responsable de los casos autóctonos de dengue registrados en España, lo que justifica la vigilancia entomológica que establece el Plan Nacional de enfermedades transmitidas por vectores. Los años 2000, 2008 y 2010 no corresponden a su primera detección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977467") }, {"option_1": "2005", "long_answer": "Aedes aegypti se detectó por primera vez en la isla portuguesa de Madeira en 2005, donde se estableció y fue responsable del brote de dengue de 2012, con miles de casos. Este antecedente es relevante para España porque demuestra que el vector más competente para el dengue, el chikungunya y el Zika puede introducirse y establecerse en territorio europeo, y justifica la vigilancia en puertos y aeropuertos, especialmente en Canarias. Los años 2010 y 2015 son posteriores a su establecimiento, y 2012 corresponde al año del brote de dengue, no al de la detección del mosquito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97746a") }, {"question": "¿Cuál de las siguientes manifestaciones indica la progresión de una infección por virus del dengue hacia dengue grave?", "long_answer": "La dificultad respiratoria por edema pulmonar refleja la extravasación plasmática que caracteriza al dengue grave, junto con el shock, las hemorragias graves y el daño orgánico. Su aparición, generalmente al bajar la fiebre, obliga a una vigilancia estrecha y a un manejo hospitalario. La cefalea, la fiebre y las mialgias son manifestaciones habituales del dengue sin signos de alarma y no indican por sí mismas una evolución desfavorable, por lo que no sirven para identificar la progresión hacia la forma grave de la enfermedad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97746b") }, {"long_answer": "En los periodos epidémicos del chikungunya, el reservorio principal del virus es el ser humano, ya que mantiene viremias elevadas que permiten infectar a los mosquitos Aedes que le pican, estableciéndose un ciclo urbano humano-mosquito-humano. Los primates no humanos actúan como reservorio en los ciclos selváticos del continente africano, fuera de los periodos epidémicos. Los mosquitos Aedes, incluido Aedes aegypti, son vectores que transmiten el virus, no el reservorio que lo mantiene durante las epidemias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97746f") }, {"long_answer": "El vector principal de la fiebre amarilla en su ciclo urbano es Aedes aegypti, que transmite el virus de persona a persona y ha sido responsable de las grandes epidemias históricas. En el ciclo selvático intervienen otros mosquitos, como Haemagogus en América. Aedes albopictus tiene competencia vectorial para el virus en condiciones experimentales, pero no se considera el vector principal, por lo que son incorrectas las opciones que lo sitúan como vector principal junto a Aedes aegypti o en América Latina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977470") }, {"long_answer": "El periodo de incubación de la fiebre amarilla en el ser humano es de 3 a 6 días tras la picadura del mosquito infectado. Después aparece un cuadro de fiebre, cefalea, mialgias y náuseas, y en una parte de los pacientes una fase tóxica con ictericia, hemorragias e insuficiencia renal, con elevada letalidad. Un intervalo de 1 a 3 días es demasiado corto, mientras que 7 a 10 días y 10 a 14 días superan el periodo de incubación habitual. Conocer este dato es importante para la vigilancia de casos importados en viajeros procedentes de zonas endémicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772c3") }, {"long_answer": "La presión por el tiempo es uno de los factores que incrementan el riesgo de errores en la localización del área quirúrgica, en el tipo de procedimiento o en la identificación del paciente, porque favorece la omisión de comprobaciones como el marcado del sitio y el listado de verificación. Otros factores son los cambios de programación, varios procedimientos en un mismo paciente o características inusuales. Las características habituales del paciente no son un factor de riesgo, y la buena comunicación en el equipo y la escritura legible son elementos protectores que reducen los errores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ca") }, {"long_answer": "Entre las recomendaciones para la gestión segura de fármacos y fluidos se encuentra limitar las órdenes verbales o telefónicas, porque son una fuente frecuente de errores de medicación por malentendidos de nombre, dosis o vía; cuando sean imprescindibles deben repetirse y confirmarse. Las soluciones concentradas de potasio no deben almacenarse en las unidades como el bloque quirúrgico, ya que son medicamentos de alto riesgo. También se recomienda tener una política activa frente a los efectos adversos y comunicar la lista completa de medicación al siguiente proveedor, lo contrario de lo que plantean las opciones 3 y 4."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772cd") }, {"option_1": "Utilizar monitorización de la profundidad anestésica en los pacientes con mayor riesgo", "long_answer": "Para reducir la frecuencia del despertar intraoperatorio se recomienda identificar a los pacientes con mayor riesgo, como los sometidos a cirugía cardiaca, cesárea, trauma grave o con antecedentes de despertar, y utilizar en ellos monitorización de la profundidad anestésica, además de comprobar el funcionamiento del equipo de administración de anestésicos. También se recomienda monitorizar la relajación muscular y realizar una entrevista postoperatoria estructurada ante sospecha. Las demás opciones niegan precisamente esas recomendaciones, por lo que son incorrectas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772d8") }, {"long_answer": "Los criterios de inclusión de pacientes del protocolo de prevención de la infección quirúrgica se refieren a todos los pacientes que requieren una intervención quirúrgica en los servicios participantes, ya que el riesgo de infección de localización quirúrgica afecta a cualquier procedimiento. No se limitan a los pacientes hospitalizados ni a los de cirugía mayor ambulatoria, que son subgrupos de la población quirúrgica, y los pacientes en lista de espera todavía no han sido intervenidos, por lo que no pueden ser objeto de las medidas preventivas perioperatorias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772da") }, {"long_answer": "Una de las razones que justifican disponer de quirófanos especializados es minimizar la contaminación cruzada, por ejemplo en procedimientos con requisitos especiales de bioseguridad o de calidad del aire, como la cirugía de implantes, trasplantes o la que requiere aislamiento. La especialización también permite adaptar equipamiento e instalaciones. Facilitar el acceso del personal o reducir el tiempo de espera no son argumentos propios de la especialización, y evitar la centralización de recursos va en contra de la tendencia a concentrar equipamiento costoso en quirófanos determinados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772db") }, {"long_answer": "En el diseño tradicional del bloque quirúrgico predominaron los requisitos de seguridad microbiológica, como la circulación diferenciada de material limpio y sucio, la zonificación y el control de la calidad del aire, con el objetivo de prevenir la infección. El documento de estándares y recomendaciones del Ministerio señala que muchas de estas exigencias no siempre se basaban en evidencia científica sólida. Las normativas gubernamentales y la gestión de residuos condicionan aspectos concretos, pero no fueron el factor predominante en el diseño."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772e8") }, {"long_answer": "El documento de estándares y recomendaciones del bloque quirúrgico aconseja cerrar la programación de los quirófanos con 48 horas de antelación respecto al día de la cirugía, lo que permite organizar los recursos humanos y materiales, comprobar la preparación de los pacientes y comunicar la programación a las unidades implicadas, reduciendo suspensiones. Una semana de antelación resta flexibilidad para incorporar cambios clínicos, mientras que cerrar la programación 24 o 12 horas antes deja un margen insuficiente para la planificación y la preparación del paciente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ec") }, {"long_answer": "El manual de organización y funcionamiento del bloque quirúrgico debe recoger, entre otros aspectos, los circuitos de circulación de pacientes, del personal y de los equipamientos y materiales, para garantizar la seguridad, la separación de flujos limpios y sucios y la eficiencia. También incluye la cartera de servicios, la organización, las normas de funcionamiento y la gestión. El organigrama general del hospital no forma parte de este manual, los protocolos clínicos de cada especialidad se elaboran por los servicios y los resultados de los procedimientos se recogen en los sistemas de información y evaluación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772f2") }, {"long_answer": "Según el documento de estándares del bloque quirúrgico, en aplicación de la normativa de protección de datos, tiene la consideración de responsable de los ficheros de datos de carácter personal la persona designada por el centro sanitario, que debe velar por la confidencialidad, seguridad e integridad de la información clínica. No es automáticamente el director del centro ni el personal administrativo, que tratan datos pero no asumen esa responsabilidad, y el paciente es el titular de los datos y de los derechos de acceso, rectificación y cancelación, no el responsable de los ficheros."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772fd") }, {"long_answer": "El documento de estándares y recomendaciones del bloque quirúrgico recomienda disponer en la Unidad de Recuperación Post-Anestésica de 1,5 puestos por cada quirófano, dimensionamiento que permite absorber la salida de pacientes de varios quirófanos sin bloquear la actividad quirúrgica, ajustándose según la complejidad y la proporción de cirugía ambulatoria. Un solo puesto por quirófano suele resultar insuficiente y provoca esperas en el quirófano, mientras que 2 o 2,5 puestos por quirófano superan la ratio recomendada como estándar general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772fe") }, {"long_answer": "El control de enfermería de la zona postquirúrgica es un espacio de trabajo que, desde el punto de vista estructural, debe contar con tomas eléctricas suficientes para la conexión y revisión de equipos, además de la central de monitorización y visión directa de los puestos de los pacientes. No incorpora una sala de estar, que se ubica en la zona de personal, ni se trata de una sala polivalente. Que esté situado en el bloque quirúrgico describe su localización, no una característica estructural propia del control."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9772ff") }, {"long_answer": "En la zona postquirúrgica el almacén general se destina a guardar la lencería de la Unidad de Recuperación Post-Anestésica y otros materiales de uso general, de modo que estén disponibles cerca de los puestos de los pacientes. La preparación de medicamentos se realiza en un espacio específico de preparación de medicación, los equipos portátiles disponen de su propio almacén con tomas eléctricas para la carga y el material estéril se guarda en un almacén específico que garantiza sus condiciones de conservación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977304") }, {"long_answer": "La sala de reuniones de la zona de personal de anestesia, cirugía y enfermería del bloque quirúrgico está destinada a la realización de sesiones clínicas y de docencia, así como a reuniones de coordinación del equipo, favoreciendo la formación continuada y la comunicación entre profesionales. No es un espacio para distribuir lencería ni para almacenar equipos portátiles o material estéril, funciones que corresponden a los almacenes específicos del bloque quirúrgico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977306") }, {"long_answer": "El estar de personal de la zona de anestesia, cirugía y enfermería es un espacio de descanso donde se dispone del refrigerio del personal, con el equipamiento básico necesario para que los profesionales puedan tomar algo sin salir del bloque quirúrgico. No se usa para almacenar equipos portátiles ni material estéril, que tienen almacenes propios, y la ropa sucia y los residuos se gestionan en los locales de sucio, separados de las zonas de descanso por motivos de higiene y prevención de infecciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97730a") }, {"long_answer": "La normativa de baja tensión aplicable a los centros sanitarios establece que el alumbrado de seguridad debe tener, con carácter general, una autonomía mínima de 1 hora, de modo que permita la evacuación y la actuación segura en caso de fallo del suministro principal. En zonas críticas como los quirófanos se exigen además sistemas de alimentación complementarios con mayor autonomía. Una autonomía de 30 minutos es insuficiente, mientras que 2 o 3 horas no constituyen el requisito general establecido para el alumbrado de seguridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97730f") }, {"long_answer": "Disponer de un sistema de alimentación ininterrumpida distribuido, es decir, ubicado en cada sala de intervención, tiene como objetivo minimizar el número de elementos intermedios susceptibles de fallar entre la fuente de energía de respaldo y los equipos críticos del quirófano, aumentando la fiabilidad del suministro eléctrico. No busca reducir el consumo energético ni aumentar la autonomía del alumbrado de emergencia, que tiene sus propios sistemas. Aunque protege la calidad del suministro, su ventaja fundamental frente al sistema centralizado es la reducción de puntos de fallo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977310") }, {"long_answer": "Al instalar un sistema de alimentación ininterrumpida centralizado, la temperatura del local es el parámetro crítico para las baterías, ya que temperaturas elevadas reducen de forma importante su vida útil y su capacidad, por lo que la sala debe estar adecuadamente ventilada o climatizada. La presión atmosférica y el nivel de ruido no afectan de forma relevante a las baterías, y la humedad relativa, aunque debe controlarse en cualquier instalación eléctrica, no es el parámetro crítico que destacan las recomendaciones del bloque quirúrgico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977311") }, {"long_answer": "El documento de estándares del bloque quirúrgico recomienda que la potencia nominal del sistema de alimentación ininterrumpida sea igual a la del transformador de aislamiento al que alimenta, de forma que pueda asumir toda la carga del circuito del quirófano en caso de fallo del suministro sin quedar infradimensionado. Una potencia menor no garantizaría el funcionamiento de todos los equipos conectados, y una potencia mayor supondría un sobredimensionamiento innecesario. Sí existe una recomendación explícita al respecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977319") }, {"long_answer": "Las instalaciones térmicas de los edificios, incluidas las de climatización de los bloques quirúrgicos, están reguladas por el Reglamento de Instalaciones Térmicas en los Edificios (RITE), aprobado por el Real Decreto 1027/2007, que establece las exigencias de bienestar, higiene, eficiencia energética y seguridad. El Real Decreto 314/2006 aprueba el Código Técnico de la Edificación, la Ley 50/1998 es una ley de medidas fiscales y administrativas y la Ordenanza general de seguridad e higiene en el trabajo es una norma antigua de prevención de riesgos laborales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97731d") }, {"long_answer": "La norma UNE 100713, sobre instalaciones de acondicionamiento de aire en hospitales, recomienda que el climatizador del quirófano cumpla con la norma UNE-EN 1886, que establece las prestaciones mecánicas, de estanqueidad, aislamiento y filtración de las unidades de tratamiento de aire. Situarlo en el exterior del edificio no es una exigencia, y las distancias de las tomas y descargas de aire que proponen las otras opciones no se corresponden con las establecidas, ya que lo relevante es separar suficientemente las descargas de las tomas para evitar la recirculación de aire contaminado.", "question": "¿Cuál es una de las recomendaciones para el climatizador de quirófano según la norma UNE 100713?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977323") }, {"long_answer": "En los quirófanos, los elementos terminales de impulsión de aire deben incorporar filtros absolutos (HEPA), que retienen la práctica totalidad de partículas y microorganismos, para garantizar que el aire que llega al campo quirúrgico tenga la máxima calidad y reducir el riesgo de infección. Los filtros de menor eficacia se sitúan en las etapas previas del climatizador. Los denominados filtros de humedad o de temperatura no existen como tales: la humedad y la temperatura se controlan mediante los sistemas de tratamiento del aire, no mediante filtración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977326") }, {"long_answer": "Las recomendaciones para la climatización de quirófanos establecen que la última etapa de filtración dentro del climatizador sea un filtro de bolsas de eficacia F9, que retiene la mayor parte de las partículas antes de que el aire se distribuya por los conductos. La filtración absoluta, con filtros H13 o superiores, no se coloca en el climatizador sino en los elementos terminales de impulsión dentro del propio quirófano, para que el aire no se contamine en su recorrido. El filtro plano F7 corresponde a una etapa previa y los filtros de gases medicinales no forman parte del sistema de climatización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977329") }, {"long_answer": "Para asegurar que se mantienen las renovaciones de aire requeridas en el quirófano, se recomienda disponer de un variador de frecuencia en el ventilador de impulsión, que ajusta su velocidad a medida que los filtros se van colmatando y aumenta la pérdida de carga, manteniendo constante el caudal. Impulsar caudales diferentes no garantiza el número de renovaciones, los conductos flexibles en zonas de clase I se desaconsejan por acumular suciedad, y el caudal de retorno debe ser inferior al de impulsión para mantener la sobrepresión del quirófano respecto a las zonas adyacentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97732e") }, {"long_answer": "El suministro de gases medicinales y de vacío al bloque quirúrgico debe ser independiente de otros suministros del hospital para garantizar su continuidad incluso en caso de avería o de corte en otras zonas, ya que una interrupción durante una intervención puede comprometer la vida del paciente. Por ello se diseñan redes y válvulas de corte propias y sistemas de reserva. La independencia no persigue ahorrar costes de instalación, que de hecho aumentan, ni reducir el consumo de gases o facilitar el control de calidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97732f") }, {"long_answer": "En las torretas o columnas de anestesiólogo y de cirujano, las tomas de gases medicinales se recomiendan en las zonas limítrofes, es decir, en los laterales o extremos de la torreta, de modo que sean accesibles y no interfieran con el espacio de trabajo ni con el campo quirúrgico. Colocarlas en el suelo alrededor de la mesa supone un riesgo de tropiezos, de contaminación y de daño en las conexiones, el falso techo del quirófano no es accesible para la conexión directa de los equipos y el panel de control no está destinado a las tomas de gases."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977339") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97733b") }, {"long_answer": "Según las recomendaciones del bloque quirúrgico, el personal que accede al área quirúrgica no estricta debe vestir pijama y calzas o calzado de uso exclusivo del área, con el fin de no introducir contaminación desde el exterior. En el área estricta, donde se encuentran los quirófanos, se añaden el gorro y la mascarilla, y el personal que interviene directamente en el campo utiliza bata y guantes estériles. La bata verde desechable, el traje quirúrgico con mascarilla y gorro o los zuecos de goma no constituyen la vestimenta establecida para el área no estricta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977341") }, {"long_answer": "El documento del proyecto ITU-Zero recoge que alrededor del 15% de los pacientes hospitalizados desarrolla una infección urinaria durante su ingreso, en su gran mayoría asociada al uso de sonda uretral, que es el principal factor de riesgo. Esta elevada frecuencia, unida a que una parte importante de estas infecciones es evitable, justifica las medidas de inserción aséptica, mantenimiento adecuado y retirada precoz de la sonda. Las cifras del 5% y 10% infravaloran el problema, y el 20% lo sobreestima respecto al dato del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977342") }, {"long_answer": "Las infecciones del tracto urinario se encuentran entre las principales infecciones relacionadas con la asistencia sanitaria en Europa, junto con las respiratorias, las de localización quirúrgica y las bacteriemias, y la mayoría se asocian a sonda uretral. Por eso el proyecto ITU-Zero se centra en su prevención en las unidades de cuidados intensivos. Las infecciones respiratorias también son muy frecuentes, pero el documento destaca las urinarias como su objeto de estudio; las gastrointestinales y las cutáneas tienen una menor relevancia en el conjunto de estas infecciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977345") }, {"long_answer": "El documento del proyecto ITU-Zero señala que cada episodio de bacteriuria asociada a sondaje uretral con bacteriemia tiene en Estados Unidos un coste aproximado de 2.800 dólares, por el aumento de la estancia, las pruebas diagnósticas y los tratamientos antibióticos. Aunque cada caso aislado tenga un coste moderado, su elevada frecuencia hace que el impacto económico global sea considerable, lo que refuerza la eficiencia de las medidas preventivas. Las cifras de 2.000, 2.500 y 3.000 dólares no corresponden al dato recogido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977348") }, {"long_answer": "Según el documento del proyecto ITU-Zero, entre el 70% y el 80% de las infecciones del tracto urinario relacionadas con sonda uretral se consideran evitables mediante la aplicación de medidas preventivas sencillas: limitar la indicación del sondaje, insertar la sonda de forma aséptica, mantener un sistema de drenaje cerrado con la bolsa por debajo de la vejiga y retirarla en cuanto deje de ser necesaria. Este alto porcentaje de prevención es el fundamento del proyecto. Los intervalos inferiores propuestos en las demás opciones no corresponden al dato recogido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97734a") }, {"long_answer": "Se consideran infecciones adquiridas en la UCI aquellas que aparecen después de 48 horas de estancia en la unidad, ya que se asume que antes de ese plazo la infección podía estar en periodo de incubación en el momento del ingreso. Este criterio temporal, utilizado por el registro ENVIN-HELICS y por el proyecto ITU-Zero, permite diferenciar las infecciones relacionadas con la asistencia en la UCI de las adquiridas previamente. Los plazos de 12, 24 y 36 horas no corresponden a la definición establecida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97734c") }, {"long_answer": "Para el diagnóstico de infección urinaria relacionada con sonda en pacientes sin tratamiento antibiótico, el criterio microbiológico es un urocultivo con aislamiento de al menos 10^5 unidades formadoras de colonias por mililitro de no más de dos microorganismos, junto con la clínica compatible. Recuentos inferiores a 10^5 ufc/mL de un único microorganismo se aceptan en otras circunstancias, como en pacientes que ya reciben antibiótico. Recuentos de 10 o 50 ufc/mL son irrelevantes desde el punto de vista diagnóstico, y el aislamiento de tres o más microorganismos sugiere contaminación de la muestra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97734e") }, {"long_answer": "Según el informe del registro ENVIN de 2017, la ratio de utilización de sonda vesical en las UCI españolas, calculada como días de sondaje respecto al total de estancias, fue de 0,79, lo que significa que los pacientes llevaron sonda uretral durante aproximadamente el 79% de los días de ingreso. Este alto nivel de uso muestra el margen de mejora en la revisión diaria de la indicación y la retirada precoz que promueve el proyecto ITU-Zero. Los valores de 0,92, 0,65 y 0,55 no corresponden al dato del informe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977353") }, {"long_answer": "Entre 2012 y 2017 aumentó el porcentaje de pacientes con infección urinaria relacionada con sonda uretral en los que se aislaron bacilos gramnegativos productores de carbapenemasas, según los datos del registro ENVIN recogidos en el documento ITU-Zero. Esta tendencia refleja el avance de la multirresistencia en las UCI y refuerza la importancia de prevenir estas infecciones y de usar los antibióticos de forma adecuada. Por tanto no disminuyó ni permaneció estable, y el documento sí aporta información sobre esta evolución."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977358") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97735c") }, {"question": "¿Cuál de las siguientes es una indicación adecuada de sondaje uretral en el paciente crítico?", "option_3": "Facilitar la recogida de la orina en pacientes continentes por comodidad del personal", "long_answer": "La hematuria con coágulos es una indicación adecuada de sondaje uretral, ya que permite el drenaje y, si es necesario, la irrigación vesical para evitar la retención por obstrucción. Otras indicaciones aceptadas son la retención urinaria, la medición precisa de la diuresis en pacientes inestables o la cirugía urológica. Mantener el sistema colector por debajo de la vejiga es una medida de mantenimiento, no una indicación. Sondar a pacientes continentes por comodidad del personal es un uso inapropiado, y el sondaje intermitente es una alternativa al sondaje permanente, no una indicación de este."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97735d") }, {"long_answer": "El algoritmo de prevención de la infección urinaria relacionada con sonda uretral establece que, antes de la inserción, se realice higiene de manos y de la zona genitourinaria del paciente, para después insertar la sonda con técnica aséptica y material estéril. Los lavados vesicales rutinarios no se recomiendan porque aumentan el riesgo de infección al abrir el circuito. Conectar la sonda al sistema colector es un paso posterior a la inserción, y se debe elegir la sonda del menor calibre posible para reducir el traumatismo uretral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97735e") }, {"long_answer": "Una recomendación clave para el mantenimiento de la sonda uretral es revisar diariamente la indicación del sondaje, con el fin de retirar la sonda en cuanto deje de ser necesaria, ya que el riesgo de infección aumenta con cada día de permanencia. Los lavados vesicales rutinarios están desaconsejados porque abren el sistema cerrado. El sistema colector debe mantenerse siempre por debajo del nivel de la vejiga, nunca por encima, para evitar el reflujo, y cambiar semanalmente la zona de fijación no es la medida destacada para prevenir la infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977360") }, {"option_2": "Mantener siempre la bolsa colectora por debajo del nivel de la vejiga", "long_answer": "Uno de los puntos clave del proyecto ITU-Zero es mantener el circuito cerrado y permeable con la bolsa colectora siempre por debajo del nivel de la vejiga y sin contacto con el suelo, para favorecer el drenaje por gravedad y evitar el reflujo de orina contaminada hacia la vejiga. Colocar la bolsa por encima de la vejiga favorece precisamente ese reflujo. La presencia de úlceras por presión de categoría III o IV en la zona sacrocoxígea puede justificar el sondaje, pero no es una medida de prevención de la infección, y el sistema de drenaje debe mantenerse cerrado, nunca abierto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977363") }, {"option_1": "Retirar la sonda tan pronto como deje de estar indicada", "long_answer": "El proyecto ITU-Zero recomienda valorar diariamente la necesidad de mantener el sondaje urinario y retirar la sonda tan pronto como deje de estar indicada, porque la duración del sondaje es el principal factor de riesgo de infección urinaria asociada. Por tanto no valorar diariamente su necesidad o no retirarla cuando ya no es necesaria son prácticas contrarias a la recomendación. Mantener el sistema de drenaje abierto también es incorrecto, ya que el sistema debe permanecer cerrado para impedir la entrada de microorganismos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977364") }, {"long_answer": "La inserción aséptica de la sonda uretral, con higiene de manos, guantes y material estéril, preparación de la zona genital y técnica que evite la contaminación, es uno de los puntos clave del proyecto ITU-Zero para prevenir la infección urinaria relacionada con sonda. Los lavados vesicales rutinarios no se recomiendan porque obligan a abrir el sistema. No retirar la sonda cuando no es necesaria prolonga innecesariamente el riesgo, y la bolsa colectora debe colocarse siempre por debajo de la vejiga, no por encima, para mantener el circuito permeable y evitar el reflujo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977367") }, {"long_answer": "El protocolo de higiene de manos aplicado al cuidado del paciente con sonda urinaria, basado en las recomendaciones de la OMS, establece que la fricción de las manos con solución hidroalcohólica debe durar entre 20 y 30 segundos, tiempo suficiente para cubrir todas las superficies de las manos y lograr la reducción de la carga microbiana. Diez segundos son insuficientes para una higiene eficaz. Los 40 a 60 segundos corresponden al lavado con agua y jabón, y 90 segundos excede el tiempo recomendado para la higiene de manos habitual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977369") }, {"option_2": "Proteger al profesional sanitario y al entorno de los microorganismos del paciente", "option_4": "Evitar la necesidad de utilizar guantes durante los cuidados", "answer": 2, "long_answer": "Según los cinco momentos de la OMS, la higiene de manos después del contacto con el paciente tiene como finalidad proteger al profesional sanitario y al entorno asistencial de los microorganismos del paciente, evitando su diseminación a otras superficies y pacientes. Proteger al paciente de los microorganismos de las manos del profesional es el objetivo de la higiene antes del contacto con el paciente o antes de una tarea aséptica, como la manipulación de la sonda. La finalidad no se limita a las enfermedades gastrointestinales, y la higiene de manos nunca sustituye al uso de guantes cuando estos están indicados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97736e") }, {"long_answer": "El protocolo del proyecto Infección Quirúrgica Zero señala que cada año alrededor del 10% de la población española se somete a una intervención quirúrgica, lo que da idea del elevado número de pacientes expuestos al riesgo de infección de localización quirúrgica y justifica la importancia de aplicar medidas preventivas de forma sistemática. Las cifras del 5%, 15% y 20% no corresponden al dato recogido en el documento, ya sea por infravalorar o por sobreestimar la actividad quirúrgica anual."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977371") }, {"long_answer": "El proyecto IQZ propone dos estrategias generales para el éxito de la intervención preventiva: la implantación de un plan general de seguridad del paciente quirúrgico, que incluye el listado de verificación y la cultura de seguridad, y la aplicación de un programa general de vigilancia y control de riesgos clínicos, que permita medir las tasas de infección y retroalimentar los resultados. La vacunación, la desinfección de áreas, el uso de antibióticos o el control de la temperatura son medidas concretas o ajenas al proyecto, y el ejercicio físico y la dieta no forman parte de él."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977372") }, {"long_answer": "Entre las medidas preventivas generales que todo hospital debe tener para prevenir la infección quirúrgica se encuentra el establecimiento de normas de trabajo para el quirófano, que regulan aspectos como la circulación de personas, la vestimenta, la limpieza, la apertura de puertas o la asepsia, y que constituyen el marco sobre el que se aplican las medidas específicas. La higiene de manos se realiza preferentemente con solución hidroalcohólica, la mascarilla es solo un elemento de esas normas, y la povidona yodada no sustituye a la clorhexidina alcohólica, que es el antiséptico de elección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977376") }, {"question": "¿Cuál es la dosis estándar de cefuroxima en la profilaxis antibiótica quirúrgica del paciente adulto?", "option_1": "3 g", "option_2": "1,5 g", "option_3": "500 mg", "option_4": "250 mg", "answer": 2, "long_answer": "La dosis estándar de cefuroxima en la profilaxis antibiótica quirúrgica del adulto es de 1,5 g por vía intravenosa, administrada dentro de los 60 minutos previos a la incisión, con redosificación si la intervención se prolonga más allá de la vida media del fármaco o hay una pérdida hemática importante. La adecuación de la profilaxis, en fármaco, dosis, momento y duración, es una de las medidas obligatorias del proyecto IQZ. La dosis de 3 g supera la habitual, y las de 500 mg o 250 mg son insuficientes para alcanzar concentraciones tisulares eficaces durante la cirugía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97737e") }, {"long_answer": "En el protocolo IQZ, la recomendación de mantener la normotermia perioperatoria para prevenir la infección de localización quirúrgica se apoya en un nivel de evidencia alto, procedente de ensayos clínicos que demostraron que la hipotermia aumenta las infecciones de la herida, además de otras complicaciones como la coagulopatía o la mayor necesidad de transfusión. Por ello se incluye en el paquete de medidas STOP-ILQ. Calificarla con evidencia moderada, baja o muy baja no se corresponde con la graduación recogida en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977380") }, {"long_answer": "Uno de los puntos críticos para mantener la normotermia es la medición periódica de la temperatura corporal del paciente antes y después de la intervención, que permite detectar la hipotermia y aplicar medidas de calentamiento activo, como mantas de aire caliente o calentamiento de fluidos. La temperatura ambiente del quirófano no debe mantenerse por debajo de 22 ºC con el objetivo de la normotermia, ya que eso favorece la pérdida de calor. El control de la glucemia por debajo de 150 mg/dl es un punto crítico de la normoglucemia, no de la normotermia, por lo que la opción ninguna de las anteriores también es incorrecta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977381") }, {"long_answer": "En el protocolo IQZ, la recomendación de mantener la normoglucemia perioperatoria para prevenir la infección de localización quirúrgica se clasifica con un nivel de evidencia alto, ya que diversos estudios han demostrado que la hiperglucemia, en pacientes diabéticos y no diabéticos, aumenta el riesgo de infección. Por ello forma parte de las medidas del proyecto. Los niveles moderado, bajo o muy bajo no corresponden a la graduación recogida en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977386") }, {"long_answer": "Para participar en el proyecto IQZ, todo el personal sanitario directamente implicado en las intervenciones preventivas, como cirujanos, anestesiólogos y profesionales de enfermería del bloque quirúrgico y de las plantas, debe realizar como formación mínima el curso en línea STOP-ILQ, que explica las medidas del paquete y su registro. La formación no es opcional, ya que es requisito para la correcta implantación. No se exige a todos los profesionales del hospital independientemente de su área, y los coordinadores reciben además una formación presencial específica, por lo que no son los únicos que deben formarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97738b") }, {"answer": 2, "long_answer": "La hipotermia perioperatoria se asocia a coagulopatía, con mayor sangrado y necesidad de transfusión, aumento de la infección de la herida quirúrgica por vasoconstricción y alteración inmunitaria, retraso en el metabolismo de los fármacos con despertar prolongado, temblores con aumento del consumo de oxígeno y disconfort térmico. La primera opción es incorrecta porque la hipotermia supone un descenso, no un aumento, de la temperatura. La tercera describe consecuencias del ayuno prolongado y del estrés quirúrgico, y la cuarta mezcla mecanismos de pérdida de calor con un concepto erróneo, ya que la producción metabólica genera calor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97738c") }, {"long_answer": "Existe una recomendación fuerte a favor de calentar los líquidos intravenosos utilizados durante la cirugía a una temperatura de entre 37 y 41 ºC, ya que reduce la caída de la temperatura central y contribuye a prevenir la hipotermia perioperatoria y sus complicaciones, incluida la infección de localización quirúrgica, especialmente cuando se infunden volúmenes importantes. Calentarlos solo a 36 ºC resulta insuficiente, ya que sería inferior a la temperatura corporal, y una única cifra de 38 ºC no corresponde al rango recomendado. No calentarlos contradice la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97738d") }, {"question": "¿Cuál es la recomendación actual sobre el ayuno preoperatorio en cirugía programada?", "option_1": "Ayuno de 12 horas para líquidos claros y 8 horas para alimentos sólidos", "option_2": "Ayuno de 6 horas para líquidos claros y 2 horas para alimentos sólidos", "option_3": "Ayuno de 2 horas para líquidos claros y 6 horas para alimentos sólidos", "long_answer": "La recomendación actual en cirugía programada es un ayuno de 2 horas para los líquidos claros y de 6 horas para los alimentos sólidos, intervalos suficientes para garantizar el vaciamiento gástrico y prevenir la broncoaspiración, evitando a la vez los efectos negativos del ayuno prolongado, como la deshidratación, la hipoglucemia, el catabolismo o el malestar del paciente. Un ayuno de 12 horas para líquidos y 8 para sólidos es excesivo e innecesario. La segunda opción invierte los tiempos, ya que los sólidos requieren más tiempo de vaciamiento que los líquidos, y sí existe una recomendación específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97738e") }, {"option_3": "Sustituir la profilaxis antibiótica preoperatoria", "long_answer": "El tratamiento preoperatorio con hidratos de carbono complejos por vía oral tiene como propósito reducir el catabolismo asociado al ayuno y a la cirugía, de modo que el paciente llegue a la intervención en un estado metabólico alimentado, con menor resistencia a la insulina y mejor conservación de la masa muscular. Por tanto no aumenta la resistencia a la insulina, sino que la disminuye. No sustituye en ningún caso a la profilaxis antibiótica, que es una medida independiente, y la mejora de la respuesta inmunológica no es el propósito principal que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97738f") }, {"option_1": "Eliminación de la necesidad de anestesia", "long_answer": "El aporte de bebidas carbohidratadas claras hasta dos horas antes de una cirugía programada induce una sensación de bienestar en el paciente, al reducir la sed, el hambre y la ansiedad propias del ayuno, además de atenuar la resistencia a la insulina. Este es el beneficio que destaca el documento con mayor consistencia. No elimina la necesidad de anestesia, la evidencia sobre una reducción de las complicaciones postoperatorias no es concluyente, y su objetivo no es aumentar la tasa de infusión de glucosa, sino evitar el estado de ayuno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977391") }, {"long_answer": "En la cesárea, cuando el tejido celular subcutáneo tiene un grosor mayor de 2 centímetros, su sutura reduce el riesgo de complicaciones de la herida quirúrgica, como seroma, hematoma, dehiscencia e infección, al eliminar el espacio muerto donde se acumulan líquidos. Por tanto no aumenta el riesgo de hematoma ni incrementa la pérdida hemática, y afirmar que no tiene ningún efecto contradice la evidencia en la que se basa esta recomendación de las guías de prevención de la infección quirúrgica en cirugía obstétrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977396") }, {"long_answer": "La cumplimentación del listado de verificación quirúrgica de la OMS es una de las principales medidas de seguridad del paciente quirúrgico, ya que estructura la comprobación de la identidad del paciente, el sitio quirúrgico, el procedimiento, la profilaxis antibiótica, el equipamiento y el recuento de material en tres momentos de la intervención, reduciendo complicaciones y mortalidad. La realización de exámenes radiológicos no es una medida de seguridad en sí misma, y administrar medicación sin etiquetar u omitir la profilaxis antibiótica son prácticas inseguras que precisamente se pretenden evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca977399") }, {"long_answer": "La formación en seguridad del paciente se enfoca en reducir la probabilidad de que un paciente sufra un error o un evento adverso derivado de la asistencia, mediante el conocimiento de los factores que los favorecen, la cultura de seguridad, la notificación y el aprendizaje de los incidentes y el uso de herramientas como el listado de verificación quirúrgica. El enfoque sistémico de las organizaciones busca la seguridad más que la eficiencia, la comunicación con los pacientes es solo uno de sus componentes y aprender a usar herramientas quirúrgicas de última generación no es el objetivo de esta formación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97739a") }, {"long_answer": "Para identificar, analizar y priorizar los problemas clínicos u organizativos de seguridad en los bloques quirúrgicos se recomienda realizar sesiones con los miembros del propio bloque quirúrgico, de forma que los profesionales que trabajan a diario en él aporten su experiencia, consensúen las prioridades y se impliquen en las soluciones. Las entrevistas individuales no permiten el análisis conjunto, el cuestionario de seguridad mide la cultura de seguridad más que priorizar problemas concretos, y la encuesta de satisfacción del paciente no está orientada a detectar problemas clínicos u organizativos internos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97739c") }, {"long_answer": "Durante la fase piloto, los puntos débiles en el desarrollo del programa se identifican en las sesiones mensuales de evaluación del programa, en las que los responsables y los profesionales revisan los datos de cumplimiento, los problemas detectados en la aplicación de las medidas y las propuestas de mejora, siguiendo la lógica del ciclo de mejora continua. Las entrevistas individuales, las encuestas de satisfacción del paciente o la revisión de registros administrativos no constituyen el mecanismo establecido para evaluar el desarrollo del programa en esta fase."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97739d") }, {"long_answer": "Entre las variables que se incluyen en la recogida de datos del proyecto de seguridad del paciente quirúrgico se encuentra la adecuación de la profilaxis tromboembólica, ya que la enfermedad tromboembólica venosa es una complicación prevenible y frecuente en el paciente quirúrgico, y su profilaxis forma parte de las prácticas seguras evaluadas, junto con la profilaxis antibiótica o el listado de verificación. El nivel de satisfacción del personal, el número de pacientes atendidos en urgencias o la cantidad de material quirúrgico utilizado no son variables de este proyecto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca97739f") }, {"long_answer": "Para la realización de informes dirigidos a los servicios y a la Dirección del hospital se recomienda que el coordinador del centro presente los resultados del programa, lo que favorece la retroalimentación a los profesionales, el compromiso de la dirección y la toma de decisiones para la mejora. El análisis estadístico y los informes no corresponden al personal de limpieza. La mecanización de datos en hojas de cálculo es una herramienta de trabajo, no la recomendación para informar, y el envío de información al centro coordinador es una comunicación externa, no un informe a los servicios y la Dirección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a3") }, {"long_answer": "La fase del listado de verificación quirúrgica de la OMS que se realiza antes de la inducción de la anestesia incluye la confirmación de la identidad del paciente, el sitio quirúrgico, el procedimiento y el consentimiento, el marcado del sitio, la verificación del equipamiento y la medicación anestésica, el pulsioxímetro y la valoración de alergias, vía aérea difícil y riesgo de hemorragia. La revisión de los pasos críticos del procedimiento corresponde a la pausa quirúrgica antes de la incisión, y el recuento de instrumental, el etiquetado de muestras y la recuperación del paciente pertenecen a la fase previa a la salida del quirófano."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773a9") }, {"question": "¿A partir de qué puntuación se considera alto riesgo de sangrado en la escala de evaluación de riesgo hemorrágico IMPROVE?", "option_1": "7 o más puntos", "option_2": "0 puntos", "option_3": "1 punto", "option_4": "Entre 2 y 4 puntos", "long_answer": "La escala IMPROVE de riesgo hemorrágico, utilizada en pacientes médicos y quirúrgicos para decidir sobre la profilaxis tromboembólica farmacológica, suma puntos según factores como úlcera gastroduodenal activa, sangrado reciente, plaquetopenia, edad avanzada, insuficiencia renal o hepática y estancia en UCI. Una puntuación de 7 o más puntos indica alto riesgo de sangrado, en cuyo caso se prefieren medidas mecánicas frente a la anticoagulación profiláctica. Las puntuaciones de 0, 1 o entre 2 y 4 puntos se sitúan por debajo del punto de corte y corresponden a un riesgo bajo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773ae") }, {"long_answer": "Mantener una oxigenación tisular adecuada en el perioperatorio tiene como objetivo disminuir la tasa de infecciones postoperatorias, ya que el oxígeno es necesario para la actividad bactericida de los neutrófilos mediante el estallido oxidativo y para la cicatrización de la herida. Prevenir la broncoaspiración durante la inducción es el objetivo del ayuno preoperatorio, mientras que mejorar el bienestar del paciente y evitar la hipoglucemia y la deshidratación son objetivos de la administración preoperatoria de bebidas carbohidratadas y del ayuno corto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773af") }, {"long_answer": "El documento recomienda un ayuno preoperatorio de 2 horas para los líquidos claros, como agua, infusiones, zumos sin pulpa o bebidas carbohidratadas, ya que se vacían rápidamente del estómago y no aumentan el riesgo de broncoaspiración, mientras que evitan la deshidratación, la sed y la hipoglucemia. Ayunos de 4, 6 u 8 horas para los líquidos claros son innecesariamente prolongados; el intervalo de 6 horas corresponde a los alimentos sólidos ligeros, y periodos más largos se reservan para comidas copiosas o grasas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b1") }, {"long_answer": "Tradicionalmente se recomendaba un ayuno prolongado desde la medianoche anterior a la cirugía para prevenir la broncoaspiración del contenido gástrico tras la inducción anestésica, al considerar que un estómago vacío reducía ese riesgo. La evidencia ha demostrado que ayunos más cortos son igual de seguros. Evitar el catabolismo y la hiperglucemia es precisamente el argumento actual para acortar el ayuno, las guías actuales no recomiendan el ayuno prolongado y el riesgo de deshidratación es una consecuencia negativa del ayuno, no un motivo para prolongarlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b3") }, {"long_answer": "La recomendación para el ayuno preoperatorio de alimentos sólidos en cirugía programada es de 6 horas, tiempo suficiente para el vaciamiento gástrico de una comida ligera y para minimizar el riesgo de broncoaspiración durante la inducción anestésica. Dos horas es el intervalo establecido para los líquidos claros, no para los sólidos, y cuatro horas resulta insuficiente para ellos. Un ayuno de 8 horas solo se recomienda tras comidas copiosas o ricas en grasas, por lo que no constituye la recomendación general."});
rm('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b5") });
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773b7") }, {"long_answer": "Para la prevención de la infección de la herida quirúrgica, el documento recomienda que el paciente realice una ducha preoperatoria con jabón antiséptico de clorhexidina la noche anterior a la intervención, con el fin de reducir la carga bacteriana de la piel antes de la preparación del campo quirúrgico. La ducha con jabón convencional reduce menos la colonización cutánea, y realizarla el mismo día de la intervención no es la pauta establecida en el documento. Esta medida complementa, pero no sustituye, a la antisepsia del campo con clorhexidina alcohólica en el quirófano."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c0") }, {"long_answer": "El objetivo general del Protocolo común para la actuación sanitaria frente a la violencia sexual es establecer criterios comunes de actuación profesional, normalizada y homogénea en el conjunto del Sistema Nacional de Salud para la detección, valoración e intervención ante la violencia sexual, pasada o reciente, en mujeres adultas, niñas, niños y adolescentes. Sensibilizar y formar al personal sanitario, promover el empoderamiento de las víctimas o actualizar el conocimiento son objetivos específicos o principios que contribuyen a ese fin, pero no constituyen el objetivo general del protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c4") }, {"long_answer": "Entre los principios generales y aspectos transversales del protocolo común frente a la violencia sexual figura la atención interprofesional e intersectorial, que implica la participación coordinada de distintos profesionales y sectores para ofrecer una respuesta integral a la víctima. Otros principios son el enfoque de derechos humanos, de género e interseccional, la seguridad y la confidencialidad, la accesibilidad y la continuidad asistencial. La confidencialidad no es opcional, la mala coordinación entre servicios es lo que se pretende evitar y la falta de accesibilidad universal contradice el principio de accesibilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c5") }, {"long_answer": "El protocolo incluye la promoción de la salud sexual como forma de prevención de la violencia sexual, y uno de sus conceptos centrales es fomentar la corresponsabilidad en las relaciones sexuales, basada en el consentimiento, el respeto, la igualdad y el cuidado mutuo, implicando a ambas partes en la prevención de riesgos. Promover riesgos asociados al comportamiento sexual es lo contrario del objetivo. Limitar la información sobre sexualidad dificulta la toma de decisiones informadas, y un enfoque exclusivo en el embarazo deja fuera el placer, las infecciones de transmisión sexual y las relaciones igualitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063d0ee40273ca9773c8") }, {"long_answer": "Entre las consecuencias específicas de la violencia sexual en la adolescencia el protocolo señala las conductas sexuales de riesgo, como las relaciones sexuales sin protección, con mayor riesgo de infecciones de transmisión sexual y embarazos no deseados, además de la hipersexualización, el consumo de sustancias, las autolesiones o el fracaso escolar. Por tanto no se asocia a un aumento del rendimiento académico, que suele empeorar, ni a una reducción del riesgo de abuso de sustancias o de comportamientos hipersexualizados, que por el contrario aumentan."});
print(`\nParte terminada: ${ok} corregidas, ${del} borradas, ${warn} avisos.`);
